-- ─── 3. Functions (90) ──────────────────────────────────────────
-- public._employee_advance_cash_leg
CREATE OR REPLACE FUNCTION public._employee_advance_cash_leg(p_tenant uuid, p_account uuid, p_date date, p_debit integer, p_credit integer, p_text text, p_adv uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if p_account is null then return null; end if;
  if not exists (select 1 from public.bank_accounts
                  where id = p_account and tenant_id = p_tenant and account_type = 'cash') then
    return null;   -- a bank / UPI account: matched from the statement in Banking instead
  end if;
  insert into public.bank_transactions
    (tenant_id, bank_account_id, txn_date, description, debit, credit, source,
     matched_to_type, matched_to_id, match_confidence, matched_at, matched_by)
  values
    (p_tenant, p_account, p_date, p_text, p_debit, p_credit, 'manual',
     'prepaid', p_adv::text, 'manual', now(), public.current_user_id())
  returning id into v_id;
  return v_id;
end $function$;

-- public.academy_my_apprentice_id
CREATE OR REPLACE FUNCTION public.academy_my_apprentice_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select a.id from public.academy_apprentices a where a.user_id = public.current_user_id() limit 1;
$function$;

-- public.academy_my_tenant_id
CREATE OR REPLACE FUNCTION public.academy_my_tenant_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select a.tenant_id from public.academy_apprentices a where a.user_id = public.current_user_id() limit 1;
$function$;

-- public.academy_review_task
CREATE OR REPLACE FUNCTION public.academy_review_task(p_task_id uuid, p_result text, p_feedback text, p_marks integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_task public.academy_tasks; v_sub uuid; v_fb text := nullif(trim(coalesce(p_feedback, '')), '');
begin
  if p_result not in ('approved', 'rework') then raise exception 'Choose approve or rework.'; end if;
  select * into v_task from public.academy_tasks where id = p_task_id for update;
  if not found or not public.academy_staff_sees(v_task.apprentice_id) then raise exception 'Task not found.'; end if;
  if v_task.status <> 'submitted' then raise exception 'Only a submitted task can be reviewed.'; end if;
  if p_result = 'rework' and v_fb is null then raise exception 'Say what to fix — rework needs feedback.'; end if;
  if p_marks is not null and (p_marks < 0 or p_marks > 100) then raise exception 'Marks are out of 100.'; end if;

  select id into v_sub from public.academy_submissions where task_id = p_task_id order by attempt desc limit 1;
  update public.academy_submissions
     set review_result = p_result, feedback = v_fb, marks = p_marks, reviewed_by = public.current_user_id(), reviewed_at = now()
   where id = v_sub;
  update public.academy_tasks
     set status = case when p_result = 'approved' then 'completed' else 'rework' end,
         completed_at = case when p_result = 'approved' then now() else null end
   where id = p_task_id;
end $function$;

-- public.academy_staff_sees
CREATE OR REPLACE FUNCTION public.academy_staff_sees(p_apprentice_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.academy_apprentices a
     where a.id = p_apprentice_id
       and a.tenant_id = public.current_tenant_id()
       and (public.academy_can_manage() or a.mentor_user_id = public.current_user_id())
  );
$function$;

-- public.add_reimbursement
CREATE OR REPLACE FUNCTION public.add_reimbursement(p_person text, p_purpose text, p_category text, p_amount integer, p_gst integer, p_incurred_on date, p_paid_via text, p_employee_id uuid DEFAULT NULL::uuid, p_receipt_path text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_cat    text := coalesce(nullif(trim(p_category), ''), 'Other');
  v_via    text := nullif(trim(coalesce(p_paid_via, '')), '');
  v_exp_id text;
  v_id     uuid;
begin
  if v_tenant is null then raise exception 'No tenant context'; end if;
  if p_amount is null or p_amount <= 0 then raise exception 'Amount must be greater than 0'; end if;
  if coalesce(trim(p_person), '') = '' then raise exception 'Who paid? — person name is required'; end if;
  if coalesce(trim(p_purpose), '') = '' then raise exception 'What was it for? — purpose is required'; end if;

  if p_employee_id is not null then
    perform 1 from public.employees where id = p_employee_id and tenant_id = v_tenant;
    if not found then raise exception 'Employee not found'; end if;
  end if;

  v_exp_id := 'EXP-' || upper(to_hex((extract(epoch from clock_timestamp()) * 1000)::bigint)) || '-' || upper(to_hex((random() * 255)::int));
  insert into public.expenses (id, tenant_id, category, vendor_name, expense_date, amount, gst_paid, payment_method, description)
  values (v_exp_id, v_tenant, v_cat, trim(p_person), coalesce(p_incurred_on, current_date), p_amount, greatest(coalesce(p_gst, 0), 0), 'reimbursement',
          'Reimbursement · ' || p_purpose || ' · paid by ' || trim(p_person) || coalesce(' (' || v_via || ')', ''));

  insert into public.reimbursements (tenant_id, person_name, purpose, category, amount, gst_paid, incurred_on, paid_via, employee_id, receipt_path, expense_id, created_by)
  values (v_tenant, trim(p_person), trim(p_purpose), v_cat, p_amount, greatest(coalesce(p_gst, 0), 0), coalesce(p_incurred_on, current_date), v_via,
          p_employee_id, nullif(trim(coalesce(p_receipt_path, '')), ''), v_exp_id, public.current_user_id())
  returning id into v_id;
  return v_id;
end;
$function$;

-- public.auto_backup_if_stale
CREATE OR REPLACE FUNCTION public.auto_backup_if_stale()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_role text; v_last timestamptz;
begin
  select tenant_id, role into v_tenant, v_role from public.users where id = public.current_user_id();
  if v_tenant is null or coalesce(v_role,'') <> 'owner' then return jsonb_build_object('created', false); end if;
  select max(created_at) into v_last from backup.snapshots where tenant_id = v_tenant;
  if v_last is not null and v_last > now() - interval '20 hours' then
    return jsonb_build_object('created', false);
  end if;
  perform backup._take(v_tenant, 'Auto (daily)', 'auto');
  return jsonb_build_object('created', true);
end $function$;

-- public.backup_tenant
CREATE OR REPLACE FUNCTION public.backup_tenant(p_tenant uuid, p_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role  text := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '');
  v_name  text;
  v_label text := coalesce(nullif(btrim(p_label), ''),
                           'Automated Daily Backup - ' || to_char(now() at time zone 'Asia/Kolkata', 'YYYY-MM-DD'));
  v_snap  jsonb;
begin
  /* Doosra pehra (asli deewar grant hai). Ye kisi bhi tenant ka snapshot le sakta hai —
     browser session se kabhi nahi chalna chahiye. */
  if public.current_user_id() is not null or v_role in ('authenticated', 'anon') then
    raise exception 'backup_tenant is service_role only';
  end if;

  select name into v_name from public.tenants where id = p_tenant;
  if not found then
    raise exception 'backup_tenant: tenant % nahi mila — tenants list dobara padho (shayad abhi delete hua)', p_tenant;
  end if;

  v_snap := backup._take(p_tenant, v_label, 'auto');
  return v_snap || jsonb_build_object('tenant_id', p_tenant, 'tenant_name', v_name, 'label', v_label);
end;
$function$;

-- public.book_bank_advance
CREATE OR REPLACE FUNCTION public.book_bank_advance(p_txn_id uuid, p_counterparty text, p_kind text DEFAULT 'given'::text, p_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant  uuid := public.current_tenant_id();
  v_txn     public.bank_transactions;
  v_amount  int;
  v_section text;
  v_label   text;
  v_party   text;
begin
  if v_tenant is null then raise exception 'No tenant context'; end if;

  select * into v_txn from public.bank_transactions where id = p_txn_id and tenant_id = v_tenant;
  if not found then raise exception 'Bank transaction not found'; end if;
  if v_txn.matched_to_type is not null then
    raise exception 'This line is already reconciled';
  end if;

  v_party := nullif(trim(coalesce(p_counterparty, '')), '');

  if p_kind = 'given' then
    v_section := 'asset';
    if coalesce(v_txn.debit, 0) > 0 then
      v_amount := v_txn.debit;
      v_label  := 'Advance/loan given' || coalesce(' · ' || v_party, '');
    elsif coalesce(v_txn.credit, 0) > 0 then
      v_amount := -v_txn.credit;
      v_label  := 'Advance/loan returned' || coalesce(' · ' || v_party, '');
    else
      raise exception 'Transaction has no amount';
    end if;
  elsif p_kind = 'received' then
    v_section := 'liability';
    if coalesce(v_txn.credit, 0) > 0 then
      v_amount := v_txn.credit;
      v_label  := 'Loan received' || coalesce(' · ' || v_party, '');
    elsif coalesce(v_txn.debit, 0) > 0 then
      v_amount := -v_txn.debit;
      v_label  := 'Loan repaid' || coalesce(' · ' || v_party, '');
    else
      raise exception 'Transaction has no amount';
    end if;
  else
    raise exception 'Unknown kind: %', p_kind;
  end if;

  insert into public.balance_sheet_items (tenant_id, section, label, amount, notes, bank_txn_id)
  values (v_tenant, v_section, v_label, v_amount, nullif(trim(coalesce(p_notes, '')), ''), p_txn_id);

  update public.bank_transactions
     set matched_to_type = 'manual', matched_to_id = null,
         matched_at = now(), matched_by = public.current_user_id(), match_confidence = 'manual',
         updated_at = now()
   where id = p_txn_id;
end;
$function$;

-- public.book_bank_credit
CREATE OR REPLACE FUNCTION public.book_bank_credit(p_txn_id uuid, p_kind text, p_label text, p_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant  uuid := public.current_tenant_id();
  v_txn     public.bank_transactions;
  v_section text;
  v_label   text;
begin
  if v_tenant is null then raise exception 'No tenant context'; end if;

  select * into v_txn from public.bank_transactions where id = p_txn_id and tenant_id = v_tenant;
  if not found then raise exception 'Bank transaction not found'; end if;
  if coalesce(v_txn.credit, 0) <= 0 then
    raise exception 'This is only for money-in (credit) lines';
  end if;
  if v_txn.matched_to_type is not null then
    raise exception 'This line is already reconciled';
  end if;

  v_section := case p_kind
                 when 'capital'       then 'equity'
                 when 'director_loan' then 'liability'
                 else null end;
  if v_section is null then raise exception 'Unknown kind: %', p_kind; end if;

  v_label := coalesce(nullif(trim(p_label), ''),
                      case p_kind when 'capital' then 'Owner''s capital' else 'Director''s loan' end);

  insert into public.balance_sheet_items (tenant_id, section, label, amount, notes, bank_txn_id)
  values (v_tenant, v_section, v_label, v_txn.credit, nullif(trim(coalesce(p_notes, '')), ''), p_txn_id);

  update public.bank_transactions
     set matched_to_type = 'manual', matched_to_id = null,
         matched_at = now(), matched_by = public.current_user_id(), match_confidence = 'manual',
         updated_at = now()
   where id = p_txn_id;
end;
$function$;

-- public.book_bank_txn_as_expense
CREATE OR REPLACE FUNCTION public.book_bank_txn_as_expense(p_txn_id uuid, p_category text, p_vendor text, p_gst integer, p_notes text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_txn    public.bank_transactions;
  v_exp_id text;
begin
  if trim(coalesce(p_category, '')) = '' then
    raise exception 'Please choose a category';
  end if;
  select * into v_txn from public.bank_transactions
    where id = p_txn_id and tenant_id = v_tenant;
  if not found then raise exception 'Transaction not found'; end if;
  if coalesce(v_txn.debit, 0) <= 0 then
    raise exception 'Only a money-out (debit) line can be booked as an expense';
  end if;
  if v_txn.matched_to_type is not null then
    raise exception 'This line is already reconciled';
  end if;
  v_exp_id := 'EXP-' || upper(to_hex((extract(epoch from clock_timestamp()) * 1000)::bigint))
                     || '-' || upper(to_hex((random() * 255)::int));
  insert into public.expenses
    (id, tenant_id, category, vendor_name, expense_date, amount, gst_paid, payment_method, description,
     paid, paid_date, bank_account_id, reconciled_txn_id)
  values
    (v_exp_id, v_tenant, trim(p_category), nullif(trim(coalesce(p_vendor, '')), ''),
     v_txn.txn_date, v_txn.debit, greatest(coalesce(p_gst, 0), 0), 'bank',
     coalesce(nullif(trim(coalesce(p_notes, '')), ''), v_txn.description),
     true, v_txn.txn_date, v_txn.bank_account_id, p_txn_id);
  update public.bank_transactions
     set matched_to_type = 'expense', matched_to_id = v_exp_id, match_confidence = 'manual',
         matched_at = now(), matched_by = public.current_user_id()
   where id = p_txn_id and tenant_id = v_tenant;
  return v_exp_id;
end;
$function$;

-- public.book_bank_txn_as_prepaid
CREATE OR REPLACE FUNCTION public.book_bank_txn_as_prepaid(p_txn_id uuid, p_vendor_name text, p_category text DEFAULT 'Advertising'::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_txn    public.bank_transactions;
  v_id     uuid;
begin
  if v_tenant is null then raise exception 'No company context — sign in again.'; end if;
  if nullif(trim(coalesce(p_vendor_name, '')), '') is null then
    raise exception 'Enter who the advance was paid to (e.g. Facebook).';
  end if;
  if nullif(trim(coalesce(p_category, '')), '') is null or p_category = 'Salaries' then
    raise exception 'Pick the expense category this advance will be used for.';
  end if;

  select * into v_txn from public.bank_transactions where id = p_txn_id and tenant_id = v_tenant;
  if not found then raise exception 'Bank line not found in your company.'; end if;
  if v_txn.matched_to_type is not null then raise exception 'This bank line is already reconciled — un-reconcile it first.'; end if;
  if coalesce(v_txn.debit, 0) <= 0 then raise exception 'An advance paid out must be a money-out line.'; end if;

  insert into public.prepaid_advances
    (tenant_id, vendor_name, category, total_amount, consumed_amount, paid_date, payment_method,
     bank_account_id, notes, created_by, bank_txn_id)
  values
    (v_tenant, trim(p_vendor_name), p_category, v_txn.debit, 0, v_txn.txn_date, 'bank_transfer',
     v_txn.bank_account_id, coalesce(nullif(trim(coalesce(p_notes, '')), ''), v_txn.description), public.current_user_id(), p_txn_id)
  returning id into v_id;

  update public.bank_transactions
     set matched_to_type = 'prepaid', matched_to_id = v_id::text, match_confidence = 'manual',
         matched_at = now(), matched_by = public.current_user_id(), updated_at = now()
   where id = p_txn_id;

  return v_id;
end;
$function$;

-- public.book_bank_txn_as_referral_commission
CREATE OR REPLACE FUNCTION public.book_bank_txn_as_referral_commission(p_txn_id uuid, p_commission_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_txn public.bank_transactions;
  v_comm public.referral_commissions;
  v_synth uuid;
begin
  if v_tenant is null then raise exception 'No tenant context'; end if;
  select * into v_txn from public.bank_transactions where id = p_txn_id and tenant_id = v_tenant for update;
  if not found then raise exception 'Bank transaction not found'; end if;
  if v_txn.matched_to_type is not null then raise exception 'This line is already reconciled'; end if;
  if coalesce(v_txn.debit, 0) <= 0 then raise exception 'A commission payment must be a money-out line'; end if;

  select * into v_comm from public.referral_commissions where id = p_commission_id and tenant_id = v_tenant for update;
  if not found then raise exception 'Commission not found'; end if;
  if v_comm.status = 'cancelled' then raise exception 'Commission is cancelled'; end if;
  if v_txn.debit <> v_comm.net_payable then
    raise exception 'Line (%) is not the commission''s net payable (%) — commissions are paid in full', v_txn.debit, v_comm.net_payable;
  end if;

  select id into v_synth from public.bank_transactions
   where tenant_id = v_tenant and id <> p_txn_id and source = 'manual'
     and matched_to_type = 'referral_commission' and matched_to_id = p_commission_id::text
   order by abs(txn_date - v_txn.txn_date) limit 1;

  if v_synth is not null then
    delete from public.bank_transactions where id = v_synth;
  elsif v_comm.status = 'paid' then
    raise exception 'Commission already paid (and its bank line is not a synthetic one) — un-reconcile that first';
  end if;

  update public.referral_commissions
     set status = 'paid', paid_date = coalesce(paid_date, v_txn.txn_date), pay_txn_id = p_txn_id
   where id = p_commission_id;

  update public.bank_transactions
     set matched_to_type = 'referral_commission', matched_to_id = p_commission_id::text, match_confidence = 'manual',
         matched_at = now(), matched_by = public.current_user_id(), updated_at = now()
   where id = p_txn_id;

  return jsonb_build_object('commission_id', p_commission_id, 'replaced_synthetic', v_synth, 'amount', v_txn.debit);
end; $function$;

-- public.book_bank_txn_as_statutory
CREATE OR REPLACE FUNCTION public.book_bank_txn_as_statutory(p_txn_id uuid, p_kind text, p_notes text DEFAULT NULL::text, p_challan_no text DEFAULT NULL::text, p_period text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_txn public.bank_transactions;
begin
  if v_tenant is null then raise exception 'No tenant context'; end if;
  select * into v_txn from public.bank_transactions where id = p_txn_id and tenant_id = v_tenant;
  if not found then raise exception 'Bank transaction not found'; end if;
  if v_txn.matched_to_type is not null then raise exception 'This line is already reconciled'; end if;
  if coalesce(v_txn.debit,0) <= 0 then raise exception 'A statutory payment must be a money-out line'; end if;

  insert into public.statutory_dues_payments (tenant_id, kind, amount, paid_on, bank_account_id, notes, bank_txn_id, challan_no, period)
  values (v_tenant, coalesce(nullif(p_kind,''),'mixed'), v_txn.debit, v_txn.txn_date, v_txn.bank_account_id,
          nullif(trim(coalesce(p_notes,'')),''), p_txn_id,
          nullif(trim(coalesce(p_challan_no,'')),''), nullif(trim(coalesce(p_period,'')),''));

  update public.bank_transactions
     set matched_to_type='statutory', matched_to_id=null, match_confidence='manual',
         matched_at=now(), matched_by=public.current_user_id(), updated_at=now()
   where id = p_txn_id;
end; $function$;

-- public.book_bank_txn_as_tax
CREATE OR REPLACE FUNCTION public.book_bank_txn_as_tax(p_txn_id uuid, p_kind text, p_period text DEFAULT NULL::text, p_fy text DEFAULT NULL::text, p_interest integer DEFAULT 0, p_late_fee integer DEFAULT 0, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant   uuid := public.current_tenant_id();
  v_txn      public.bank_transactions;
  v_interest integer := coalesce(p_interest, 0);
  v_late     integer := coalesce(p_late_fee, 0);
  v_tax      integer;
  v_exp_id   text;
  v_id       uuid;
  v_label    text;
begin
  if v_tenant is null then raise exception 'No company context — sign in again.'; end if;
  if p_kind not in ('gst', 'advance_tax', 'self_assessment_tax') then
    raise exception 'Unknown tax type "%" — pick GST, advance tax or self-assessment tax.', p_kind;
  end if;

  select * into v_txn from public.bank_transactions where id = p_txn_id and tenant_id = v_tenant;
  if not found then raise exception 'Bank line not found in your company.'; end if;
  if v_txn.matched_to_type is not null then raise exception 'This bank line is already reconciled — un-reconcile it first.'; end if;
  if coalesce(v_txn.debit, 0) <= 0 then raise exception 'A tax payment must be a money-out line.'; end if;

  if v_interest < 0 or v_late < 0 then raise exception 'Interest and late fee cannot be negative.'; end if;
  v_tax := v_txn.debit - v_interest - v_late;
  if v_tax <= 0 then
    raise exception 'Interest + late fee (₹%) leave no tax out of this ₹% line — check the amounts.', v_interest + v_late, v_txn.debit;
  end if;

  if p_kind = 'gst' then
    if p_period is null or p_period !~ '^\d{4}-(0[1-9]|1[0-2])$' then
      raise exception 'Pick the GST return month this payment is for.';
    end if;
    v_label := 'GST ' || p_period;
  else
    if p_fy is null or p_fy !~ '^\d{4}-\d{2}$'
       or (split_part(p_fy, '-', 1)::int + 1) % 100 <> split_part(p_fy, '-', 2)::int then
      raise exception 'Pick the financial year, e.g. 2026-27.';
    end if;
    v_label := case p_kind when 'advance_tax' then 'Advance tax FY ' else 'Self-assessment tax FY ' end || p_fy;
  end if;

  /* Interest and late fee are expenses — booked, paid from this account, and tied to
     this line so they never show as an unreconciled expense. */
  if v_interest + v_late > 0 then
    v_exp_id := 'EXP-' || upper(to_hex((extract(epoch from clock_timestamp()) * 1000)::bigint)) || '-' || upper(to_hex((random() * 255)::int));
    insert into public.expenses
      (id, tenant_id, category, vendor_name, expense_date, amount, gst_paid, payment_method,
       description, paid, paid_date, bank_account_id, reconciled_txn_id, bill_type)
    values
      (v_exp_id, v_tenant, 'Rates & Taxes', 'Government', v_txn.txn_date, v_interest + v_late, 0, 'bank_transfer',
       v_label || ' — ' ||
         concat_ws(' + ',
           case when v_interest > 0 then 'interest ₹' || v_interest end,
           case when v_late > 0 then 'late fee ₹' || v_late end),
       true, v_txn.txn_date, v_txn.bank_account_id, p_txn_id, 'none');
  end if;

  insert into public.tax_payments
    (tenant_id, kind, amount, interest, late_fee, period, fy, paid_on, bank_account_id, bank_txn_id, expense_id, notes)
  values
    (v_tenant, p_kind, v_tax, v_interest, v_late,
     case when p_kind = 'gst' then p_period end,
     case when p_kind <> 'gst' then p_fy end,
     v_txn.txn_date, v_txn.bank_account_id, p_txn_id, v_exp_id,
     nullif(trim(coalesce(p_notes, '')), ''))
  returning id into v_id;

  update public.bank_transactions
     set matched_to_type = 'statutory', matched_to_id = v_id::text, match_confidence = 'manual',
         matched_at = now(), matched_by = public.current_user_id(), updated_at = now()
   where id = p_txn_id;

  return v_id;
end;
$function$;

-- public.book_bank_txn_as_vendor_bill
CREATE OR REPLACE FUNCTION public.book_bank_txn_as_vendor_bill(p_txn_id uuid, p_bill_id text, p_method text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_txn public.bank_transactions;
  v_bill public.vendor_bills;
  v_synth uuid;
  v_outstanding integer;
  v_new_paid integer;
begin
  if v_tenant is null then raise exception 'No tenant context'; end if;
  select * into v_txn from public.bank_transactions where id = p_txn_id and tenant_id = v_tenant for update;
  if not found then raise exception 'Bank transaction not found'; end if;
  if v_txn.matched_to_type is not null then raise exception 'This line is already reconciled'; end if;
  if coalesce(v_txn.debit, 0) <= 0 then raise exception 'A bill payment must be a money-out line'; end if;

  select * into v_bill from public.vendor_bills where id = p_bill_id and tenant_id = v_tenant for update;
  if not found then raise exception 'Bill not found'; end if;

  -- The same payment already booked from the Bills page as a synthetic line? Replace it.
  select id into v_synth from public.bank_transactions
   where tenant_id = v_tenant and id <> p_txn_id and source = 'manual'
     and matched_to_type = 'vendor_bill' and matched_to_id = p_bill_id
     and debit = v_txn.debit
   order by abs(txn_date - v_txn.txn_date) limit 1;

  if v_synth is not null then
    delete from public.bank_transactions where id = v_synth;
  else
    v_outstanding := coalesce(v_bill.total, 0) - coalesce(v_bill.paid_amount, 0);
    if v_txn.debit > v_outstanding then
      raise exception 'Line (%) is more than the bill''s outstanding (%) — split the line, or pick the right bill', v_txn.debit, v_outstanding;
    end if;
    v_new_paid := coalesce(v_bill.paid_amount, 0) + v_txn.debit;
    update public.vendor_bills
       set paid_amount = v_new_paid,
           status = case when v_new_paid >= coalesce(total, 0) then 'paid' else 'partial' end,
           updated_at = now()
     where id = p_bill_id;
  end if;

  update public.bank_transactions
     set matched_to_type = 'vendor_bill', matched_to_id = p_bill_id, match_confidence = 'manual',
         reference = coalesce(nullif(trim(coalesce(p_method, '')), ''), reference),
         matched_at = now(), matched_by = public.current_user_id(), updated_at = now()
   where id = p_txn_id;

  return jsonb_build_object('bill_id', p_bill_id, 'replaced_synthetic', v_synth, 'amount', v_txn.debit);
end; $function$;

-- public.can_see_record
CREATE OR REPLACE FUNCTION public.can_see_record(p_owner uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ select p_owner is null or public.current_customer_id() is not null or exists (select 1 from public.users u where u.id = public.current_user_id() and u.role not in ('sales','sales_senior','manager')) or p_owner in (select public.get_subordinate_user_ids(public.current_user_id())) $function$;

-- public.consume_prepaid_advance
CREATE OR REPLACE FUNCTION public.consume_prepaid_advance(p_advance_id uuid, p_amount integer, p_date date DEFAULT CURRENT_DATE, p_note text DEFAULT NULL::text, p_gst integer DEFAULT 0, p_attachment text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_adv    public.prepaid_advances;
  v_exp_id text;
  v_new    int;
begin
  select tenant_id into v_tenant from public.users where id = public.current_user_id();
  if v_tenant is null then raise exception 'No tenant for caller'; end if;
  select * into v_adv from public.prepaid_advances where id = p_advance_id and tenant_id = v_tenant for update;
  if not found then raise exception 'Advance not found'; end if;
  if p_amount <= 0 then raise exception 'Amount must be positive'; end if;
  if p_amount > (v_adv.total_amount - v_adv.consumed_amount) then raise exception 'Amount exceeds remaining balance'; end if;

  v_exp_id := 'EXP-' || upper(substr(md5(gen_random_uuid()::text), 1, 10));
  insert into public.expenses
    (id, tenant_id, category, vendor_name, vendor_id, amount, gst_paid, expense_date, paid, paid_date, bill_type, payment_method, description, notes, attachment_url, prepaid_advance_id)
  values
    (v_exp_id, v_tenant, v_adv.category, v_adv.vendor_name, v_adv.vendor_id, p_amount, greatest(0, coalesce(p_gst,0)), p_date, true, p_date,
     case when coalesce(p_gst,0) > 0 then 'gst' else 'none' end, 'advance',
     'Consumed from ' || v_adv.vendor_name || ' advance', p_note, p_attachment, p_advance_id);

  v_new := v_adv.consumed_amount + p_amount;
  update public.prepaid_advances set consumed_amount = v_new, updated_at = now() where id = p_advance_id;
  return v_adv.total_amount - v_new;
end $function$;

-- public.create_direct_invoice
CREATE OR REPLACE FUNCTION public.create_direct_invoice(p_customer_id uuid, p_line_items jsonb, p_notes text DEFAULT NULL::text, p_recurring boolean DEFAULT false)
 RETURNS TABLE(invoice_id text, quote_id text, net_payable integer, tax_rate integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant   uuid := public.current_tenant_id();
  v_is_svc   boolean := public.current_request_role() = 'service_role';
  v_cust     record;
  v_export   boolean;
  v_rate     integer;
  v_subtotal integer;
  v_gross    integer;
  v_qid      text;
  v_inv      record;
  v_commit   text := case when p_recurring then 'annual_yearly' else 'one_time' end;
  v_lines    jsonb;
begin
  if not v_is_svc and v_tenant is null then raise exception 'No tenant context'; end if;
  if p_customer_id is null then raise exception 'Customer required'; end if;
  if jsonb_typeof(p_line_items) <> 'array' or jsonb_array_length(p_line_items) = 0 then
    raise exception 'At least one line item is required';
  end if;

  select c.id, c.name, c.country, c.tenant_id into v_cust
    from public.customers c where c.id = p_customer_id;
  if not found then raise exception 'Customer not found'; end if;
  if not v_is_svc and v_cust.tenant_id is distinct from v_tenant then
    raise exception 'Customer is not in the caller''s tenant';
  end if;
  v_tenant := v_cust.tenant_id;

  v_export := coalesce(nullif(lower(trim(v_cust.country)), ''), 'india') not in ('india','in','ind','bharat');
  v_rate := case when v_export then 0 else 18 end;

  select coalesce(jsonb_agg(li || jsonb_build_object('commitment', v_commit)), '[]'::jsonb)
    into v_lines
    from jsonb_array_elements(p_line_items) li;

  select coalesce(sum( coalesce((li->>'qty')::int, 1) * coalesce((li->>'rate')::int, 0) ), 0)
    into v_subtotal
    from jsonb_array_elements(v_lines) li;
  if v_subtotal <= 0 then raise exception 'Invoice total must be greater than zero'; end if;
  v_gross := v_subtotal + round(v_subtotal * v_rate / 100.0)::int;

  v_qid := public.next_document_number('quote', v_tenant, public.ist_today());
  if v_qid is null then raise exception 'Could not allocate a quote number'; end if;

  insert into public.quotes (
    id, tenant_id, customer_id, customer_name, amount, subtotal, tax_rate, discount_pct,
    line_items, status, payment_status, is_one_off, created_date, notes
  ) values (
    v_qid, v_tenant, p_customer_id, v_cust.name, v_gross, v_subtotal, v_rate, 0,
    v_lines, 'accepted', 'awaiting', not p_recurring, public.ist_today(), p_notes
  );

  select gi.invoice_id, gi.net_payable into v_inv
    from public.generate_invoice(v_qid) gi;

  return query select v_inv.invoice_id, v_qid, v_inv.net_payable, v_rate;
end;
$function$;

-- public.create_tenant_backup
CREATE OR REPLACE FUNCTION public.create_tenant_backup(p_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_role text;
begin
  select tenant_id, role into v_tenant, v_role from public.users where id = public.current_user_id();
  if v_tenant is null then raise exception 'No tenant for caller'; end if;
  if coalesce(v_role, '') <> 'owner' then raise exception 'Only the owner can take a backup'; end if;
  return backup._take(v_tenant, coalesce(p_label, 'Manual backup'), 'manual');
end $function$;

-- public.current_customer_id
CREATE OR REPLACE FUNCTION public.current_customer_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select customer_id
  from public.customer_users
  where auth_user_id = public.current_user_id()
  limit 1
$function$;

-- public.current_user_has_role
CREATE OR REPLACE FUNCTION public.current_user_has_role(VARIADIC p_roles text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  /* `is_active` matters as much as the role: a deactivated owner is how an ex-employee
     keeps their access. current_user_is_owner() already checks it; this matches. */
  select exists (
    select 1 from public.users u
    where u.id = public.current_user_id()
      and u.is_active
      and u.role::text = any (p_roles)
  );
$function$;

-- public.current_user_is_owner
CREATE OR REPLACE FUNCTION public.current_user_is_owner()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1 from public.users u
    where u.id = public.current_user_id() and u.role = 'owner' and u.is_active
  );
$function$;

-- public.delete_customer
CREATE OR REPLACE FUNCTION public.delete_customer(p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant      uuid;
  v_caller      uuid;
  v_is_service  boolean;
  v_subs        integer;
  v_pays        integer;
  v_invs        integer;
  v_quotes      integer;
  v_projs       integer;
  v_credits     integer;
  v_debits      integer;
  v_tds         integer;
  v_name        text;
  v_parts       text[] := array[]::text[];
begin
  v_is_service := public.current_request_role() = 'service_role';

  select tenant_id, name into v_tenant, v_name
    from public.customers where id = p_customer_id;
  if not found then
    raise exception 'customer % not found', p_customer_id;
  end if;

  if not v_is_service then
    v_caller := public.current_tenant_id();
    if v_caller is null or v_caller <> v_tenant then
      raise exception 'customer % does not belong to your tenant', p_customer_id;
    end if;
  end if;

  select count(*) into v_subs    from public.subscriptions  where customer_id = p_customer_id;
  select count(*) into v_pays    from public.payments       where customer_id = p_customer_id;
  select count(*) into v_invs    from public.invoices       where customer_id = p_customer_id;
  select count(*) into v_quotes  from public.quotes         where customer_id = p_customer_id;
  select count(*) into v_projs   from public.project_sales  where customer_id = p_customer_id;
  -- R-007: these three are legal records too, and nothing counted them. A customer
  -- holding only a credit note was deletable through the front door.
  select count(*) into v_credits from public.credit_notes   where customer_id = p_customer_id;
  select count(*) into v_debits  from public.debit_notes    where customer_id = p_customer_id;
  select count(*) into v_tds     from public.tds_receivable where customer_id = p_customer_id;

  if v_subs    > 0 then v_parts := v_parts || format('%s subscription(s)', v_subs);   end if;
  if v_pays    > 0 then v_parts := v_parts || format('%s payment(s)',      v_pays);    end if;
  if v_invs    > 0 then v_parts := v_parts || format('%s invoice(s)',      v_invs);    end if;
  if v_quotes  > 0 then v_parts := v_parts || format('%s quote(s)',        v_quotes);  end if;
  if v_projs   > 0 then v_parts := v_parts || format('%s project(s)',      v_projs);   end if;
  if v_credits > 0 then v_parts := v_parts || format('%s credit note(s)',  v_credits); end if;
  if v_debits  > 0 then v_parts := v_parts || format('%s debit note(s)',   v_debits);  end if;
  if v_tds     > 0 then v_parts := v_parts || format('%s TDS entry(s)',    v_tds);     end if;

  if array_length(v_parts, 1) is not null then
    raise exception
      'Cannot delete customer "%": has %. Those are financial records and must keep their customer. Archive the customer instead (Customers -> the customer -> Archive), which hides it everywhere without touching the books.',
      v_name, array_to_string(v_parts, ', ');
  end if;

  delete from public.customers where id = p_customer_id and tenant_id = v_tenant;

  return jsonb_build_object('deleted', true, 'customer_id', p_customer_id);
end;
$function$;

-- public.delete_payment
CREATE OR REPLACE FUNCTION public.delete_payment(p_payment_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant   uuid := public.current_tenant_id();
  v_pay      record;
  v_quote    record;
  v_remaining integer;
  v_expected  integer;
  v_new_status public.payment_status;
  v_subs_removed int := 0;
  v_pos_removed  int := 0;
  v_bank_cnt int;
  v_bad_po   int;
begin
  select * into v_pay from public.payments where id = p_payment_id;
  if not found then raise exception 'Payment not found'; end if;
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated')) or (v_tenant is not null and v_pay.tenant_id is distinct from v_tenant) then
    raise exception 'Payment not in your tenant' using errcode = 'insufficient_privilege';
  end if;

  select id, tenant_id, amount, invoice_id, is_add_seats, lead_id, customer_id, customer_name, status
    into v_quote from public.quotes where id = v_pay.quote_id;

  if v_quote.invoice_id is not null then
    raise exception 'A GST invoice is already generated for this quote — cancel / credit-note that invoice before deleting the payment.'
      using errcode = 'invalid_parameter_value';
  end if;

  select count(*) into v_bank_cnt from public.bank_transactions
   where tenant_id = v_pay.tenant_id and matched_to_type = 'payment' and matched_to_id = v_pay.id::text;
  if v_bank_cnt > 0 then
    raise exception 'This payment is reconciled to a bank transaction — un-reconcile that bank line first, then delete.'
      using errcode = 'invalid_parameter_value';
  end if;

  if coalesce(v_quote.is_add_seats, false) then
    if exists (
      select 1 from public.subscriptions s
       where s.tenant_id = v_pay.tenant_id
         and ( (v_quote.customer_id is not null and s.customer_id = v_quote.customer_id)
            or (v_quote.customer_id is null and s.customer_name = v_quote.customer_name) )
    ) then
      raise exception 'This is an add-seats payment — adjust it from the subscription (reduce seats), not by deleting here.'
        using errcode = 'invalid_parameter_value';
    end if;
  end if;

  delete from public.payments where id = p_payment_id;

  select coalesce(sum(amount), 0) into v_remaining
    from public.payments where quote_id = v_pay.quote_id and status = 'received';
  v_expected := coalesce(v_quote.amount, 0);

  v_new_status := case
    when v_remaining <= 0            then 'none'
    when v_remaining >= v_expected   then 'received'
    else                                  'partial' end::public.payment_status;

  update public.quotes
     set payment_status      = v_new_status,
         payment_amount      = v_remaining,
         payment_method      = case when v_remaining <= 0 then null else payment_method end,
         payment_reference   = case when v_remaining <= 0 then null else payment_reference end,
         payment_received_at = case when v_remaining <= 0 then null else payment_received_at end,
         payment_notes       = case when v_remaining <= 0 then null else payment_notes end,
         status              = case when v_remaining <= 0 and status = 'accepted'
                                    then 'sent'::public.quote_status else status end
   where id = v_pay.quote_id and tenant_id = v_pay.tenant_id;

  if v_remaining <= 0 then
    select count(*) into v_bad_po
      from public.purchase_orders po
      join public.subscriptions s on s.id = po.subscription_id
     where s.tenant_id = v_pay.tenant_id and s.quote_id = v_pay.quote_id and po.status <> 'draft';
    if v_bad_po > 0 then
      raise exception 'A purchase order from this sale is already processed — handle it manually before deleting the payment.'
        using errcode = 'invalid_parameter_value';
    end if;

    with subs as (
      select id from public.subscriptions where tenant_id = v_pay.tenant_id and quote_id = v_pay.quote_id
    )
    delete from public.purchase_orders po using subs where po.subscription_id = subs.id;
    get diagnostics v_pos_removed = row_count;

    delete from public.subscriptions where tenant_id = v_pay.tenant_id and quote_id = v_pay.quote_id;
    get diagnostics v_subs_removed = row_count;

    if v_quote.lead_id is not null then
      update public.leads set stage = 'quote', trial_converted_at = null
       where id = v_quote.lead_id and tenant_id = v_pay.tenant_id and stage = 'won';
    end if;
  else
    update public.subscriptions set outstanding_amount = greatest(0, v_expected - v_remaining)
     where tenant_id = v_pay.tenant_id and quote_id = v_pay.quote_id;
  end if;

  return jsonb_build_object(
    'deleted', true, 'quote_id', v_pay.quote_id, 'amount', v_pay.amount,
    'remaining', v_remaining, 'new_payment_status', v_new_status,
    'subscriptions_removed', v_subs_removed, 'purchase_orders_removed', v_pos_removed
  );
end;
$function$;

-- public.delete_project_invoice
CREATE OR REPLACE FUNCTION public.delete_project_invoice(p_invoice_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant  uuid := public.current_tenant_id();
  v_inv     public.invoices;
  v_ms_ids  uuid[];
begin
  select * into v_inv from public.invoices where id = p_invoice_id;
  if not found then raise exception 'Invoice not found'; end if;
  /* R-013 (Pardeep, 27 Sep 2026): the hardened form. The old guard opened by testing
     that the tenant was NOT null and only then comparing — so a NULL tenant skipped the
     comparison entirely, which is the anon case and the signed-in-but-no-users-row case,
     and quote/invoice ids are countable. Migration 20260927100000 rewrote 17 definer RPCs
     by regex; this file recreates some of them, so it must carry the hardened shape
     forward or it silently undoes that fix.

     The old wording is deliberately NOT quoted here. `definer_rpc_hardening.test.sql`
     FAIL 4 scans `pg_get_functiondef`, which includes COMMENTS — so writing the phrase in
     prose turns that security test red for no reason (AGENTS.md L46). Verified: quoting it
     did exactly that. */
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated'))
     or (v_tenant is not null and v_inv.tenant_id is distinct from v_tenant) then
    raise exception 'Invoice not in caller''s tenant' using errcode = 'insufficient_privilege';
  end if;

  /* R-014. Checked HERE as well as in the trigger, on purpose. The trigger is the floor
     and cannot be bypassed; this one exists so the operator gets the refusal before any
     of the unlinking below has run, and so the message can name the project flow. Two
     guards, one of which is reachable and one of which is unavoidable.

     It honours the same escape hatch as the trigger, and that is not decoration: a hatch
     the trigger respects and the RPC does not is a hatch that works for a raw DELETE and
     silently fails for the sanctioned route — which is how somebody ends up deleting the
     row by hand instead, with no guard in the way at all. */
  if v_inv.status <> 'draft'
     and nullif(btrim(coalesce(current_setting('app.invoice_amend_reason', true), '')), '') is null then
    raise exception
      'Invoice % is % — an issued invoice cannot be deleted. Raise a credit note against it instead (Invoices → open % → Credit note); that keeps the number on the GST record, which deleting it would not.',
      p_invoice_id, v_inv.status, p_invoice_id
      using errcode = 'restrict_violation';
  end if;

  select array_agg(id) into v_ms_ids
    from public.project_milestones
   where invoice_id = p_invoice_id and tenant_id = v_inv.tenant_id;

  if v_ms_ids is null then
    raise exception 'Not a project invoice (nothing references it) — cannot delete here'
      using errcode = 'invalid_parameter_value';
  end if;

  /* R-014, the part that was destroying evidence.
     This used to be `delete from public.project_payments where milestone_id = any(...)`
     and, before that, an unmatching of the bank lines those payments were reconciled to.
     `project_payments` rows are money that actually arrived, carrying `bank_txn_id` back
     to a real statement line — they are not a detail of the invoice and they outlive it.

     A draft invoice should never have payments against it in the first place; if one
     somehow does, that is a fact to surface rather than to erase, so the delete is
     refused and the operator is told where to look. */
  if exists (
    select 1 from public.project_payments
     where milestone_id = any (v_ms_ids) and tenant_id = v_inv.tenant_id
  ) then
    raise exception
      'Invoice % has payments recorded against its milestones. Delete or refund those payments first (Projects → the project → Payments) — they are real receipts reconciled to your bank statement and this must not remove them.',
      p_invoice_id
      using errcode = 'restrict_violation';
  end if;

  update public.project_milestones
     set invoice_id = null, status = 'pending'
   where id = any (v_ms_ids);

  delete from public.invoices where id = p_invoice_id;
end;
$function$;

-- public.delete_project_sale
CREATE OR REPLACE FUNCTION public.delete_project_sale(p_project_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_proj   public.project_sales;
begin
  select * into v_proj from public.project_sales where id = p_project_id;
  if not found then raise exception 'Project not found'; end if;
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated')) or (v_tenant is not null and v_proj.tenant_id is distinct from v_tenant) then
    raise exception 'Not in caller''s tenant' using errcode = 'insufficient_privilege';
  end if;
  if exists (select 1 from public.project_milestones where project_id = p_project_id and invoice_id is not null) then
    raise exception 'Can''t delete — a milestone is invoiced. Delete that invoice first.'
      using errcode = 'invalid_parameter_value';
  end if;

  update public.bank_transactions b
     set matched_to_type = null, matched_to_id = null, matched_at = null, match_confidence = null
   where b.tenant_id = v_proj.tenant_id and b.matched_to_type = 'project'
     and b.matched_to_id in (select p.id::text from public.project_payments p where p.project_id = p_project_id);

  delete from public.project_sales where id = p_project_id;
end;
$function$;

-- public.delete_reimbursement
CREATE OR REPLACE FUNCTION public.delete_reimbursement(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_r      public.reimbursements;
begin
  select * into v_r from public.reimbursements where id = p_id;
  if not found then raise exception 'Reimbursement not found'; end if;
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated')) or (v_tenant is not null and v_r.tenant_id is distinct from v_tenant) then
    raise exception 'Not in your tenant' using errcode = 'insufficient_privilege';
  end if;
  delete from public.reimbursements where id = p_id;
  if v_r.expense_id is not null then
    delete from public.expenses where id = v_r.expense_id and tenant_id = v_r.tenant_id and reconciled_txn_id is null;
  end if;
end;
$function$;

-- public.delete_salary_payment
CREATE OR REPLACE FUNCTION public.delete_salary_payment(p_salary_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_sp     public.salary_payments;
begin
  select * into v_sp from public.salary_payments where id = p_salary_id;
  if not found then raise exception 'Salary payment not found'; end if;
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated')) or (v_tenant is not null and v_sp.tenant_id is distinct from v_tenant) then
    raise exception 'Salary payment not in caller''s tenant' using errcode = 'insufficient_privilege';
  end if;

  if v_sp.paid_amount > 0 then
    raise exception 'This salary has % reconciled against it — un-reconcile that bank line first, then undo.', v_sp.paid_amount
      using errcode = 'invalid_parameter_value';
  end if;

  if v_sp.advance_recovered > 0 and v_sp.advance_loan_id is not null then
    delete from public.employee_loan_repayments
     where tenant_id = v_sp.tenant_id and loan_id = v_sp.advance_loan_id
       and method = 'salary_deduction' and amount = v_sp.advance_recovered
       and repaid_on = v_sp.pay_date and notes = 'Recovered from salary ' || v_sp.period;
    update public.employee_loans set status = 'active', updated_at = now()
     where id = v_sp.advance_loan_id;
  end if;

  delete from public.salary_payments where id = p_salary_id;

  if v_sp.expense_id is not null then
    delete from public.expenses where id = v_sp.expense_id and tenant_id = v_sp.tenant_id;
  end if;
end;
$function$;

-- public.delete_subscription
CREATE OR REPLACE FUNCTION public.delete_subscription(p_subscription_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_sub    record;
  v_paid_cnt int;
  v_bad_po   int;
  v_pos_removed int := 0;
begin
  select * into v_sub from public.subscriptions where id = p_subscription_id;
  if not found then raise exception 'Subscription not found'; end if;
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated')) or (v_tenant is not null and v_sub.tenant_id is distinct from v_tenant) then
    raise exception 'Subscription not in your tenant' using errcode = 'insufficient_privilege';
  end if;

  if v_sub.quote_id is not null then
    select count(*) into v_paid_cnt from public.payments
     where tenant_id = v_sub.tenant_id and quote_id = v_sub.quote_id and status = 'received';
    if v_paid_cnt > 0 then
      raise exception 'This subscription came from a paid quote — delete that payment in Payments instead; it removes this subscription cleanly.'
        using errcode = 'invalid_parameter_value';
    end if;
  end if;

  select count(*) into v_bad_po from public.purchase_orders
   where tenant_id = v_sub.tenant_id and subscription_id = p_subscription_id and status <> 'draft';
  if v_bad_po > 0 then
    raise exception 'A purchase order linked to this subscription is already processed — handle it manually first.'
      using errcode = 'invalid_parameter_value';
  end if;

  delete from public.purchase_orders
   where tenant_id = v_sub.tenant_id and subscription_id = p_subscription_id;
  get diagnostics v_pos_removed = row_count;

  delete from public.subscriptions where id = p_subscription_id;

  return jsonb_build_object('deleted', true, 'purchase_orders_removed', v_pos_removed);
end;
$function$;

-- public.delete_subscription_invoice
CREATE OR REPLACE FUNCTION public.delete_subscription_invoice(p_invoice_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_inv    public.invoices;
  v_paid   integer;
  v_status payment_status;
begin
  select * into v_inv from public.invoices where id = p_invoice_id;
  if not found then raise exception 'Invoice not found'; end if;
  /* R-013 (Pardeep, 27 Sep 2026): the hardened form. The old guard opened by testing
     that the tenant was NOT null and only then comparing — so a NULL tenant skipped the
     comparison entirely, which is the anon case and the signed-in-but-no-users-row case,
     and quote/invoice ids are countable. Migration 20260927100000 rewrote 17 definer RPCs
     by regex; this file recreates some of them, so it must carry the hardened shape
     forward or it silently undoes that fix.

     The old wording is deliberately NOT quoted here. `definer_rpc_hardening.test.sql`
     FAIL 4 scans `pg_get_functiondef`, which includes COMMENTS — so writing the phrase in
     prose turns that security test red for no reason (AGENTS.md L46). Verified: quoting it
     did exactly that. */
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated'))
     or (v_tenant is not null and v_inv.tenant_id is distinct from v_tenant) then
    raise exception 'Invoice not in caller''s tenant' using errcode = 'insufficient_privilege';
  end if;

  if exists (select 1 from public.project_milestones where invoice_id = p_invoice_id) then
    raise exception 'This is a project invoice — delete it from the project flow'
      using errcode = 'invalid_parameter_value';
  end if;

  -- R-014. Same guard, same escape hatch, same reasons as the project path above.
  if v_inv.status <> 'draft'
     and nullif(btrim(coalesce(current_setting('app.invoice_amend_reason', true), '')), '') is null then
    raise exception
      'Invoice % is % — an issued invoice cannot be deleted. Raise a credit note against it instead (Invoices → open % → Credit note); that keeps the number on the GST record, which deleting it would not.',
      p_invoice_id, v_inv.status, p_invoice_id
      using errcode = 'restrict_violation';
  end if;

  if v_inv.quote_id is not null then
    select coalesce(sum(amount), 0) into v_paid
      from public.payments
     where quote_id = v_inv.quote_id and status = 'received';

    v_status := (case
      when v_paid >= coalesce(v_inv.amount, 0) and v_paid > 0 then 'received'
      when v_paid > 0                                         then 'partial'
      else 'none'
    end)::payment_status;

    update public.quotes
       set invoice_id = null, payment_status = v_status
     where id = v_inv.quote_id and tenant_id = v_inv.tenant_id;
  end if;

  delete from public.invoices where id = p_invoice_id;
end;
$function$;

-- public.delete_tenant_backup
CREATE OR REPLACE FUNCTION public.delete_tenant_backup(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.guard_backup_owner_only();
  delete from backup.snapshots
   where id = p_id
     and tenant_id = (select tenant_id from public.users where id = public.current_user_id());
end $function$;

-- public.disburse_employee_loan
CREATE OR REPLACE FUNCTION public.disburse_employee_loan(p_employee_name text, p_principal integer, p_disbursed_on date, p_bank_account_id uuid, p_kind text DEFAULT 'loan'::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_loan   uuid;
  v_acct   text;
  v_kind   text := coalesce(nullif(trim(p_kind), ''), 'loan');
begin
  if p_principal is null or p_principal <= 0 then
    raise exception 'Amount must be positive';
  end if;
  if trim(coalesce(p_employee_name, '')) = '' then
    raise exception 'Employee name is required';
  end if;
  if v_kind not in ('loan', 'salary_advance', 'expense_advance') then
    raise exception 'Invalid kind';
  end if;

  select name into v_acct from public.bank_accounts
    where id = p_bank_account_id and tenant_id = v_tenant;
  if not found then raise exception 'Source account not found'; end if;

  insert into public.employee_loans
    (tenant_id, employee_name, principal, disbursed_on, bank_account_id, kind, notes, created_by)
  values
    (v_tenant, trim(p_employee_name), p_principal, p_disbursed_on, p_bank_account_id, v_kind,
     nullif(trim(coalesce(p_notes, '')), ''), public.current_user_id())
  returning id into v_loan;

  insert into public.bank_transactions
    (tenant_id, bank_account_id, txn_date, description, debit, credit, source, matched_to_type, match_confidence)
  values
    (v_tenant, p_bank_account_id, p_disbursed_on,
     case v_kind when 'expense_advance' then 'Expense advance to ' else 'Loan/advance to ' end || trim(p_employee_name),
     p_principal, 0, 'manual', 'manual', 'manual');

  return v_loan;
end;
$function$;

-- public.export_snapshots_for_offsite
CREATE OR REPLACE FUNCTION public.export_snapshots_for_offsite(p_since timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  /* `nullif(…, '')` choice nahi hai. `set_config('request.jwt.claims', null, true)` setting ko
     KHAALI STRING banata hai, NULL nahi — aur `''::jsonb` 22P02 se marta hai. Bina iske ye
     function har us session me crash karta hai jisne claims saaf ki hon, aur wo crash "backup
     nahi hua" jaisa hi dikhta. Pehli baar test chalate hi yahi hua. */
  v_role text := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '');
  v_out  jsonb;
begin
  /* Doosra pehra. Asli deewar neeche wala grant hai; ye us din ke liye hai jis din koi
     grant galti se khul jaye. `public.current_user_id()` ka hona hi kaafi saboot hai ki ye ek browser
     session hai, aur ye function browser se kabhi nahi chalna chahiye. */
  if public.current_user_id() is not null or v_role in ('authenticated', 'anon') then
    raise exception 'export_snapshots_for_offsite is service_role only';
  end if;

  select coalesce(jsonb_agg(x order by x->>'created_at'), '[]'::jsonb) into v_out
  from (
    /* Har tenant ka sirf SABSE NAYA snapshot. Poora itihaas bhejna har raat pichhli
       raaton ki nakal dobara upload karta, aur off-site copy ka size roz badhta jaata
       bina kisi naye saboot ke. */
    select distinct on (s.tenant_id)
      jsonb_build_object(
        'tenant_id',   s.tenant_id,
        'tenant_name', t.name,
        'snapshot_id', s.id,
        'created_at',  s.created_at,
        'label',       s.label,
        'kind',        s.kind,
        'table_count', s.table_count,
        'payload',     s.payload
      ) as x
    from backup.snapshots s
    join public.tenants t on t.id = s.tenant_id
    where s.created_at >= p_since
    order by s.tenant_id, s.created_at desc
  ) q;

  return v_out;
end;
$function$;

-- public.export_tenant_snapshot_for_offsite
CREATE OR REPLACE FUNCTION public.export_tenant_snapshot_for_offsite(p_tenant uuid, p_since timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role text := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '');
  v_out  jsonb;
begin
  if public.current_user_id() is not null or v_role in ('authenticated', 'anon') then
    raise exception 'export_tenant_snapshot_for_offsite is service_role only';
  end if;

  /* Shakl wahi jo export_snapshots_for_offsite ke har element ki hai — taaki envelope aur
     scripts/gen-restore-rehearsal.cjs bina badle chalein. Koi snapshot nahi → NULL (cron
     use "is tenant ka backup nahi bana" ginta hai, khaali object upload nahi karta). */
  select jsonb_build_object(
           'tenant_id',   s.tenant_id,
           'tenant_name', t.name,
           'snapshot_id', s.id,
           'created_at',  s.created_at,
           'label',       s.label,
           'kind',        s.kind,
           'table_count', s.table_count,
           'payload',     s.payload)
    into v_out
  from backup.snapshots s
  join public.tenants t on t.id = s.tenant_id
  where s.tenant_id = p_tenant and s.created_at >= p_since
  order by s.created_at desc
  limit 1;

  return v_out;
end;
$function$;

-- public.get_my_tenant_with_parent
CREATE OR REPLACE FUNCTION public.get_my_tenant_with_parent()
 RETURNS TABLE(id uuid, name text, tier text, parent_tenant_id uuid, parent_name text, parent_tier text, parent_gstin text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with my as (
    select tenant_id from public.users where id = public.current_user_id() limit 1
  )
  select
    t.id, t.name, t.tier, t.parent_tenant_id,
    p.name, p.tier, p.gstin
  from public.tenants t
  left join public.tenants p on p.id = t.parent_tenant_id
  where t.id = (select tenant_id from my);
$function$;

-- public.get_partner_catalog
CREATE OR REPLACE FUNCTION public.get_partner_catalog()
 RETURNS TABLE(id text, tenant_id uuid, name text, vendor text, kind text, hsn text, msrp integer, partner_price integer, prices jsonb, is_active boolean, already_synced boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with me as (
    select u.tenant_id as child_tenant, t.parent_tenant_id as parent_tenant
    from public.users u
    join public.tenants t on t.id = u.tenant_id
    where u.id = public.current_user_id()
    limit 1
  )
  select
    pi.id,
    pi.tenant_id,
    pi.name,
    pi.vendor::text,
    pi.kind::text,
    pi.hsn,
    pi.msrp,
    pi.partner_price,
    pi.prices,
    pi.is_active,
    exists (
      select 1
      from public.items ci
      where ci.tenant_id = (select child_tenant from me)
        and ci.synced_from_partner_id = pi.id
    ) as already_synced
  from public.items pi
  where pi.tenant_id = (select parent_tenant from me)
    and pi.is_partner_visible = true
    and pi.is_active = true
  order by pi.vendor, pi.kind, pi.name;
$function$;

-- public.get_partner_metrics
CREATE OR REPLACE FUNCTION public.get_partner_metrics()
 RETURNS TABLE(tenant_id uuid, tenant_name text, tenant_gstin text, active_subscriptions integer, total_seats_sold integer, mrr integer, invoiced_this_month integer, paid_this_month integer, renewals_due_30d integer, renewal_revenue_30d integer, last_invoice_date date)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with caller as (
    select tenant_id from public.users where id = public.current_user_id() limit 1
  ),
  month_start as (
    select date_trunc('month', current_date)::date as d
  ),
  children as (
    select t.id, t.name, t.gstin
    from public.tenants t
    where t.parent_tenant_id = (select tenant_id from caller)
  )
  select
    c.id, c.name, c.gstin,
    coalesce((select count(*)::int from public.subscriptions s
      where s.tenant_id = c.id and s.status = 'active'), 0),
    coalesce((select sum(seats)::int from public.subscriptions s
      where s.tenant_id = c.id and s.status = 'active'), 0),
    coalesce((select sum(mrr)::int from public.subscriptions s
      where s.tenant_id = c.id and s.status = 'active'), 0),
    coalesce((select sum(amount)::int from public.invoices i
      where i.tenant_id = c.id and i.invoice_date >= (select d from month_start)), 0),
    coalesce((select sum(amount)::int from public.invoices i
      where i.tenant_id = c.id and i.status = 'paid' and i.paid_date is not null
        and i.paid_date >= (select d from month_start)), 0),
    coalesce((select count(*)::int from public.subscriptions s
      where s.tenant_id = c.id and s.status = 'active'
        and s.renewal_date is not null and s.renewal_date <= current_date + interval '30 days'), 0),
    coalesce((select sum(mrr * 12)::int from public.subscriptions s
      where s.tenant_id = c.id and s.status = 'active'
        and s.renewal_date is not null and s.renewal_date <= current_date + interval '30 days'), 0),
    (select max(invoice_date) from public.invoices i where i.tenant_id = c.id)
  from children c
  order by c.name;
$function$;

-- public.get_tenant_backup
CREATE OR REPLACE FUNCTION public.get_tenant_backup(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.guard_backup_owner_only();
  return (
    select payload from backup.snapshots
     where id = p_id
       and tenant_id = (select tenant_id from public.users where id = public.current_user_id())
  );
end $function$;

-- public.give_employee_advance
CREATE OR REPLACE FUNCTION public.give_employee_advance(p_name text, p_amount integer, p_date date DEFAULT CURRENT_DATE, p_method text DEFAULT 'cash'::text, p_account uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_id     uuid;
  v_leg    uuid;
begin
  if v_tenant is null then raise exception 'No company context — sign in again.'; end if;
  if nullif(trim(coalesce(p_name, '')), '') is null then raise exception 'Enter who you gave the money to.'; end if;
  if coalesce(p_amount, 0) <= 0 then raise exception 'Amount must be more than ₹0.'; end if;
  if p_account is not null and not exists (select 1 from public.bank_accounts where id = p_account and tenant_id = v_tenant) then
    raise exception 'That bank / cash account is not in your company.';
  end if;

  insert into public.prepaid_advances
    (tenant_id, vendor_name, category, total_amount, consumed_amount, paid_date, payment_method,
     bank_account_id, notes, created_by)
  values
    (v_tenant, trim(p_name), 'Employee advance', p_amount, 0, coalesce(p_date, current_date), p_method,
     p_account, nullif(trim(coalesce(p_note, '')), ''), public.current_user_id())
  returning id into v_id;

  v_leg := public._employee_advance_cash_leg(v_tenant, p_account, coalesce(p_date, current_date), p_amount, 0,
                                             'Advance to ' || trim(p_name), v_id);
  if v_leg is not null then
    update public.prepaid_advances set bank_txn_id = v_leg where id = v_id;
  end if;
  return v_id;
end $function$;

-- public.guard_privileged_user_columns
CREATE OR REPLACE FUNCTION public.guard_privileged_user_columns()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_is_owner boolean;
begin
  if new.role           is not distinct from old.role
     and new.manager_id     is not distinct from old.manager_id
     and new.can_view_deals is not distinct from old.can_view_deals
     and new.gets_new_leads is not distinct from old.gets_new_leads
     and new.tenant_id      is not distinct from old.tenant_id
     and new.is_active      is not distinct from old.is_active then
    return new;
  end if;

  if public.current_user_id() is null then
    return new;
  end if;

  select exists (
    select 1 from public.users u where u.id = public.current_user_id() and u.role = 'owner'
  ) into v_is_owner;

  if not v_is_owner then
    raise exception 'Only an owner can change a teammate''s role, reporting manager, deals access, new-lead assignment, workspace or active status. Ask an owner to do it on the Team page (/team).';
  end if;

  return new;
end;
$function$;

-- public.guard_provisioning_request_facts
CREATE OR REPLACE FUNCTION public.guard_provisioning_request_facts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  /* Nothing that decides an activation changed — this is the operator ticking a
     row off. Leave it alone, so the common case pays no cost. */
  if new.payment_mode is not distinct from old.payment_mode
     and new.blocker     is not distinct from old.blocker
     and new.seats       is not distinct from old.seats
     and new.amount_paid is not distinct from old.amount_paid
     and new.vendor      is not distinct from old.vendor
     and new.quote_id    is not distinct from old.quote_id
     and new.tenant_id   is not distinct from old.tenant_id
     and new.domain      is not distinct from old.domain
     and new.plan        is not distinct from old.plan
     and new.years       is not distinct from old.years then
    return new;
  end if;

  /* Trusted server code — see THE CARVE-OUT in 20260921100000. */
  if public.current_user_id() is null then
    return new;
  end if;

  raise exception
    'This row records what a customer paid for, so those fields cannot be edited here. '
    'You changed one of: payment mode, blocker, seats, amount paid, vendor, quote, domain, '
    'plan or years. They are written from the verified payment and are what decides what is '
    'activated or registered automatically. To complete a request, set its status (and '
    'vendor_ref / note) instead. If the payment details are genuinely wrong, the payment is '
    'what needs correcting, not this row.'
    using errcode = 'check_violation';
end;
$function$;

-- public.handle_task_completion
CREATE OR REPLACE FUNCTION public.handle_task_completion()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status = 'done' and (old.status is distinct from 'done') then
    new.completed_at := now();
    new.completed_by := public.current_user_id();
  end if;
  if old.status = 'done' and new.status <> 'done' then
    new.completed_at := null;
    new.completed_by := null;
  end if;
  return new;
end $function$;

-- public.hierarchy_sees_all
CREATE OR REPLACE FUNCTION public.hierarchy_sees_all()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ select public.current_customer_id() is not null or exists (select 1 from public.users u where u.id = public.current_user_id() and u.role not in ('sales','sales_senior','manager')) $function$;

-- public.issue_credit_note
CREATE OR REPLACE FUNCTION public.issue_credit_note(p_invoice_id text, p_gross_amount integer, p_reason_code text DEFAULT 'other'::text, p_reason text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_inv             record;
  v_is_service      boolean;
  v_caller_tenant   uuid;
  v_already         integer;
  v_max_creditable  integer;
  v_rate            integer;
  v_taxable         integer;
  v_tax             integer;
  v_cn_id           text;
  v_supply_fy_end   text;
  v_s34_deadline    date;
  v_new_net         integer;
begin
  v_is_service := public.current_request_role() = 'service_role';
  if not v_is_service then
    v_caller_tenant := public.current_tenant_id();
    if v_caller_tenant is null then raise exception 'No tenant context'; end if;
  end if;

  if p_gross_amount is null or p_gross_amount <= 0 then
    raise exception 'Credit amount must be greater than zero' using errcode = 'check_violation';
  end if;

  /* R-041 added i.invoice_date: the Section 34(2) deadline is measured from the FY of the
     SUPPLY, so the check below needs the invoice date rather than today. */
  select i.id, i.tenant_id, i.customer_id, i.customer_name, i.amount, i.net_payable,
         i.tax_rate, i.inter_state, i.invoice_date
    into v_inv
    from public.invoices i where i.id = p_invoice_id for update;
  if not found then raise exception 'Invoice % not found', p_invoice_id using errcode = 'no_data_found'; end if;
  if not v_is_service and v_inv.tenant_id is distinct from v_caller_tenant then
    raise exception 'Invoice % is not in the caller''s tenant', p_invoice_id using errcode = 'insufficient_privilege';
  end if;

  select coalesce(sum(amount), 0) into v_already from public.credit_notes where invoice_id = p_invoice_id;
  v_max_creditable := coalesce(v_inv.amount, 0) - v_already;
  if p_gross_amount > v_max_creditable then
    raise exception 'Credit % exceeds the creditable balance % on invoice %',
      p_gross_amount, v_max_creditable, p_invoice_id using errcode = 'check_violation';
  end if;

  v_rate := coalesce(v_inv.tax_rate, 18);
  if v_rate = 0 then
    v_taxable := p_gross_amount;
    v_tax     := 0;
  else
    v_taxable := round(p_gross_amount * 100.0 / (100 + v_rate));
    v_tax     := p_gross_amount - v_taxable;
  end if;

  /* ── R-041: CGST Section 34(2) — a credit note has a deadline ──────────────────
     A credit note may be declared up to 30 NOVEMBER following the end of the financial
     year of the original supply (or the date the annual return is filed, whichever is
     earlier). Past that, the supplier cannot reduce its output tax liability: the note
     can still be raised commercially, but the GST on it is simply lost, and GSTR-1 will
     not accept it against that invoice.

     Nothing checked this. A note raised in, say, January against an invoice from two
     financial years earlier looked completely normal and quietly wrote off the tax.

     The annual-return half is not knowable from this database, so only the 30 November
     limb is enforced — the earlier of the two is what the law asks for, so this is the
     permissive side of the rule and is stated as such rather than claimed as complete. */
  v_supply_fy_end := (public.indian_fiscal_year(coalesce(v_inv.invoice_date, public.ist_today())));
  v_s34_deadline  := make_date(2000 + substring(v_supply_fy_end from 5 for 2)::int, 11, 30);
  if public.ist_today() > v_s34_deadline then
    raise exception
      'Too late for a credit note against invoice %: it was supplied in FY %, and CGST Section 34(2) allows one only up to 30 November %. Raise a refund or a commercial adjustment instead — a credit note now cannot reduce the GST you already paid.',
      p_invoice_id, v_supply_fy_end, to_char(v_s34_deadline, 'DD Mon YYYY')
      using errcode = 'check_violation';
  end if;

  v_cn_id := public.next_document_number('credit_note', v_inv.tenant_id, public.ist_today());
  if v_cn_id is null then raise exception 'Could not allocate a credit note number'; end if;

  insert into public.credit_notes (
    id, tenant_id, invoice_id, customer_id, customer_name, credit_date,
    reason_code, reason, amount, taxable_value, tax_amount, tax_rate, inter_state, notes, created_by
  ) values (
    v_cn_id, v_inv.tenant_id, p_invoice_id, v_inv.customer_id, v_inv.customer_name, public.ist_today(),
    coalesce(p_reason_code, 'other'), p_reason, p_gross_amount, v_taxable, v_tax, v_rate,
    coalesce(v_inv.inter_state, false), p_notes, public.current_user_id()
  );

  v_new_net := greatest(0, coalesce(v_inv.net_payable, v_inv.amount) - p_gross_amount);
  update public.invoices set net_payable = v_new_net, updated_at = now() where id = p_invoice_id;

  return jsonb_build_object(
    'credit_note_id',  v_cn_id,
    'invoice_id',      p_invoice_id,
    'amount',          p_gross_amount,
    'taxable_value',   v_taxable,
    'tax_amount',      v_tax,
    'tax_rate',        v_rate,
    'inter_state',     coalesce(v_inv.inter_state, false),
    'new_net_payable', v_new_net
  );
end;
$function$;

-- public.issue_debit_note
CREATE OR REPLACE FUNCTION public.issue_debit_note(p_invoice_id text, p_gross_amount integer, p_reason_code text DEFAULT 'other'::text, p_reason text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_inv           record;
  v_is_service    boolean;
  v_caller_tenant uuid;
  v_rate          integer;
  v_taxable       integer;
  v_tax           integer;
  v_dn_id         text;
  v_new_net       integer;
begin
  v_is_service := public.current_request_role() = 'service_role';
  if not v_is_service then
    v_caller_tenant := public.current_tenant_id();
    if v_caller_tenant is null then raise exception 'No tenant context'; end if;
  end if;

  if p_gross_amount is null or p_gross_amount <= 0 then
    raise exception 'Debit amount must be greater than zero' using errcode = 'check_violation';
  end if;

  select i.id, i.tenant_id, i.customer_id, i.customer_name, i.amount, i.net_payable,
         i.tax_rate, i.inter_state
    into v_inv
    from public.invoices i where i.id = p_invoice_id for update;
  if not found then raise exception 'Invoice % not found', p_invoice_id using errcode = 'no_data_found'; end if;
  if not v_is_service and v_inv.tenant_id is distinct from v_caller_tenant then
    raise exception 'Invoice % is not in the caller''s tenant', p_invoice_id using errcode = 'insufficient_privilege';
  end if;

  v_rate := coalesce(v_inv.tax_rate, 18);
  if v_rate = 0 then
    v_taxable := p_gross_amount;
    v_tax     := 0;
  else
    v_taxable := round(p_gross_amount * 100.0 / (100 + v_rate));
    v_tax     := p_gross_amount - v_taxable;
  end if;

  v_dn_id := public.next_document_number('debit_note', v_inv.tenant_id, public.ist_today());
  if v_dn_id is null then raise exception 'Could not allocate a debit note number'; end if;

  insert into public.debit_notes (
    id, tenant_id, invoice_id, customer_id, customer_name, debit_date,
    reason_code, reason, amount, taxable_value, tax_amount, tax_rate, inter_state, notes, created_by
  ) values (
    v_dn_id, v_inv.tenant_id, p_invoice_id, v_inv.customer_id, v_inv.customer_name, public.ist_today(),
    coalesce(p_reason_code, 'other'), p_reason, p_gross_amount, v_taxable, v_tax, v_rate,
    coalesce(v_inv.inter_state, false), p_notes, public.current_user_id()
  );

  v_new_net := coalesce(v_inv.net_payable, v_inv.amount) + p_gross_amount;
  update public.invoices set net_payable = v_new_net, updated_at = now() where id = p_invoice_id;

  return jsonb_build_object(
    'debit_note_id',   v_dn_id,
    'invoice_id',      p_invoice_id,
    'amount',          p_gross_amount,
    'taxable_value',   v_taxable,
    'tax_amount',      v_tax,
    'tax_rate',        v_rate,
    'inter_state',     coalesce(v_inv.inter_state, false),
    'new_net_payable', v_new_net
  );
end;
$function$;

-- public.lead_counts
CREATE OR REPLACE FUNCTION public.lead_counts(p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_f         jsonb   := coalesce(p_filters, '{}'::jsonb);
  v_view      text    := coalesce(nullif(v_f->>'smart_view', ''), 'everything');
  v_folder    text    := coalesce(nullif(v_f->>'folder', ''), 'all');
  v_today     date    := (now() at time zone 'Asia/Kolkata')::date;
  v_month_end date;
  v_month_at  timestamptz;
  v_pattern   text;
  v_stages    text[];
  v_page_stages text[];
  v_prios     text[];
  v_owner_ids uuid[];
  v_owner_id  uuid    := nullif(v_f->>'owner_id', '')::uuid;
  v_owners    text[];
  v_me        uuid    := public.current_user_id();
  v_out       jsonb;
begin
  if v_view not in ('everything', 'all', 'mine', 'waiting', 'today', 'overdue', 'hot', 'new',
                    'won-mtd', 'closing', 'stalled', 'duplicates', 'junk') then
    raise exception 'lead_counts: unknown smart_view %', v_view using errcode = '22023';
  end if;
  if v_folder not in ('all', 'inbox', 'talks', 'quoted', 'proving', 'won', 'lost', 'hot', 'followup') then
    raise exception 'lead_counts: unknown folder %', v_folder using errcode = '22023';
  end if;

  v_month_end := (date_trunc('month', v_today) + interval '1 month - 1 day')::date;
  v_month_at  := date_trunc('month', v_today)::timestamp at time zone 'Asia/Kolkata';

  if btrim(coalesce(v_f->>'search', '')) <> '' then
    v_pattern := '%' || replace(replace(replace(lower(v_f->>'search'), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  end if;
  if jsonb_typeof(v_f->'stages') = 'array' and jsonb_array_length(v_f->'stages') > 0 then
    select array_agg(x) into v_stages from jsonb_array_elements_text(v_f->'stages') x;
  end if;
  if jsonb_typeof(v_f->'page_stages') = 'array' and jsonb_array_length(v_f->'page_stages') > 0 then
    select array_agg(x) into v_page_stages from jsonb_array_elements_text(v_f->'page_stages') x;
  end if;
  if jsonb_typeof(v_f->'priorities') = 'array' and jsonb_array_length(v_f->'priorities') > 0 then
    select array_agg(x) into v_prios from jsonb_array_elements_text(v_f->'priorities') x;
  end if;
  if jsonb_typeof(v_f->'owner_ids') = 'array' then
    select coalesce(array_agg(x::uuid), '{}') into v_owner_ids from jsonb_array_elements_text(v_f->'owner_ids') x;
  end if;
  if jsonb_typeof(v_f->'owners') = 'array' and jsonb_array_length(v_f->'owners') > 0 then
    select array_agg(x) into v_owners from jsonb_array_elements_text(v_f->'owners') x;
  end if;

  with pool as (
    select l.id, l.company, l.contact_name, l.contact_email, l.contact_phone, l.plan, l.value,
           l.stage::text as stage, l.priority, l.owner_id, l.is_junk, l.created_at,
           l.follow_up_date, l.expected_close_date, l.stage_changed_at, l.enquiry_type,
           l.requires_human_attention
      from public.leads l
     where l.tenant_id = public.current_tenant_id()
  ), ws as (
    select p.*,
           public.lead_looks_like_junk(p.company, p.contact_name, p.contact_email, p.contact_phone) as suspect
      from pool p
     where (v_owner_ids is null or p.owner_id is null or p.owner_id = any (v_owner_ids))
       and (v_owner_id is null or p.owner_id = v_owner_id)
  ), dup_ids as (
    /* computeDuplicates(workspaceLeads): every workspace lead whose phone key or company key
       another workspace lead shares. One index-only pass per key over leads_dup_*_idx
       (≈13 ms each at 20,000 leads), counted with a window rather than joined back — the
       join was planned as "recompute the key for every lead" (≈330 ms). */
    select s.id
      from (select g.id, public.lead_norm_phone(g.contact_phone) as k,
                   count(*) over (partition by public.lead_norm_phone(g.contact_phone)) as n
              from public.leads g
             where g.tenant_id = public.current_tenant_id()
               and (v_owner_ids is null or g.owner_id is null or g.owner_id = any (v_owner_ids))
               and (v_owner_id is null or g.owner_id = v_owner_id)) s
     where s.n > 1 and s.k <> ''
    union
    select s.id
      from (select g.id, public.lead_norm_company(g.company) as k,
                   count(*) over (partition by public.lead_norm_company(g.company)) as n
              from public.leads g
             where g.tenant_id = public.current_tenant_id()
               and (v_owner_ids is null or g.owner_id is null or g.owner_id = any (v_owner_ids))
               and (v_owner_id is null or g.owner_id = v_owner_id)) s
     where s.n > 1 and s.k <> ''
  ), flagged as (
    select w.*,
           (w.id in (select id from dup_ids)) as dup,
           (w.stage not in ('won', 'lost') and not w.is_junk) as open
      from ws w
  ), searched as (
    select f.*
      from flagged f
     where (case when v_view = 'junk' then (f.is_junk or f.suspect) else not f.is_junk end)
       and (v_pattern is null
            or lower(f.company) like v_pattern escape '\'
            or lower(f.contact_name) like v_pattern escape '\'
            or lower(f.contact_email) like v_pattern escape '\'
            or lower(f.contact_phone) like v_pattern escape '\'
            or lower(f.plan) like v_pattern escape '\')
       and (v_stages is null or f.stage = any (v_stages))
       and (v_prios is null or f.priority = any (v_prios))
       and (v_owners is null
            or (f.owner_id is null and '__unassigned' = any (v_owners))
            or f.owner_id::text = any (v_owners))
       and (v_view in ('everything', 'all', 'junk')
            or (v_view = 'mine'     and f.owner_id = v_me)
            or (v_view = 'waiting'  and f.requires_human_attention and f.stage not in ('won', 'lost'))
            or (v_view = 'today'    and (f.created_at at time zone 'Asia/Kolkata')::date = v_today)
            or (v_view = 'overdue'  and f.follow_up_date < v_today and f.stage not in ('won', 'lost'))
            or (v_view = 'hot'      and (f.priority = 'high' or f.stage in ('demo', 'trial', 'quote')))
            or (v_view = 'new'      and f.stage = 'new')
            or (v_view = 'won-mtd'  and f.stage = 'won' and coalesce(f.stage_changed_at, f.created_at) >= v_month_at)
            or (v_view = 'closing'  and f.expected_close_date <= v_month_end and f.stage not in ('won', 'lost'))
            or (v_view = 'stalled'  and f.stage not in ('won', 'lost')
                and f.stage_changed_at is not null and f.stage_changed_at <= now() - interval '7 days')
            or (v_view = 'duplicates' and f.dup))
  ), listed as (
    select s.*
      from searched s
     where v_view = 'junk'
        or (v_folder = 'all' and v_view = 'everything')
        or (v_folder = 'all'      and s.open)
        or (v_folder = 'inbox'    and not s.is_junk and s.stage = 'new')
        or (v_folder = 'talks'    and not s.is_junk and s.stage = 'contact')
        or (v_folder = 'quoted'   and not s.is_junk and s.stage = 'quote')
        or (v_folder = 'proving'  and not s.is_junk and s.stage in ('demo', 'trial'))
        or (v_folder = 'won'      and s.stage = 'won')
        or (v_folder = 'lost'     and s.stage = 'lost')
        or (v_folder = 'hot'      and s.open and (s.priority = 'high' or coalesce(s.value, 0) >= 100000))
        or (v_folder = 'followup' and s.open and s.follow_up_date <= v_today)
  )
  select jsonb_build_object(
    'today', v_today,
    'pool', (
      select jsonb_build_object(
        'total',         count(*),
        'unassigned',    count(*) filter (where p.owner_id is null),
        'high_priority', count(*) filter (where p.priority = 'high'),
        'by_owner',      coalesce((select jsonb_object_agg(o.owner_id, o.n)
                                     from (select owner_id, count(*) as n from pool
                                            where owner_id is not null group by owner_id) o), '{}'::jsonb))
        from pool p),
    'workspace', (
      select jsonb_build_object(
        'junk',       count(*) filter (where w.is_junk),
        'everything', count(*) filter (where not w.is_junk),
        'suspects',   count(*) filter (where not w.is_junk and w.suspect))
        from ws w),
    'views', (
      select jsonb_build_object(
        'all',        count(*),
        'mine',       count(*) filter (where v_me is not null and f.owner_id = v_me),
        'waiting',    count(*) filter (where f.requires_human_attention),
        'today',      count(*) filter (where (f.created_at at time zone 'Asia/Kolkata')::date = v_today),
        'overdue',    count(*) filter (where f.follow_up_date < v_today),
        'hot',        count(*) filter (where f.priority = 'high' or f.stage in ('demo', 'trial', 'quote')),
        'new',        count(*) filter (where f.stage = 'new'),
        'stalled',    count(*) filter (where f.stage_changed_at is not null and f.stage_changed_at <= now() - interval '7 days'),
        'closing',    count(*) filter (where f.expected_close_date <= v_month_end),
        'duplicates', count(*) filter (where f.dup))
        from flagged f where f.open and (v_page_stages is null or f.stage = any (v_page_stages))),
    'folders', (
      select jsonb_build_object(
        'inbox',    count(*) filter (where not s.is_junk and s.stage = 'new'),
        'talks',    count(*) filter (where not s.is_junk and s.stage = 'contact'),
        'quoted',   count(*) filter (where not s.is_junk and s.stage = 'quote'),
        'proving',  count(*) filter (where not s.is_junk and s.stage in ('demo', 'trial')),
        'won',      count(*) filter (where s.stage = 'won'),
        'lost',     count(*) filter (where s.stage = 'lost'),
        'hot',      count(*) filter (where s.open and (s.priority = 'high' or coalesce(s.value, 0) >= 100000)),
        'followup', count(*) filter (where s.open and s.follow_up_date <= v_today))
        from searched s),
    'list', (
      select jsonb_build_object(
        'matching', count(*),
        'hot',      count(*) filter (where t.stage in ('quote', 'trial')),
        'hot_top',  (select jsonb_build_object(
                              'id', h.id, 'company', h.company, 'contact_name', h.contact_name,
                              'contact_email', h.contact_email, 'contact_phone', h.contact_phone,
                              'plan', h.plan, 'value', h.value, 'stage', h.stage)
                       from listed h
                      where h.stage in ('quote', 'trial')
                      order by coalesce(h.value, 0) desc, h.created_at desc, h.id desc
                      limit 1))
        from listed t),
    'kpi', (
      select jsonb_build_object(
        'open_count',         count(*) filter (where w.stage not in ('won', 'lost')),
        'open_value',         coalesce(sum(coalesce(w.value, 0)) filter (where w.stage not in ('won', 'lost')), 0),
        'open_value_project', coalesce(sum(coalesce(w.value, 0)) filter (where w.stage not in ('won', 'lost')
                                                                        and w.enquiry_type = 'project'), 0),
        'won',                count(*) filter (where w.stage = 'won'),
        'lost',               count(*) filter (where w.stage = 'lost'))
        from ws w where not w.is_junk),
    'stage_totals', (
      select coalesce(jsonb_object_agg(t.stage, jsonb_build_object(
               'count', t.n, 'value', t.total, 'weighted', t.weighted)), '{}'::jsonb)
        from (select s.stage,
                     count(*) as n,
                     coalesce(sum(greatest(coalesce(s.value, 0), 0)), 0) as total,
                     /* forecast.ts#STAGE_PROBABILITY — lead-counts-sql-copy.test.ts holds the
                        two tables equal. round() per deal, as weightedValue does. */
                     coalesce(sum(case when coalesce(s.value, 0) > 0 then
                       round(s.value::numeric * (case s.stage
                         when 'new' then 10 when 'contact' then 20 when 'demo' then 40
                         when 'trial' then 60 when 'quote' then 80 when 'won' then 100
                         else 0 end) / 100) else 0 end), 0)::bigint as weighted
                from searched s
               group by s.stage) t)
  ) into v_out;

  return v_out;
end
$function$;

-- public.list_leads
CREATE OR REPLACE FUNCTION public.list_leads(p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 50, p_filters jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_limit     integer := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_f         jsonb   := coalesce(p_filters, '{}'::jsonb);
  v_sort      text    := coalesce(nullif(v_f->>'sort', ''), 'created');
  v_view      text    := nullif(v_f->>'smart_view', '');
  v_folder    text    := coalesce(nullif(v_f->>'folder', ''), 'all');
  v_today     date    := (now() at time zone 'Asia/Kolkata')::date;
  v_c_at      timestamptz;
  v_c_key     numeric;
  v_c_id      text;
  v_search    text;
  v_pattern   text;
  v_stages    text[];
  v_prios     text[];
  v_junk      text    := coalesce(nullif(v_f->>'junk', ''), 'exclude');
  v_owner_ids uuid[];
  v_owner_id  uuid    := nullif(v_f->>'owner_id', '')::uuid;
  v_owners    text[];
  v_open_only boolean := coalesce((v_f->>'open_only')::boolean, false);
  v_dup_of    text    := nullif(v_f->>'dup_of', '');
  v_like      jsonb   := case when jsonb_typeof(v_f->'dup_like') = 'object' then v_f->'dup_like' end;
  v_of_p      text;
  v_of_c      text;
  v_of_ids    text[];
  v_rows      jsonb;
  v_keys      jsonb;
  v_count     integer;
  v_last      integer;
begin
  if v_sort not in ('created', 'wait') then
    raise exception 'list_leads: sort must be created or wait (got %)', v_sort using errcode = '22023';
  end if;
  if v_view is not null and v_view not in ('everything', 'all', 'mine', 'waiting', 'today', 'overdue', 'hot', 'new',
                                          'won-mtd', 'closing', 'stalled', 'duplicates', 'junk') then
    raise exception 'list_leads: unknown smart_view %', v_view using errcode = '22023';
  end if;
  if v_folder not in ('all', 'inbox', 'talks', 'quoted', 'proving', 'won', 'lost', 'hot', 'followup') then
    raise exception 'list_leads: unknown folder %', v_folder using errcode = '22023';
  end if;

  if p_cursor is not null and jsonb_typeof(p_cursor) <> 'null' then
    v_c_id := nullif(p_cursor->>'id', '');
    if v_sort = 'wait' then
      v_c_key := nullif(p_cursor->>'wait_key', '')::numeric;
      if v_c_key is null or v_c_id is null then
        raise exception 'list_leads: the cursor needs both wait_key and id — pass back next_cursor exactly as it was returned, or null for the first page'
          using errcode = '22023';
      end if;
    else
      v_c_at := nullif(p_cursor->>'created_at', '')::timestamptz;
      if v_c_at is null or v_c_id is null then
        raise exception 'list_leads: the cursor needs both created_at and id — pass back next_cursor exactly as it was returned, or null for the first page'
          using errcode = '22023';
      end if;
    end if;
  end if;

  if v_junk not in ('exclude', 'only', 'any') then
    raise exception 'list_leads: junk must be exclude, only or any (got %)', v_junk using errcode = '22023';
  end if;
  /* A smart view decides the junk cut, as searchLeads step 0 does. */
  if v_view is not null then
    v_junk := case when v_view = 'junk' then 'view' else 'exclude' end;
  end if;

  if btrim(coalesce(v_f->>'search', '')) <> '' then
    v_search  := lower(v_f->>'search');
    v_pattern := '%' || replace(replace(replace(v_search, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  end if;

  if jsonb_typeof(v_f->'stages') = 'array' and jsonb_array_length(v_f->'stages') > 0 then
    select array_agg(x) into v_stages from jsonb_array_elements_text(v_f->'stages') x;
  end if;
  if jsonb_typeof(v_f->'priorities') = 'array' and jsonb_array_length(v_f->'priorities') > 0 then
    select array_agg(x) into v_prios from jsonb_array_elements_text(v_f->'priorities') x;
  end if;
  if jsonb_typeof(v_f->'owner_ids') = 'array' then
    select coalesce(array_agg(x::uuid), '{}') into v_owner_ids from jsonb_array_elements_text(v_f->'owner_ids') x;
  end if;
  if jsonb_typeof(v_f->'owners') = 'array' and jsonb_array_length(v_f->'owners') > 0 then
    select array_agg(x) into v_owners from jsonb_array_elements_text(v_f->'owners') x;
  end if;

  /* dup_of — the other leads that make THIS one a duplicate (the page's matchesOf), for the
     merge dialog: same workspace, same keys, not the lead itself.

     Why the keys are read through "offset 0" and never compared in a WHERE on the leads
     scan: leads has RLS, and Postgres will not evaluate a non-LEAKPROOF function (these
     key functions) ahead of the policy quals — so "key = x" can never be an index
     condition, and a filter on it recomputes the key for every lead (2.9 s for one page at
     20,000 leads, measured). Selecting the key as a COLUMN lets the planner read it from
     leads_dup_*_idx with an index-only scan instead (≈13 ms). LEAKPROOF itself needs a
     superuser, which a migration on hosted Supabase is not.

     dup_like — the same match for a lead that does not exist yet: the Add-lead form's "this
     company / phone is already a lead" warning. { company, contact_phone, exclude_id } —
     exclude_id is the lead being edited, which must not warn about itself. */
  if v_dup_of is not null then
    select public.lead_norm_phone(me.contact_phone), public.lead_norm_company(me.company)
      into v_of_p, v_of_c
      from public.leads me
     where me.id = v_dup_of and me.tenant_id = public.current_tenant_id();
  elsif v_like is not null then
    v_of_p   := public.lead_norm_phone(v_like->>'contact_phone');
    v_of_c   := public.lead_norm_company(v_like->>'company');
    v_dup_of := coalesce(nullif(v_like->>'exclude_id', ''), '');
  end if;
  if v_dup_of is not null then
    select coalesce(array_agg(distinct x.id), '{}') into v_of_ids from (
      select k.id
        from (select g.id, public.lead_norm_phone(g.contact_phone) as key
                from public.leads g
               where g.tenant_id = public.current_tenant_id()
                 and (v_owner_ids is null or g.owner_id is null or g.owner_id = any (v_owner_ids))
                 and (v_owner_id is null or g.owner_id = v_owner_id)
              offset 0) k
       where coalesce(v_of_p, '') <> '' and k.key = v_of_p and k.id <> v_dup_of
      union
      select k.id
        from (select g.id, public.lead_norm_company(g.company) as key
                from public.leads g
               where g.tenant_id = public.current_tenant_id()
                 and (v_owner_ids is null or g.owner_id is null or g.owner_id = any (v_owner_ids))
                 and (v_owner_id is null or g.owner_id = v_owner_id)
              offset 0) k
       where coalesce(v_of_c, '') <> '' and k.key = v_of_c and k.id <> v_dup_of
    ) x;
  end if;

  with dup as materialized (
    /* computeDuplicates(workspaceLeads) — every workspace lead (team cut only, junk
       included) whose phone key or company key ANOTHER workspace lead shares. Keys come
       from leads_dup_*_idx through index-only scans, counted with a window (see dup_of
       above for why it is never a WHERE). Read lazily: only the 'duplicates' view and the
       page's own rows ask for it. */
    select s.id
      from (select g.id, public.lead_norm_phone(g.contact_phone) as k,
                   count(*) over (partition by public.lead_norm_phone(g.contact_phone)) as n
              from public.leads g
             where g.tenant_id = public.current_tenant_id()
               and (v_owner_ids is null or g.owner_id is null or g.owner_id = any (v_owner_ids))
               and (v_owner_id is null or g.owner_id = v_owner_id)) s
     where s.n > 1 and s.k <> ''
    union
    select s.id
      from (select g.id, public.lead_norm_company(g.company) as k,
                   count(*) over (partition by public.lead_norm_company(g.company)) as n
              from public.leads g
             where g.tenant_id = public.current_tenant_id()
               and (v_owner_ids is null or g.owner_id is null or g.owner_id = any (v_owner_ids))
               and (v_owner_id is null or g.owner_id = v_owner_id)) s
     where s.n > 1 and s.k <> ''
  ), cand as (
    select l.id, l.company, l.contact_name, l.contact_email, l.contact_phone,
           l.plan, l.seats, l.value, l.stage, l.priority, l.owner_id, l.source,
           l.is_junk, l.created_at, l.updated_at, l.follow_up_date, l.expected_close_date,
           l.stage_changed_at, l.enquiry_type, l.project_id, l.customer_id,
           l.requires_human_attention, l.pipeline, l.subscription_type, l.lost_reason,
           l.domain, l.human_attention_reason,
           /* waitPriority as one stable number: still waiting → 1e12 − arrival epoch (older
              = bigger, and it does not drift with the clock, so a cursor stays valid);
              answered → seconds to first reply (≥ 0). Every waiting key is above every
              answered one, which is waitPriority's "waiting beats any answered lead". */
           case when v_sort = 'wait' then
             case when fr.at is null
                  then 1000000000000::numeric - extract(epoch from l.created_at)
                  else greatest(0::numeric, extract(epoch from fr.at) - extract(epoch from l.created_at))
             end
           end as wait_key
      from public.leads l
      /* lib/queries/lead-first-reply.ts: the first OUTBOUND touch (waiting.ts#OUTBOUND_KINDS),
         per lead through lead_activities_lead_idx. A grouped CTE joined back was planned as
         a nested loop — 22 s for one page at 20,000 leads; this is one index probe per lead.
         Skipped outright for the 'created' order. */
      left join lateral (
        select min(a.created_at) as at
          from public.lead_activities a
         where v_sort = 'wait'
           and a.lead_id = l.id
           and a.tenant_id = public.current_tenant_id()
           and a.kind in ('email', 'email_out', 'call', 'whatsapp', 'quote')
      ) fr on true
     where l.tenant_id = public.current_tenant_id()
       -- S37 keys
       and (v_junk in ('any', 'view') or (v_junk = 'only') = l.is_junk)
       and (v_junk <> 'view' or l.is_junk
            or public.lead_looks_like_junk(l.company, l.contact_name, l.contact_email, l.contact_phone))
       and (v_pattern is null
            or lower(l.company) like v_pattern escape '\'
            or lower(l.contact_name) like v_pattern escape '\'
            or lower(l.contact_email) like v_pattern escape '\'
            or lower(l.contact_phone) like v_pattern escape '\'
            or lower(l.plan) like v_pattern escape '\')
       and (v_stages is null or l.stage::text = any (v_stages))
       and (v_prios is null or l.priority = any (v_prios))
       and (v_owner_ids is null or l.owner_id is null or l.owner_id = any (v_owner_ids))
       and (v_owner_id is null or l.owner_id = v_owner_id)
       and (not v_open_only or (l.stage not in ('won', 'lost') and not l.is_junk))
       -- Kiska (searchLeads 3b)
       and (v_owners is null
            or (l.owner_id is null and '__unassigned' = any (v_owners))
            or l.owner_id::text = any (v_owners))
       -- smart view (searchLeads 4)
       and (v_view is null or v_view in ('everything', 'all', 'junk')
            or (v_view = 'mine'     and l.owner_id = public.current_user_id())
            or (v_view = 'waiting'  and l.requires_human_attention and l.stage not in ('won', 'lost'))
            or (v_view = 'today'    and (l.created_at at time zone 'Asia/Kolkata')::date = v_today)
            or (v_view = 'overdue'  and l.follow_up_date < v_today and l.stage not in ('won', 'lost'))
            or (v_view = 'hot'      and (l.priority = 'high' or l.stage in ('demo', 'trial', 'quote')))
            or (v_view = 'new'      and l.stage = 'new')
            or (v_view = 'won-mtd'  and l.stage = 'won'
                and coalesce(l.stage_changed_at, l.created_at) >= (date_trunc('month', v_today)::timestamp at time zone 'Asia/Kolkata'))
            or (v_view = 'closing'  and l.expected_close_date <= (date_trunc('month', v_today) + interval '1 month - 1 day')::date
                and l.stage not in ('won', 'lost'))
            or (v_view = 'stalled'  and l.stage not in ('won', 'lost')
                and l.stage_changed_at is not null and l.stage_changed_at <= now() - interval '7 days')
            or (v_view = 'duplicates' and l.id in (select d.id from dup d)))
       and (v_dup_of is null or l.id = any (v_of_ids))
       -- folder cut (listCut + inSalesFolder), only alongside a smart view
       and (v_view is null or v_view = 'junk'
            or (v_folder = 'all' and v_view = 'everything')
            or (v_folder = 'all'      and l.stage not in ('won', 'lost') and not l.is_junk)
            or (v_folder = 'inbox'    and not l.is_junk and l.stage = 'new')
            or (v_folder = 'talks'    and not l.is_junk and l.stage = 'contact')
            or (v_folder = 'quoted'   and not l.is_junk and l.stage = 'quote')
            or (v_folder = 'proving'  and not l.is_junk and l.stage in ('demo', 'trial'))
            or (v_folder = 'won'      and l.stage = 'won')
            or (v_folder = 'lost'     and l.stage = 'lost')
            or (v_folder = 'hot'      and not l.is_junk and l.stage not in ('won', 'lost')
                and (l.priority = 'high' or coalesce(l.value, 0) >= 100000))
            or (v_folder = 'followup' and not l.is_junk and l.stage not in ('won', 'lost')
                and l.follow_up_date <= v_today))
  ), page as (
    select c.*
      from cand c
     where v_c_id is null
        or (v_sort = 'wait'    and (c.wait_key, c.id) < (v_c_key, v_c_id))
        or (v_sort = 'created' and (c.created_at, c.id) < (v_c_at, v_c_id))
     order by case when v_sort = 'wait' then c.wait_key end desc,
              case when v_sort = 'created' then c.created_at end desc,
              c.id desc
     limit v_limit + 1
  ), numbered as (
    select p.*,
           /* The row's "Duplicate?" flag — only for the ≤ 51 rows of this page. */
           (p.id in (select d.id from dup d)) as is_duplicate,
           row_number() over (
             order by case when v_sort = 'wait' then p.wait_key end desc,
                      case when v_sort = 'created' then p.created_at end desc,
                      p.id desc) as rn
      from page p
  )
  select coalesce(jsonb_agg(to_jsonb(n) - 'rn' - 'wait_key' order by n.rn) filter (where n.rn <= v_limit), '[]'::jsonb),
         coalesce(jsonb_agg(jsonb_build_object('wait_key', n.wait_key::text, 'id', n.id, 'created_at', n.created_at)
                            order by n.rn) filter (where n.rn <= v_limit), '[]'::jsonb),
         count(*)::integer
    into v_rows, v_keys, v_count
    from numbered n;

  if v_count > v_limit then
    v_last := v_limit - 1;
    return jsonb_build_object(
      'rows', v_rows,
      'next_cursor', case when v_sort = 'wait'
                          then jsonb_build_object('wait_key', v_keys->v_last->'wait_key', 'id', v_keys->v_last->'id')
                          else jsonb_build_object('created_at', v_rows->v_last->'created_at', 'id', v_rows->v_last->'id')
                     end);
  end if;
  return jsonb_build_object('rows', v_rows, 'next_cursor', null);
end
$function$;

-- public.list_stranded_auth_users
CREATE OR REPLACE FUNCTION public.list_stranded_auth_users()
 RETURNS TABLE(email text, full_name text, created_at timestamp with time zone, last_sign_in_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
begin
  if not exists (select 1 from public.users u where u.id = public.current_user_id() and u.role = 'owner') then
    raise exception 'Only a workspace owner can see this.' using errcode = '42501';
  end if;

  return query
    select au.email::text,
           coalesce(
             nullif(btrim(au.raw_user_meta_data ->> 'full_name'), ''),
             nullif(btrim(au.raw_user_meta_data ->> 'name'), ''),
             split_part(au.email, '@', 1)
           )::text,
           au.created_at,
           au.last_sign_in_at
      from auth.users au
     where not exists (select 1 from public.users u where u.id = au.id)
       and au.email is not null
     order by au.last_sign_in_at desc nulls last, au.created_at desc;
end;
$function$;

-- public.list_tenant_backups
CREATE OR REPLACE FUNCTION public.list_tenant_backups()
 RETURNS TABLE(id uuid, created_at timestamp with time zone, label text, kind text, table_count integer, bytes integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.guard_backup_owner_only();
  return query
    select s.id, s.created_at, s.label, s.kind, s.table_count, length(s.payload::text)
      from backup.snapshots s
     where s.tenant_id = (select tenant_id from public.users where id = public.current_user_id())
     order by s.created_at desc;
end $function$;

-- public.log_activity
CREATE OR REPLACE FUNCTION public.log_activity(p_action text, p_entity text DEFAULT 'session'::text, p_entity_id text DEFAULT NULL::text, p_label text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid;
begin
  select tenant_id into v_tenant from public.users where id = public.current_user_id();
  if v_tenant is null then return; end if;
  insert into public.activity_log (tenant_id, user_id, action, entity, entity_id, label)
  values (v_tenant, public.current_user_id(), p_action, coalesce(p_entity, 'session'), p_entity_id, left(p_label, 120));
end $function$;

-- public.log_lead_activity
CREATE OR REPLACE FUNCTION public.log_lead_activity(p_lead_id text, p_kind text, p_detail text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid := public.current_tenant_id(); v_id uuid;
begin
  perform 1 from public.leads where id = p_lead_id and tenant_id = v_tenant;
  if not found then raise exception 'Lead not found'; end if;
  insert into public.lead_activities (tenant_id, lead_id, kind, detail, created_by)
  values (v_tenant, p_lead_id, coalesce(nullif(trim(p_kind), ''), 'note'),
          nullif(trim(coalesce(p_detail, '')), ''), public.current_user_id())
  returning id into v_id;
  return v_id;
end; $function$;

-- public.log_row_change
CREATE OR REPLACE FUNCTION public.log_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_json    jsonb;
  v_old     jsonb;
  v_tenant  uuid;
  v_id      text;
  v_label   text;
  v_changes jsonb;
  v_key     text;
  v_uid     uuid := public.current_user_id();
  v_user    uuid;
  v_actor   text;
begin
  if v_uid is null then return null; end if;
  if tg_op = 'DELETE' then v_json := to_jsonb(old); else v_json := to_jsonb(new); end if;
  v_tenant := nullif(v_json->>'tenant_id', '')::uuid;
  if v_tenant is null then return null; end if;
  v_id := v_json->>'id';
  v_label := coalesce(
    v_json->>'full_name', v_json->>'name', v_json->>'company', v_json->>'company_name',
    v_json->>'invoice_no', v_json->>'quote_no', v_json->>'title', v_json->>'vendor_name',
    v_json->>'category', v_json->>'kind', v_json->>'period', ''
  );

  if tg_op = 'UPDATE' then
    v_old := to_jsonb(old);
    v_changes := '{}'::jsonb;
    for v_key in select jsonb_object_keys(v_json) loop
      if v_key in ('updated_at', 'created_at') then continue; end if;
      if v_json->v_key is distinct from v_old->v_key then
        v_changes := v_changes || jsonb_build_object(v_key, jsonb_build_object('old', v_old->v_key, 'new', v_json->v_key));
      end if;
    end loop;
    if v_changes = '{}'::jsonb then return null; end if;   -- a touch, not a change
  elsif tg_op = 'DELETE' then
    v_changes := jsonb_build_object('old', v_json);
  end if;

  -- Who is acting: a staff user, or a portal customer (not in public.users).
  select u.id into v_user from public.users u where u.id = v_uid;
  if v_user is null then
    select 'Customer ' || c.name into v_actor
      from public.customer_users cu
      join public.customers c on c.id = cu.customer_id
     where cu.auth_user_id = v_uid
     limit 1;
  end if;

  insert into public.activity_log (tenant_id, user_id, actor_label, action, entity, entity_id, label, changes)
  values (v_tenant, v_user, left(v_actor, 120), lower(tg_op), tg_table_name, v_id, left(v_label, 120), v_changes);
  return null;
end $function$;

-- public.mark_self_attendance
CREATE OR REPLACE FUNCTION public.mark_self_attendance()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_emp uuid; v_date date; v_row public.attendance;
begin
  select tenant_id, employee_id into v_tenant, v_emp from public.users where id = public.current_user_id();
  if v_emp is null then raise exception 'Pehle apna employee link karo.'; end if;
  v_date := (now() at time zone 'Asia/Kolkata')::date;
  select * into v_row from public.attendance where tenant_id = v_tenant and employee_id = v_emp and work_date = v_date;
  if not found then
    insert into public.attendance (tenant_id, employee_id, work_date, check_in, source)
    values (v_tenant, v_emp, v_date, now(), 'self');
    return 'checked_in';
  elsif v_row.check_out is null then
    if now() - v_row.check_in < interval '90 seconds' then
      return 'too_soon';
    end if;
    update public.attendance set check_out = now() where id = v_row.id;
    return 'checked_out';
  else
    return 'already_done';
  end if;
end $function$;

-- public.merge_stranded_user_into_tenant
CREATE OR REPLACE FUNCTION public.merge_stranded_user_into_tenant(p_email text, p_tenant_id uuid, p_role user_role DEFAULT 'support'::user_role)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
declare
  v_email        text := lower(btrim(p_email));
  v_caller_tid   uuid;
  v_caller_role  public.user_role;
  v_dest_name    text;
  v_auth_id      uuid;
  v_auth_name    text;
  v_old_tid      uuid;
  v_old_name     text;
  v_old_users    int;
  v_sql          text;
  v_holdings     jsonb;
  v_rows         bigint;
  v_action       text;
  v_deleted      boolean := false;
begin
  -- ── 1. The caller must own the destination workspace ────────────────────
  select u.tenant_id, u.role
    into v_caller_tid, v_caller_role
    from public.users u
   where u.id = public.current_user_id();

  if v_caller_tid is null then
    raise exception
      'You are not signed in to a workspace, so there is nothing to claim this person into. Sign in again and reopen Team.'
      using errcode = '42501';
  end if;

  if v_caller_tid <> p_tenant_id or v_caller_role <> 'owner' then
    raise exception
      'Only the owner of a workspace can claim someone into it. Ask your workspace owner to open Team → Claim a colleague.'
      using errcode = '42501';
  end if;

  select t.name into v_dest_name from public.tenants t where t.id = p_tenant_id;

  -- ── 2. Do they have an account at all? ──────────────────────────────────
  select au.id,
         coalesce(
           nullif(btrim(au.raw_user_meta_data ->> 'full_name'), ''),
           nullif(btrim(au.raw_user_meta_data ->> 'name'), ''),
           split_part(au.email, '@', 1)
         )
    into v_auth_id, v_auth_name
    from auth.users au
   where lower(au.email) = v_email
   limit 1;

  if v_auth_id is null then
    raise exception
      'No account exists for %. Send them an invite from Team → Invite teammate using this exact address, ask them to sign in once, then claim them.',
      v_email
      using errcode = 'P0002';
  end if;

  -- ── 3. Where are they now? ──────────────────────────────────────────────
  select u.tenant_id into v_old_tid
    from public.users u
   where u.id = v_auth_id;

  -- 3a. Already here. Only the role may need correcting.
  if v_old_tid = p_tenant_id then
    update public.users set role = p_role where id = v_auth_id and role <> p_role;
    v_action := case when found then 'role_updated' else 'already_member' end;

  -- 3b. Truly stranded: an auth account with no profile anywhere. This is the
  --     thirteen. Nothing to move and nothing to delete — just give them a home.
  elsif v_old_tid is null then
    insert into public.users (id, tenant_id, email, full_name, initials, role, color)
    values (
      v_auth_id, p_tenant_id, v_email, v_auth_name,
      upper(left(regexp_replace(coalesce(v_auth_name, v_email), '[^A-Za-z]', '', 'g'), 2)),
      p_role, 'indigo'
    );
    v_action := 'attached';

  -- 3c. They are sitting in another tenant.
  else
    select t.name, (select count(*) from public.users u2 where u2.tenant_id = t.id)
      into v_old_name, v_old_users
      from public.tenants t where t.id = v_old_tid;

    -- A workspace with other people in it is somebody's real company, not a
    -- stray. Refuse before looking at data — this tool is for accidents.
    if v_old_users > 1 then
      raise exception
        'Cannot claim %: they belong to "%", which has % people in it. That is a separate company, not an accidental workspace. If it really should be merged, that is a platform-admin job.',
        v_email, v_old_name, v_old_users
        using errcode = '23505';
    end if;

    -- Count everything that is not bookkeeping. Fail-safe: unlisted table = data.
    select string_agg(
             format('select %L::text as tbl, count(*)::bigint as n from public.%I where tenant_id = %L',
                    c.table_name, c.table_name, v_old_tid),
             ' union all ')
      into v_sql
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema
       and t.table_name   = c.table_name
       and t.table_type   = 'BASE TABLE'
     where c.table_schema = 'public'
       and c.column_name  = 'tenant_id'
       and c.table_name not in (
             -- Bookkeeping only. None of these is a thing an operator would
             -- mourn, and all of them cascade with the tenant anyway.
             'users', 'activity_log', 'team_invites', 'tenant_secrets',
             'document_series', 'customer_number_seq', 'user_google_tokens',
             'tenant_domains', 'join_requests', 'email_log', 'api_keys'
           );

    execute format(
      'select coalesce(jsonb_object_agg(tbl, n) filter (where n > 0), ''{}''::jsonb),
              coalesce(sum(n), 0) from (%s) s', v_sql)
      into v_holdings, v_rows;

    if v_rows > 0 then
      raise exception
        'Cannot claim %: their workspace "%" still holds % records (%). Moving them out would leave that data with no one who can sign in and see it. Move or export the data first — this tool only clears empty workspaces.',
        v_email, v_old_name, v_rows, v_holdings::text
        using errcode = '23503';
    end if;

    update public.users
       set tenant_id = p_tenant_id,
           role      = p_role,
           email     = v_email
     where id = v_auth_id;

    -- Empty, and now nobody is in it. 78 of 80 tenant FKs cascade.
    delete from public.tenants where id = v_old_tid;
    v_deleted := true;
    v_action  := 'moved';
  end if;

  -- ── 4. Any open request from this person is now settled ─────────────────
  update public.join_requests
     set status = 'approved', decided_at = now(), decided_by = public.current_user_id()
   where tenant_id = p_tenant_id
     and lower(email) = v_email
     and status = 'pending_approval';

  -- ── 5. Visible in the destination workspace, not just in a server log ───
  insert into public.activity_log (tenant_id, user_id, action, entity, entity_id, label)
  values (
    p_tenant_id, public.current_user_id(), v_action, 'user', v_auth_id::text,
    format('Claimed %s into %s as %s%s',
           v_email, coalesce(v_dest_name, 'this workspace'), p_role,
           case when v_deleted then format(' (removed empty workspace "%s")', v_old_name) else '' end)
  );

  return jsonb_build_object(
    'action',          v_action,
    'email',           v_email,
    'full_name',       v_auth_name,
    'auth_user_id',    v_auth_id,
    'role',            p_role,
    'tenant_id',       p_tenant_id,
    'tenant_name',     v_dest_name,
    'old_tenant_name', v_old_name,
    'old_tenant_deleted', v_deleted
  );
end;
$function$;

-- public.my_attendance_history
CREATE OR REPLACE FUNCTION public.my_attendance_history(p_days integer DEFAULT 14)
 RETURNS TABLE(work_date date, check_in timestamp with time zone, check_out timestamp with time zone, source text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_emp uuid;
begin
  select tenant_id, employee_id into v_tenant, v_emp from public.users where id = public.current_user_id();
  if v_emp is null then return; end if;
  return query
    select a.work_date, a.check_in, a.check_out, a.source
    from public.attendance a
    where a.tenant_id = v_tenant and a.employee_id = v_emp
      and a.work_date >= ((now() at time zone 'Asia/Kolkata')::date - greatest(p_days, 1))
    order by a.work_date desc;
end $function$;

-- public.my_attendance_today
CREATE OR REPLACE FUNCTION public.my_attendance_today()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_emp uuid; v_name text; v_date date; v_row public.attendance;
        v_consent timestamptz; v_retention int; v_face timestamptz;
begin
  select tenant_id, employee_id into v_tenant, v_emp from public.users where id = public.current_user_id();
  if v_emp is null then return jsonb_build_object('linked', false); end if;
  select name, attendance_consent_at, face_enrolled_at into v_name, v_consent, v_face from public.employees where id = v_emp;
  select coalesce(selfie_retention_days, 180) into v_retention from public.attendance_settings where tenant_id = v_tenant;
  v_date := (now() at time zone 'Asia/Kolkata')::date;
  select * into v_row from public.attendance where tenant_id = v_tenant and employee_id = v_emp and work_date = v_date;
  return jsonb_build_object(
    'linked', true, 'employee_name', v_name, 'work_date', v_date,
    'check_in', v_row.check_in, 'check_out', v_row.check_out,
    'consent_at', v_consent, 'retention_days', coalesce(v_retention, 180),
    'face_enrolled', (v_face is not null)
  );
end $function$;

-- public.nav_badges
CREATE OR REPLACE FUNCTION public.nav_badges(p_approval_tiers text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_me     uuid := public.current_user_id();
  v_tenant uuid := public.current_tenant_id();
  -- End of today in IST, as an instant (same as the hook's startUTC + 24h).
  v_eod    timestamptz := ((date_trunc('day', now() at time zone 'Asia/Kolkata') + interval '1 day')
                           at time zone 'Asia/Kolkata');
  -- The hook used new Date(Date.now() + 30d).toISOString().split("T")[0] — a UTC date.
  v_renew  date := ((now() at time zone 'UTC') + interval '720 hours')::date;
  v_quotes integer := 0;
begin
  if v_tenant is null then
    raise exception 'nav_badges: no workspace for this session'
      using errcode = 'insufficient_privilege';
  end if;

  if v_me is not null and coalesce(array_length(p_approval_tiers, 1), 0) > 0 then
    select count(*) into v_quotes
      from public.quotes q
     where q.approval_status = 'pending'
       and q.approval_requested_by <> v_me
       and q.approval_tier::text = any (p_approval_tiers);
  end if;

  return jsonb_build_object(
    'leads',     (select count(*) from public.leads l where l.stage in ('new', 'contact')),
    'enquiries', (select count(*) from public.inbound_emails e where e.status = 'received' and e.lead_id is null),
    'deals',     (select count(*) from public.leads l where l.stage in ('quote', 'demo', 'trial')),
    'tasks',     (select count(*) from public.tasks t where t.status = 'pending' and t.due_at < v_eod),
    'renewals',  (select count(*) from public.subscriptions s where s.status = 'active' and s.renewal_date <= v_renew),
    'invoices',  (select count(*) from public.invoices i where i.status in ('pending', 'overdue')),
    'payments',  (select count(*) from public.quotes q where q.payment_status = 'received'),
    'quotes',    v_quotes
  );
end;
$function$;

-- public.portal_ensure_customer_link
CREATE OR REPLACE FUNCTION public.portal_ensure_customer_link()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid          uuid := public.current_user_id();
  v_email        text;
  v_customer_id  uuid;
  v_tenant_id    uuid;
begin
  if v_uid is null then
    return 'no_auth';
  end if;

  select email into v_email from auth.users where id = v_uid;
  if v_email is null or length(trim(v_email)) = 0 then
    return 'no_auth';
  end if;

  if exists (select 1 from public.customer_users where auth_user_id = v_uid) then
    update public.customer_users set last_login_at = now() where auth_user_id = v_uid;
    return 'already';
  end if;

  select id, tenant_id into v_customer_id, v_tenant_id
    from public.customers
   where lower(contact_email) = lower(trim(v_email))
   limit 1;

  if v_customer_id is null then
    return 'no_customer';
  end if;

  insert into public.customer_users
    (tenant_id, customer_id, auth_user_id, email, role, last_login_at)
  values
    (v_tenant_id, v_customer_id, v_uid, v_email, 'admin', now());

  return 'linked';
end;
$function$;

-- public.portal_list_products
CREATE OR REPLACE FUNCTION public.portal_list_products()
 RETURNS TABLE(id text, name text, vendor text, price_per_seat_month integer, hsn text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    i.id,
    i.name,
    i.vendor::text,
    coalesce(
      nullif((i.prices->'annual'->>'msrp'), '')::int,
      i.msrp
    ) as price_per_seat_month,
    i.hsn
  from public.items i
  where i.is_active = true
    and i.kind = 'main'
    and i.tenant_id = (
      select cu.tenant_id from public.customer_users cu
      where cu.auth_user_id = public.current_user_id()
      limit 1
    )
  order by coalesce(nullif((i.prices->'annual'->>'msrp'),'')::int, i.msrp) asc, i.name asc;
$function$;

-- public.portal_request_quote
CREATE OR REPLACE FUNCTION public.portal_request_quote(p_item_id text, p_seats integer, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid       uuid := public.current_user_id();
  v_customer  record;
  v_item      record;
  v_seats     int;
  v_rate      int;
  v_value     int;
  v_lead_id   text;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = 'insufficient_privilege';
  end if;

  select c.id as customer_id, c.tenant_id, c.name, c.contact_email,
         c.contact_phone, c.gstin, c.state, c.state_code
    into v_customer
  from public.customer_users cu
  join public.customers c on c.id = cu.customer_id
  where cu.auth_user_id = v_uid
  limit 1;

  if v_customer.customer_id is null then
    raise exception 'no customer account' using errcode = 'no_data_found';
  end if;

  select i.id, i.name,
         coalesce(nullif((i.prices->'annual'->>'msrp'),'')::int, i.msrp) as rate
    into v_item
  from public.items i
  where i.id = p_item_id
    and i.tenant_id = v_customer.tenant_id
    and i.is_active = true
    and i.kind = 'main'
  limit 1;

  if v_item.id is null then
    raise exception 'product not available' using errcode = 'no_data_found';
  end if;

  v_seats := greatest(1, least(coalesce(p_seats, 1), 100000));
  v_rate  := coalesce(v_item.rate, 0);
  v_value := v_seats * v_rate * 12;

  v_lead_id := 'L-' || upper(substr(md5(gen_random_uuid()::text), 1, 10));

  insert into public.leads (
    id, tenant_id, company, contact_name, contact_email, contact_phone,
    plan, seats, value, stage, source, priority, gstin, state, state_code, notes
  ) values (
    v_lead_id,
    v_customer.tenant_id,
    v_customer.name,
    v_customer.name,
    v_customer.contact_email,
    v_customer.contact_phone,
    v_item.name,
    v_seats,
    v_value,
    'new',
    'Customer Portal',
    'high',
    v_customer.gstin,
    v_customer.state,
    v_customer.state_code,
    'Portal upsell request from existing customer "' || v_customer.name ||
      '" for ' || v_item.name || ' × ' || v_seats || ' seats.' ||
      case when p_note is not null and length(trim(p_note)) > 0
           then ' Note: ' || left(trim(p_note), 500) else '' end
  );

  return v_lead_id;
end;
$function$;

-- public.portal_touch_login
CREATE OR REPLACE FUNCTION public.portal_touch_login()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.customer_users
     set last_login_at = now()
   where auth_user_id = public.current_user_id();
end;
$function$;

-- public.raise_project_milestone_invoice
CREATE OR REPLACE FUNCTION public.raise_project_milestone_invoice(p_milestone_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant   uuid := public.current_tenant_id();
  v_ms       record;
  v_proj     record;
  v_id       text;
  v_paid     integer;
  v_full     boolean;
  v_pay_date date;
  v_inv_date date;
  v_rate     integer;
  v_taxable  integer;
  v_tax      integer;
  v_lines    jsonb;
begin
  select * into v_ms from public.project_milestones where id = p_milestone_id for update;
  if not found then raise exception 'Milestone not found'; end if;
  /* R-013 (Pardeep, 27 Sep 2026): the hardened form. The old guard opened by testing
     that the tenant was NOT null and only then comparing — so a NULL tenant skipped the
     comparison entirely, which is the anon case and the signed-in-but-no-users-row case,
     and quote/invoice ids are countable. Migration 20260927100000 rewrote 17 definer RPCs
     by regex; this file recreates one of them, so it must carry the hardened shape
     forward or it silently undoes that fix.

     The old wording is deliberately NOT quoted here. `definer_rpc_hardening.test.sql`
     FAIL 4 scans `pg_get_functiondef`, which includes COMMENTS — so writing the phrase in
     prose turns that security test red for no reason (AGENTS.md L46). Verified: quoting it
     did exactly that. */
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated'))
     or (v_tenant is not null and v_ms.tenant_id is distinct from v_tenant) then
    raise exception 'Milestone not in caller''s tenant' using errcode = 'insufficient_privilege';
  end if;
  if v_ms.invoice_id is not null then
    raise exception 'Invoice % already raised for this milestone', v_ms.invoice_id
      using errcode = 'unique_violation';
  end if;

  select * into v_proj from public.project_sales where id = v_ms.project_id;

  select coalesce(sum(amount), 0), min(received_at)
    into v_paid, v_pay_date
    from public.project_payments where milestone_id = p_milestone_id;
  v_full := v_paid >= v_ms.total_amount;

  -- R-003. Was: the first payment's date when fully paid. The number is allocated
  -- below, from today's series, so any earlier date puts the two out of step.
  v_inv_date := public.ist_today();

  v_rate    := coalesce(v_proj.gst_rate, 18);
  v_taxable := round(v_ms.total_amount * 100.0 / (100 + v_rate));
  v_tax     := v_ms.total_amount - v_taxable;

  /* R-010. ONE line, qty 1, rate = this milestone's taxable value — so qty × rate is the
     amount and the document cannot contradict itself. The SAC comes from the project, not
     from a literal: `project_sales.sac_code` is NOT NULL and defaults to 998314. */
  v_lines := jsonb_build_array(jsonb_build_object(
    'id',          'milestone-' || v_ms.seq::text,
    'name',        coalesce(nullif(btrim(v_proj.title), ''), 'Project services')
                   || ' — '
                   || coalesce(nullif(btrim(v_ms.label), ''), 'Milestone ' || v_ms.seq::text),
    'description', nullif(btrim(coalesce(v_proj.description, '')), ''),
    'qty',         1,
    'rate',        v_taxable,
    'cost',        0,
    'hsn',         v_proj.sac_code
  ));

  v_id := public.next_document_number('invoice', v_ms.tenant_id, public.ist_today());
  if v_id is null then raise exception 'Could not allocate invoice number'; end if;

  insert into public.invoices
    (id, tenant_id, customer_id, customer_name, amount, status,
     invoice_date, due_date, paid_date, adjusted_advances, net_payable, quote_id,
     taxable_value, tax_amount, tax_rate, inter_state, line_items)
  values
    (v_id, v_ms.tenant_id, v_proj.customer_id, v_proj.customer_name, v_ms.total_amount,
     (case when v_full then 'paid' else 'pending' end)::invoice_status,
     v_inv_date, greatest(coalesce(v_ms.due_date, v_inv_date), v_inv_date),
     -- The money's own date, not the document's. An advance really did arrive then.
     case when v_full then v_pay_date else null end,
     '[]'::jsonb,
     case when v_full then 0 else v_ms.total_amount end,
     null,
     v_taxable, v_tax, v_rate, coalesce(v_proj.inter_state, false), v_lines);

  update public.project_milestones
     set invoice_id = v_id,
         status     = case when v_full then 'paid' else 'invoiced' end
   where id = p_milestone_id;

  return v_id;
end;
$function$;

-- public.rate_limit_hit
CREATE OR REPLACE FUNCTION public.rate_limit_hit(p_key text, p_limit integer, p_window_ms integer)
 RETURNS TABLE(allowed boolean, hits integer, retry_after_sec integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  /* export_snapshots_for_offsite wala hi doosra pehra: asli deewar grant hai, ye us din ke
     liye jab koi grant galti se khul jaye. nullif(…,'') — khaali claims ''::jsonb par marte. */
  v_role text := coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role', '');
  v_now  timestamptz := clock_timestamp();
  v_hits integer;
  v_reset timestamptz;
begin
  if public.current_user_id() is not null or v_role in ('authenticated', 'anon') then
    raise exception 'rate_limit_hit is service_role only';
  end if;
  if p_key is null or length(p_key) = 0 or length(p_key) > 128 then
    raise exception 'rate_limit_hit: key 1..128 chars hona chahiye (TS sha256 hex bhejta hai)';
  end if;
  if p_limit is null or p_limit < 1 or p_window_ms is null or p_window_ms < 1000 or p_window_ms > 86400000 then
    raise exception 'rate_limit_hit: limit >= 1 aur window 1s..24h honi chahiye';
  end if;

  insert into public.rate_limit_buckets as b (key, hits, reset_at)
  values (p_key, 1, v_now + make_interval(secs => p_window_ms / 1000.0))
  on conflict (key) do update
    set hits     = case when b.reset_at <= v_now then 1 else b.hits + 1 end,
        reset_at = case when b.reset_at <= v_now then excluded.reset_at else b.reset_at end
  returning b.hits, b.reset_at into v_hits, v_reset;

  if random() < 0.01 then
    delete from public.rate_limit_buckets where reset_at < v_now - interval '1 hour';
  end if;

  return query select
    v_hits <= p_limit,
    v_hits,
    case when v_hits <= p_limit then 0
         else greatest(1, ceil(extract(epoch from (v_reset - v_now)))::integer) end;
end;
$function$;

-- public.reconcile_bank_txn
CREATE OR REPLACE FUNCTION public.reconcile_bank_txn(p_txn_id uuid, p_matched_to_type text, p_matched_to_id text, p_match_confidence text)
 RETURNS bank_transactions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_txn    public.bank_transactions;
  v_row    public.bank_transactions;
  v_tax_expenses text[];
  v_used   integer;
begin
  select * into v_txn from public.bank_transactions where id = p_txn_id;
  if not found then
    raise exception 'Bank transaction not found' using errcode = 'no_data_found';
  end if;
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated')) or (v_tenant is not null and v_txn.tenant_id is distinct from v_tenant) then
    raise exception 'Not in caller''s tenant' using errcode = 'insufficient_privilege';
  end if;

  -- A prepaid line that stops being one: refuse if its advance was already used.
  if v_txn.matched_to_type = 'prepaid' and p_matched_to_type is distinct from 'prepaid' then
    select coalesce(sum(consumed_amount), 0) into v_used
      from public.prepaid_advances where bank_txn_id = p_txn_id;
    if v_used > 0 then
      raise exception 'This advance has ₹% already booked as expenses from invoices. Delete those invoice expenses first (Prepaid page), then un-reconcile.', v_used;
    end if;
  end if;

  if p_matched_to_type is not null then
    update public.bank_transactions
       set matched_to_type  = p_matched_to_type,
           matched_to_id    = p_matched_to_id,
           matched_at       = now(),
           matched_by       = public.current_user_id(),
           match_confidence = coalesce(p_match_confidence, 'manual')
     where id = p_txn_id
     returning * into v_row;
  else
    update public.bank_transactions
       set matched_to_type  = null,
           matched_to_id    = null,
           matched_at       = null,
           matched_by       = null,
           match_confidence = null
     where id = p_txn_id
     returning * into v_row;
  end if;

  if p_matched_to_type is distinct from 'prepaid' then
    delete from public.prepaid_advances where bank_txn_id = p_txn_id;
  end if;

  -- Tax payment on this line: gone once the line is no longer a tax payment.
  if p_matched_to_type is distinct from 'statutory' then
    select array_agg(expense_id) filter (where expense_id is not null) into v_tax_expenses
      from public.tax_payments where bank_txn_id = p_txn_id;
    delete from public.tax_payments where bank_txn_id = p_txn_id;
    if v_tax_expenses is not null then
      delete from public.expenses where id = any (v_tax_expenses);
    end if;
  end if;

  -- Reverse link on project_payments: clear any stale pointer to this line,
  -- then set it when matching to a project payment. (project_payments.id is uuid.)
  update public.project_payments set bank_txn_id = null where bank_txn_id = p_txn_id;
  if p_matched_to_type = 'project' and p_matched_to_id is not null then
    update public.project_payments set bank_txn_id = p_txn_id where id = p_matched_to_id::uuid;
  end if;

  -- Reverse link on expenses: same clear-then-set. (expenses.id is text.)
  update public.expenses set reconciled_txn_id = null where reconciled_txn_id = p_txn_id;
  if p_matched_to_type = 'expense' and p_matched_to_id is not null then
    update public.expenses set reconciled_txn_id = p_txn_id where id = p_matched_to_id;
  end if;

  -- Un-reconcile also reverses a line booked as capital / director's loan
  -- (balance sheet) or a statutory (TDS/PF/ESI) challan, so nothing drifts.
  if p_matched_to_type is null then
    delete from public.balance_sheet_items       where bank_txn_id = p_txn_id;
    delete from public.statutory_dues_payments    where bank_txn_id = p_txn_id;
  end if;

  return v_row;
end;
$function$;

-- public.reconcile_expenses_to_bank_txn
CREATE OR REPLACE FUNCTION public.reconcile_expenses_to_bank_txn(p_bank_txn_id uuid, p_expense_ids text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_txn    public.bank_transactions;
  v_sum    integer;
  v_cnt    integer;
  v_want   integer := coalesce(array_length(p_expense_ids, 1), 0);
begin
  select * into v_txn from public.bank_transactions where id = p_bank_txn_id;
  if not found then raise exception 'Bank transaction not found'; end if;
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated')) or (v_tenant is not null and v_txn.tenant_id is distinct from v_tenant) then
    raise exception 'Not in caller''s tenant' using errcode = 'insufficient_privilege';
  end if;
  if v_txn.debit <= 0 then
    raise exception 'Only a money-out (debit) line can be matched to expenses' using errcode = 'invalid_parameter_value';
  end if;
  if v_txn.matched_to_type is not null then
    raise exception 'This line is already reconciled — un-reconcile it first' using errcode = 'invalid_parameter_value';
  end if;
  if v_want < 1 then raise exception 'Pick at least one expense to match'; end if;

  select coalesce(sum(amount), 0), count(*) into v_sum, v_cnt
  from public.expenses
  where id = any (p_expense_ids) and tenant_id = v_txn.tenant_id and reconciled_txn_id is null;

  if v_cnt <> v_want then
    raise exception 'Some selected expenses are missing or already reconciled — refresh and try again'
      using errcode = 'invalid_parameter_value';
  end if;
  if v_sum <> v_txn.debit then
    raise exception 'Selected expenses total % but this bank line is % — they must add up exactly', v_sum, v_txn.debit
      using errcode = 'invalid_parameter_value';
  end if;

  update public.expenses set reconciled_txn_id = p_bank_txn_id
   where id = any (p_expense_ids) and tenant_id = v_txn.tenant_id;

  update public.salary_payments sp
     set paid_status = 'paid', paid_amount = sp.net, reconciled_txn_id = p_bank_txn_id
   where sp.tenant_id = v_txn.tenant_id and sp.expense_id = any (p_expense_ids) and sp.paid_status <> 'paid';

  update public.bank_transactions
     set matched_to_type = 'split', matched_to_id = null,
         matched_at = now(), matched_by = public.current_user_id(), match_confidence = 'manual'
   where id = p_bank_txn_id;
end;
$function$;

-- public.reconcile_salaries_to_bank_txn
CREATE OR REPLACE FUNCTION public.reconcile_salaries_to_bank_txn(p_bank_txn_id uuid, p_salary_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_txn    public.bank_transactions;
  v_sum    integer;
  v_cnt    integer;
  v_want   integer := coalesce(array_length(p_salary_ids, 1), 0);
begin
  select * into v_txn from public.bank_transactions where id = p_bank_txn_id;
  if not found then raise exception 'Bank transaction not found'; end if;
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated')) or (v_tenant is not null and v_txn.tenant_id is distinct from v_tenant) then
    raise exception 'Not in caller''s tenant' using errcode = 'insufficient_privilege';
  end if;
  if v_txn.debit <= 0 then
    raise exception 'Only a money-out (debit) line can be matched to salaries' using errcode = 'invalid_parameter_value';
  end if;
  if v_txn.matched_to_type is not null then
    raise exception 'This line is already reconciled — un-reconcile it first' using errcode = 'invalid_parameter_value';
  end if;
  if v_want < 1 then raise exception 'Pick at least one salary to match'; end if;

  select coalesce(sum(net), 0), count(*) into v_sum, v_cnt
  from public.salary_payments
  where id = any (p_salary_ids) and tenant_id = v_txn.tenant_id
    and paid_status = 'unpaid' and reconciled_txn_id is null;

  if v_cnt <> v_want then
    raise exception 'Some selected salaries are missing or already paid — refresh and try again'
      using errcode = 'invalid_parameter_value';
  end if;
  if v_sum <> v_txn.debit then
    raise exception 'Selected salaries total % but this bank line is % — they must add up exactly', v_sum, v_txn.debit
      using errcode = 'invalid_parameter_value';
  end if;

  update public.salary_payments
     set paid_status = 'paid', reconciled_txn_id = p_bank_txn_id
   where id = any (p_salary_ids) and tenant_id = v_txn.tenant_id;

  update public.bank_transactions
     set matched_to_type = 'split', matched_to_id = null,
         matched_at = now(), matched_by = public.current_user_id(), match_confidence = 'manual'
   where id = p_bank_txn_id;
end;
$function$;

-- public.reconcile_salary_advance_split
CREATE OR REPLACE FUNCTION public.reconcile_salary_advance_split(p_txn_id uuid, p_salary_id uuid, p_advance_amount integer, p_employee_name text, p_notes text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_txn public.bank_transactions%rowtype;
  v_sal public.salary_payments%rowtype;
  v_salary_portion integer;
begin
  select * into v_txn from public.bank_transactions where id = p_txn_id and tenant_id = v_tenant;
  if not found then raise exception 'Bank line not found'; end if;
  if v_txn.matched_to_type is not null then raise exception 'This line is already reconciled'; end if;
  if coalesce(v_txn.debit, 0) <= 0 then raise exception 'Only a money-out line can be split into salary + advance'; end if;

  select * into v_sal from public.salary_payments where id = p_salary_id and tenant_id = v_tenant;
  if not found then raise exception 'Salary not found'; end if;

  if p_advance_amount is null or p_advance_amount <= 0 then raise exception 'Advance amount must be positive'; end if;
  v_salary_portion := v_txn.debit - p_advance_amount;
  if v_salary_portion <= 0 then raise exception 'Salary portion must be positive'; end if;
  if v_salary_portion > (v_sal.net - v_sal.paid_amount) then
    raise exception 'Salary portion (%) is more than the % still due on this salary',
      v_salary_portion, (v_sal.net - v_sal.paid_amount);
  end if;

  update public.salary_payments
     set paid_amount = paid_amount + v_salary_portion,
         paid_status = case
           when paid_amount + v_salary_portion >= net then 'paid'
           when paid_amount + v_salary_portion <= 0   then 'unpaid'
           else 'partial' end,
         reconciled_txn_id = p_txn_id
   where id = p_salary_id;

  insert into public.employee_loans
    (tenant_id, employee_name, principal, disbursed_on, bank_account_id, kind, notes, created_by)
  values
    (v_tenant, trim(coalesce(p_employee_name, 'Employee')), p_advance_amount, v_txn.txn_date, v_txn.bank_account_id,
     'salary_advance', coalesce(nullif(trim(p_notes), ''), 'Salary overpaid — excess booked as recoverable advance'), public.current_user_id());

  update public.bank_transactions
     set matched_to_type = 'split', matched_to_id = null,
         match_confidence = 'manual', matched_at = now(), matched_by = public.current_user_id()
   where id = p_txn_id;
end;
$function$;

-- public.record_attendance_consent
CREATE OR REPLACE FUNCTION public.record_attendance_consent()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_emp uuid;
begin
  select employee_id into v_emp from public.users where id = public.current_user_id();
  if v_emp is null then raise exception 'Pehle apna employee link karo.'; end if;
  update public.employees
    set attendance_consent_at = now(), attendance_consent_source = 'self'
    where id = v_emp;
end $function$;

-- public.record_business_loan
CREATE OR REPLACE FUNCTION public.record_business_loan(p_lender text, p_purpose text, p_principal integer, p_interest_rate numeric, p_tenure_months integer, p_emi_amount integer, p_disbursed_on date, p_deposit_account uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_id     uuid;
begin
  if v_tenant is null then raise exception 'No tenant context'; end if;
  if p_principal is null or p_principal <= 0 then raise exception 'Loan amount must be positive'; end if;
  if trim(coalesce(p_lender, '')) = '' then raise exception 'Lender is required'; end if;
  if p_deposit_account is null then raise exception 'Pick the account the money was received into'; end if;
  perform 1 from public.bank_accounts where id = p_deposit_account and tenant_id = v_tenant;
  if not found then raise exception 'Deposit account not found'; end if;

  insert into public.business_loans
    (tenant_id, lender, purpose, principal, interest_rate, tenure_months, emi_amount, disbursed_on, deposit_account_id, status, created_by)
  values
    (v_tenant, trim(p_lender), nullif(trim(coalesce(p_purpose,'')),''), p_principal,
     p_interest_rate, nullif(greatest(coalesce(p_tenure_months,0),0),0), nullif(greatest(coalesce(p_emi_amount,0),0),0),
     p_disbursed_on, p_deposit_account, 'active', public.current_user_id())
  returning id into v_id;

  insert into public.bank_transactions
    (tenant_id, bank_account_id, txn_date, description, debit, credit, source, matched_to_type, match_confidence)
  values
    (v_tenant, p_deposit_account, p_disbursed_on, 'Loan received: ' || trim(p_lender), 0, p_principal, 'manual', 'manual', 'manual');

  return v_id;
end;
$function$;

-- public.record_contract_amendment
CREATE OR REPLACE FUNCTION public.record_contract_amendment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_changes jsonb := '{}'::jsonb;
  v_kinds   text[] := '{}';
  v_uid     uuid   := public.current_user_id();
begin
  /* Only COMMERCIAL terms. A domain correction or a reminder timestamp is not an
     amendment, and recording every column change would bury the seat history that
     the ledger exists for under cron noise. */
  if new.seats is distinct from old.seats then
    v_changes := v_changes || jsonb_build_object('seats', jsonb_build_object('from', old.seats, 'to', new.seats));
    v_kinds := v_kinds || (case when new.seats > old.seats then 'seats_added' else 'seats_reduced' end)::text;
  end if;

  if new.mrr is distinct from old.mrr then
    v_changes := v_changes || jsonb_build_object('mrr', jsonb_build_object('from', old.mrr, 'to', new.mrr));
    v_kinds := v_kinds || 'price_changed'::text;
  end if;

  if new.plan is distinct from old.plan then
    v_changes := v_changes || jsonb_build_object('plan', jsonb_build_object('from', old.plan, 'to', new.plan));
    v_kinds := v_kinds || 'plan_changed'::text;
  end if;

  if new.renewal_date is distinct from old.renewal_date then
    v_changes := v_changes || jsonb_build_object('renewal_date', jsonb_build_object('from', old.renewal_date, 'to', new.renewal_date));
    v_kinds := v_kinds || 'term_changed'::text;
  end if;

  if new.status is distinct from old.status then
    v_changes := v_changes || jsonb_build_object('status', jsonb_build_object('from', old.status, 'to', new.status));
    v_kinds := v_kinds || 'status_changed'::text;
  end if;

  if new.billing_cycle is distinct from old.billing_cycle then
    v_changes := v_changes || jsonb_build_object('billing_cycle', jsonb_build_object('from', old.billing_cycle, 'to', new.billing_cycle));
    v_kinds := v_kinds || 'billing_cycle_changed'::text;
  end if;

  if v_changes = '{}'::jsonb then
    return new;   -- nothing commercial moved
  end if;

  insert into public.contract_amendments (
    tenant_id, subscription_id, customer_name, kind, changes,
    seats_from, seats_to, mrr_from, mrr_to, changed_by, source
  ) values (
    new.tenant_id, new.id, new.customer_name,
    array_to_string(v_kinds, '+'),
    v_changes,
    case when new.seats is distinct from old.seats then old.seats end,
    case when new.seats is distinct from old.seats then new.seats end,
    case when new.mrr   is distinct from old.mrr   then old.mrr   end,
    case when new.mrr   is distinct from old.mrr   then new.mrr   end,
    v_uid,
    case when v_uid is null then 'system' else 'user' end
  );

  return new;
end;
$function$;

-- public.record_emi_purchase
CREATE OR REPLACE FUNCTION public.record_emi_purchase(p_name text, p_category text, p_total_cost integer, p_down_payment integer, p_emi_count integer, p_emi_amount integer, p_purchased_on date, p_down_account uuid, p_lender text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_id     uuid;
  v_down   integer := greatest(coalesce(p_down_payment, 0), 0);
  v_cat    text := coalesce(nullif(trim(p_category), ''), 'other');
  v_fin    integer;
begin
  if p_total_cost is null or p_total_cost <= 0 then raise exception 'Total cost must be positive'; end if;
  if trim(coalesce(p_name, '')) = '' then raise exception 'Name is required'; end if;
  if v_down > p_total_cost then raise exception 'Down payment cannot exceed total cost'; end if;
  v_fin := p_total_cost - v_down;

  if v_down > 0 then
    if p_down_account is null then raise exception 'Pick the account the down payment came from'; end if;
    perform 1 from public.bank_accounts where id = p_down_account and tenant_id = v_tenant;
    if not found then raise exception 'Down-payment account not found'; end if;
  end if;

  insert into public.emi_purchases
    (tenant_id, name, category, total_cost, down_payment, financed, emi_count, emi_amount, purchased_on, down_account_id, lender, notes, status, created_by)
  values
    (v_tenant, trim(p_name), v_cat, p_total_cost, v_down, v_fin,
     greatest(coalesce(p_emi_count,0),0), greatest(coalesce(p_emi_amount,0),0), p_purchased_on, p_down_account,
     nullif(trim(coalesce(p_lender,'')),''), nullif(trim(coalesce(p_notes,'')),''),
     case when v_fin <= 0 then 'closed' else 'active' end, public.current_user_id())
  returning id into v_id;

  if v_down > 0 then
    insert into public.bank_transactions
      (tenant_id, bank_account_id, txn_date, description, debit, credit, source, matched_to_type, match_confidence)
    values
      (v_tenant, p_down_account, p_purchased_on, 'Purchase: ' || trim(p_name) || ' (down payment)', v_down, 0, 'manual', 'manual', 'manual');
  end if;

  return v_id;
end;
$function$;

-- public.record_payment
CREATE OR REPLACE FUNCTION public.record_payment(p_quote_id text, p_amount integer, p_method text, p_reference text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_quote                 record;
  v_tenant_id             uuid;
  v_caller_tenant         uuid;
  v_is_service_role       boolean;
  v_has_existing_invoice  boolean;
  v_receipt_voucher_no    text := null;
  v_payment_id            uuid;
  v_prior_received        integer;
  v_total_received        integer;
  v_expected              integer;
  v_outstanding           integer;
  v_overpaid_credit       integer := 0;
  v_is_first_payment      boolean;
  v_is_fully_paid         boolean;
  v_new_payment_status    public.payment_status;
  v_customer_id           uuid;
  v_converted_now         boolean := false;
  v_lead                  record;
  v_domain                text;
  v_subscription_created  boolean := false;
  v_new_sub_id            uuid;
  v_first_line            jsonb;
  v_commitment            text;
  v_is_annual             boolean;
  v_is_monthly            boolean;
  v_plan_name             text;
  v_plan_lower            text;
  v_vendor                public.vendor;
  v_seats                 integer;
  v_is_renewal_quote      boolean := false;
  v_renewal_sub           record;
  v_renewal_rolled_forward boolean := false;
  v_extension_months      integer;
  v_new_mrr               integer;
  v_invoice               record;
  v_already_adjusted      integer;
  v_post_invoice_received integer;
  v_net_due               integer;
  v_invoice_paid          boolean := false;
  v_po_id                 text := null;
  v_po_created            boolean := false;
  v_unit_wholesale_pm     integer;
  v_total_wholesale       integer;
  v_po_seats              integer;
  v_po_months             integer;
  v_po_plan               text;
  v_po_vendor             public.vendor;
  v_po_sub_id             uuid;
  v_was_trial             boolean := false;
  v_existing_payment      record;
  v_is_add_seats          boolean := false;
  v_has_bulk              boolean := false;
  v_bulk_total_seats      integer;
  v_bulk_pool             integer;
  v_running_mrr           integer;
  v_dom_mrr               integer;
  v_dom_seats             integer;
  v_dom                   text;
  v_idx                   integer;
  v_n                     integer;
  v_d                     jsonb;
  v_bulk_count            integer := 0;
  v_start                 date;
  -- 0172: multi-line-item support
  v_line_idx              integer;
  v_line_amount           integer;
  v_first_sub_in_quote    boolean := true;
  -- Only domain/Workspace-type products are meaningfully tied to a single
  -- domain; a quote mixing e.g. a support plan + a hosting plan has no
  -- per-line domain of its own, so both would otherwise fall back to the
  -- SAME customer domain and collide against
  -- subscriptions_tenant_quote_domain_unique (tenant_id, quote_id,
  -- lower(domain)). Track domains already used THIS call and null out any
  -- repeat instead of erroring or silently dropping the subscription.
  v_used_domains          text[] := array[]::text[];
  v_sub_domain            text;
begin
  v_is_service_role := public.current_request_role() = 'service_role';
  if not v_is_service_role then
    v_caller_tenant := public.current_tenant_id();
    if v_caller_tenant is null then
      raise exception 'No tenant context';
    end if;
  end if;

  if p_amount is null or p_amount <= 0 then raise exception 'amount must be > 0'; end if;
  if p_method is null or p_method not in ('upi','razorpay','bank_transfer','cheque','cash','other')
    then raise exception 'invalid payment method: %', p_method; end if;
  if p_reference is null or length(trim(p_reference)) = 0 then raise exception 'reference required'; end if;

  select q.id, q.tenant_id, q.customer_id, q.customer_name, q.lead_id,
         q.amount, q.line_items, q.invoice_id, q.payment_status,
         q.domain, q.extension_months, q.is_add_seats, q.subtotal, q.is_one_off,
         q.prospect_state_code, q.prospect_state, q.prospect_country
    into v_quote
    from public.quotes q
   where q.id = p_quote_id for update;
  if not found then raise exception 'quote % not found', p_quote_id; end if;
  if not v_is_service_role and v_quote.tenant_id <> v_caller_tenant then
    raise exception 'quote % does not belong to your tenant', p_quote_id;
  end if;

  select p.id, p.receipt_voucher_no, p.customer_id
    into v_existing_payment
    from public.payments p
   where p.tenant_id = v_quote.tenant_id
     and p.quote_id  = p_quote_id
     and p.reference = p_reference
     and p.status    = 'received'
   limit 1;
  if found then
    select coalesce(sum(amount), 0) into v_total_received
      from public.payments where quote_id = p_quote_id and status = 'received';
    v_expected    := coalesce(v_quote.amount, 0);
    v_outstanding := greatest(0, v_expected - v_total_received);
    return jsonb_build_object(
      'payment_id', v_existing_payment.id,
      'receipt_voucher_no', v_existing_payment.receipt_voucher_no,
      'customer_id', v_existing_payment.customer_id,
      'total_received', v_total_received,
      'expected', v_expected,
      'outstanding', v_outstanding,
      'is_first_payment', false,
      'is_fully_paid', v_total_received >= v_expected,
      'idempotent_replay', true,
      'already_recorded', true
    );
  end if;

  v_tenant_id            := v_quote.tenant_id;
  v_has_existing_invoice := v_quote.invoice_id is not null;
  v_expected             := coalesce(v_quote.amount, 0);
  v_domain               := v_quote.domain;
  /* Default to the TERM of the subscription being renewed, not a hard 12. A monthly
     subscription renewed with a plain renewal quote was being pushed a YEAR forward, so
     it would never be chased again and its MRR would keep counting for twelve months of
     service nobody had sold. Falls back to 12 when there is no subscription in hand
     (a new sale), which is where the old constant was right. */
  /* Left deliberately NULL when the quote does not say. The term of the subscription
     being renewed is not known yet — v_renewal_sub is selected below — and reading an
     unassigned RECORD raises 55000 for every payment, renewal or not. Resolved right
     after that select. */
  v_extension_months     := v_quote.extension_months;
  v_is_add_seats         := coalesce(v_quote.is_add_seats, false);
  v_has_bulk := exists (
    select 1
      from jsonb_array_elements(case when jsonb_typeof(v_quote.line_items) = 'array' then v_quote.line_items else '[]'::jsonb end) li
     where coalesce((li->>'bulk')::boolean, false)
  );

  select s.id, s.renewal_date, s.seats, s.mrr, s.plan, s.renewal_state, s.vendor, s.customer_id, s.customer_name, s.domain as sub_domain, s.term_months
    into v_renewal_sub
    from public.subscriptions s
   where s.tenant_id = v_tenant_id
     and s.renewal_quote_id = p_quote_id
   for update limit 1;
  v_is_renewal_quote := found;

  /* Now the term IS known. Default to the term of the subscription being renewed rather
     than a hard 12: renewing a MONTHLY subscription used to push its renewal date twelve
     months out, so it was never chased again and its MRR counted for a year of service
     nobody had sold. Falls back to 12 for a new sale, where no subscription exists and the
     old constant was right. */
  if v_extension_months is null then
    v_extension_months := coalesce(case when v_is_renewal_quote then v_renewal_sub.term_months end, 12);
  end if;

  select coalesce(sum(amount), 0) into v_prior_received
    from public.payments where quote_id = p_quote_id and status = 'received';
  v_is_first_payment := (v_prior_received = 0);

  /* #27 (migrations 0060/0061), lost from this function and re-added 22 Aug 2026.
     A quote with no amount has nothing to pay. Without this, paying ₹5,000 against a
     ₹0 quote recorded the payment, marked the quote received, and created an mrr=0
     subscription — a live customer with a subscription worth nothing, which then
     enters the renewal cadence and is invoiced for ₹0.

     Placed AFTER the idempotency replay above, deliberately: a quote that WAS priced,
     was paid, and was later edited to 0 must still replay idempotently rather than
     start throwing at a webhook that already succeeded. Only a NEW payment is refused. */
  if coalesce(v_quote.amount, 0) <= 0 then
    raise exception 'Quote % has no amount, so a payment cannot be recorded against it. Set the quote total first, then record the payment.', p_quote_id;
  end if;

  v_customer_id := v_quote.customer_id;
  if v_is_first_payment and v_quote.lead_id is not null and v_quote.customer_id is null then
    select l.contact_name, l.contact_email, l.contact_phone, l.company, l.notes, l.domain, l.stage,
           l.state_code, l.state, l.gstin
      into v_lead from public.leads l
     where l.id = v_quote.lead_id and l.tenant_id = v_tenant_id;
    if not found then raise exception 'lead % not found', v_quote.lead_id; end if;
    if v_domain is null then v_domain := v_lead.domain; end if;
    v_was_trial := (v_lead.stage = 'trial');

    /* Dedup (migrations 0064/0065), lost from this function and re-added 22 Aug 2026.
       The lead is a fresh row but the company may already be a customer — the same
       business enquiring a second time, or a renewal that came in as a new lead. This
       used to insert unconditionally, so that company got a SECOND customer row, and
       then a second subscription and a second invoice series against the same buyer.

       Matched on contact_email, case-insensitively and tenant-scoped. Email only:
       company NAME is not an identity ("Excel Tech" vs "Excel Technologies Pvt Ltd")
       and matching on it would merge two genuinely different customers, which is the
       worse error of the two — a wrongly-merged customer is far harder to unpick than
       a duplicate. No email on the lead means no match, and a new customer is created. */
    /* R-137 (3 Oct 2026): email alone merged different businesses that shared one
       inbox — every test quote on the owner's own address landed on one customer
       ("Sri Ganga Technologies": 64 quotes, Rs 3.9L of payments). Now: same GSTIN, or
       same email AND a matching name (match_existing_customer). The rule above still
       holds — when unsure, a duplicate is the lesser error. */
    v_customer_id := public.match_existing_customer(v_tenant_id, v_lead.contact_email, v_lead.gstin, v_lead.company);

    if v_customer_id is null then
      insert into public.customers (tenant_id, name, contact_name, contact_email, contact_phone, domain, since, health, notes, state_code, state, gstin)
      values (v_tenant_id, v_lead.company, v_lead.contact_name, v_lead.contact_email, v_lead.contact_phone, v_domain, current_date,
              case when p_amount >= v_expected then 85 else 75 end, v_lead.notes, v_lead.state_code, v_lead.state, v_lead.gstin)
      returning id into v_customer_id;
    else
      /* Reused. The quote must point at the customer that actually exists, or the
         invoice and the subscription below hang off a different row than the payment. */
      update public.quotes set customer_id = v_customer_id
       where id = p_quote_id and tenant_id = v_tenant_id;
    end if;

    update public.leads
       set stage              = 'won',
           trial_converted_at = case when v_was_trial then now() else trial_converted_at end
     where id = v_quote.lead_id and tenant_id = v_tenant_id;
    v_converted_now := true;
  elsif v_is_first_payment and v_quote.customer_id is null and v_quote.lead_id is null then
    insert into public.customers (tenant_id, name, domain, since, health, state_code, state, country)
    values (v_tenant_id, coalesce(nullif(trim(v_quote.customer_name), ''), 'Customer'),
            v_domain, current_date, case when p_amount >= v_expected then 85 else 75 end,
            v_quote.prospect_state_code, v_quote.prospect_state,
            coalesce(nullif(trim(v_quote.prospect_country), ''), 'India'))
    returning id into v_customer_id;
    v_converted_now := true;
  elsif v_quote.lead_id is not null then
    select l.stage into v_lead from public.leads l where l.id = v_quote.lead_id and l.tenant_id = v_tenant_id;
    if v_is_first_payment then
      update public.leads
         set trial_converted_at = case when stage = 'won' and trial_started_at is not null and trial_converted_at is null then now() else trial_converted_at end
       where id = v_quote.lead_id and tenant_id = v_tenant_id;
    end if;
  end if;

  if not v_has_existing_invoice then
    v_receipt_voucher_no := public.next_document_number('receipt_voucher', v_tenant_id, public.ist_today());
  end if;

  begin
    insert into public.payments (tenant_id, quote_id, customer_id, amount, method, reference, notes,
      status, received_at, receipt_voucher_no, recorded_by)
    values (v_tenant_id, p_quote_id, v_customer_id, p_amount, p_method, p_reference,
            nullif(trim(coalesce(p_notes, '')), ''), 'received', now(), v_receipt_voucher_no, public.current_user_id())
    returning id into v_payment_id;
  exception when unique_violation then
    select p.id, p.receipt_voucher_no, p.customer_id into v_existing_payment
      from public.payments p
     where p.tenant_id = v_tenant_id and p.quote_id = p_quote_id
       and p.reference = p_reference and p.status = 'received' limit 1;
    select coalesce(sum(amount), 0) into v_total_received
      from public.payments where quote_id = p_quote_id and status = 'received';
    v_outstanding := greatest(0, v_expected - v_total_received);
    return jsonb_build_object(
      'payment_id', v_existing_payment.id,
      'receipt_voucher_no', v_existing_payment.receipt_voucher_no,
      'customer_id', v_existing_payment.customer_id,
      'total_received', v_total_received,
      'expected', v_expected,
      'outstanding', v_outstanding,
      'is_first_payment', false,
      'is_fully_paid', v_total_received >= v_expected,
      'idempotent_replay', true,
      'already_recorded', true
    );
  end;

  v_total_received := v_prior_received + p_amount;
  v_outstanding    := greatest(0, v_expected - v_total_received);
  v_is_fully_paid  := v_total_received >= v_expected;
  v_new_payment_status := case
    when v_has_existing_invoice then 'invoiced'
    when v_is_fully_paid        then 'received'
    else                             'partial' end::public.payment_status;

  /* 0157: a ONE-OFF sale creates no subscription. Lost from this function and re-added
     22 Aug 2026 — and this is the costliest of the three, because it does not just
     record something wrong, it goes on to CHARGE for it. A direct invoice (is_one_off)
     is a single sale; the guard's absence gave it a recurring subscription, which the
     renewal cron then bills again on its next cycle. The customer is invoiced for a
     subscription nobody sold them. */
  if v_is_first_payment and not v_is_renewal_quote and not v_is_add_seats
     and not coalesce(v_quote.is_one_off, false) then
    if jsonb_typeof(v_quote.line_items) = 'array' and jsonb_array_length(v_quote.line_items) > 0 then
      for v_line_idx in 0 .. jsonb_array_length(v_quote.line_items) - 1 loop
        v_first_line := v_quote.line_items -> v_line_idx;
        v_commitment := v_first_line->>'commitment';
        v_plan_name  := coalesce(v_first_line->>'name',
                          case when v_commitment = 'monthly' then 'Monthly subscription'
                               else 'Annual subscription' end);
        v_is_annual  := v_commitment is distinct from 'monthly' and v_commitment is not null;
        v_is_monthly := v_commitment = 'monthly';
        v_po_sub_id  := null;

        if (v_is_annual or v_is_monthly) and v_customer_id is not null then
          -- 0172: exact vendor via the catalog item itself; name-guess only
          -- for lines with no item_id (hand-typed, no catalog link).
          v_vendor := null;
          if v_first_line->>'item_id' is not null then
            select i.vendor into v_vendor from public.items i
             where i.id = v_first_line->>'item_id' and i.tenant_id = v_tenant_id;
          end if;
          if v_vendor is null then
            v_plan_lower := lower(v_plan_name);
            v_vendor := case
              when v_plan_lower like '%google%'    then 'google'::public.vendor
              when v_plan_lower like '%m365%'      then 'microsoft'::public.vendor
              when v_plan_lower like '%microsoft%' then 'microsoft'::public.vendor
              when v_plan_lower like '%365%'       then 'microsoft'::public.vendor
              when v_plan_lower like '%zoho%'      then 'zoho'::public.vendor
              else 'other'::public.vendor end;
          end if;

          v_start := coalesce(nullif(v_first_line->>'start_date', '')::date, current_date);
          v_line_amount := round(
            coalesce((v_first_line->>'qty')::numeric, 0) * coalesce((v_first_line->>'rate')::numeric, 0)
              * (1 - coalesce((v_first_line->>'discount_pct')::numeric, 0) / 100)
          )::int;

          if coalesce((v_first_line->>'bulk')::boolean, false)
             and jsonb_typeof(v_first_line->'domains') = 'array'
             and jsonb_array_length(v_first_line->'domains') > 0 then
            select coalesce(sum((e->>'seats')::int), 0) into v_bulk_total_seats
              from jsonb_array_elements(v_first_line->'domains') e;
            if v_bulk_total_seats <= 0 then
              raise exception 'bulk line has zero total seats (quote %)', p_quote_id;
            end if;
            v_bulk_pool := greatest(0, round(
                             coalesce(v_line_amount, v_expected) / case when v_is_monthly then 1.0 else 12.0 end
                           ))::int;
            v_running_mrr := 0;
            v_idx := 0;
            v_n := jsonb_array_length(v_first_line->'domains');
            for v_d in select e from jsonb_array_elements(v_first_line->'domains') e loop
              v_idx := v_idx + 1;
              v_dom := lower(trim(v_d->>'domain'));
              v_dom_seats := coalesce((v_d->>'seats')::int, 0);
              if v_dom = '' then continue; end if;
              if v_idx < v_n then
                v_dom_mrr := floor(v_bulk_pool::numeric * v_dom_seats / v_bulk_total_seats)::int;
              else
                v_dom_mrr := v_bulk_pool - v_running_mrr;
              end if;
              v_running_mrr := v_running_mrr + v_dom_mrr;

              insert into public.subscriptions (tenant_id, customer_id, customer_name, plan, vendor, seats, mrr,
                start_date, renewal_date, status, outstanding_amount, domain, quote_id,
                term_months)
              values (v_tenant_id, v_customer_id, v_quote.customer_name, v_plan_name, v_vendor, v_dom_seats, v_dom_mrr,
                v_start,
                (v_start + case when v_is_monthly then interval '1 month' else interval '1 year' end)::date,
                'active', 0, v_dom, p_quote_id,
                case when v_is_monthly then 1 else 12 end)
              on conflict (tenant_id, quote_id, lower(domain)) where quote_id is not null and domain is not null
                do nothing
              returning id into v_new_sub_id;

              insert into public.customer_domains (tenant_id, customer_id, domain)
              values (v_tenant_id, v_customer_id, v_dom)
              on conflict (tenant_id, lower(domain)) do nothing;

              v_bulk_count := v_bulk_count + 1;
              v_used_domains := array_append(v_used_domains, v_dom);
            end loop;
            v_subscription_created := true;
            v_first_sub_in_quote := false;
            v_po_seats := v_bulk_total_seats; v_po_months := 12; v_po_plan := v_plan_name;
            v_po_vendor := v_vendor; v_po_sub_id := v_new_sub_id;
          else
            v_seats := coalesce((v_first_line->>'qty')::int, 0);
            -- 0172: prefer THIS line's own domain (the quote builder now lets
            -- staff type a distinct domain per product line) over the
            -- whole-quote/customer fallback below, which was the only source
            -- before per-line domains existed.
            v_sub_domain := nullif(lower(trim(v_first_line->>'domain')), '');
            if v_sub_domain is null then
              if v_domain is null and v_customer_id is not null then
                select domain into v_domain from public.customers where id = v_customer_id;
              end if;
              v_sub_domain := v_domain;
            end if;
            if v_sub_domain is not null and lower(v_sub_domain) = any(v_used_domains) then
              v_sub_domain := null;
            end if;
            insert into public.subscriptions (tenant_id, customer_id, customer_name, plan, vendor, seats, mrr,
              start_date, renewal_date, status, outstanding_amount, domain, quote_id,
              term_months)
            values (v_tenant_id, v_customer_id, v_quote.customer_name, v_plan_name, v_vendor, v_seats,
              greatest(0, round(v_line_amount / case when v_is_monthly then 1.0 else 12.0 end))::int, v_start,
              (v_start + case when v_is_monthly then interval '1 month' else interval '1 year' end)::date, 'active',
              case when v_first_sub_in_quote then v_outstanding else 0 end,
              v_sub_domain, p_quote_id,
              case when v_is_monthly then 1 else 12 end)
            returning id into v_new_sub_id;
            if v_sub_domain is not null then
              v_used_domains := array_append(v_used_domains, lower(v_sub_domain));
            end if;
            v_subscription_created := true;
            v_first_sub_in_quote := false;
            v_po_seats := v_seats; v_po_months := 12; v_po_plan := v_plan_name;
            v_po_vendor := v_vendor; v_po_sub_id := v_new_sub_id;
          end if;

          if v_po_sub_id is not null then
            select coalesce(nullif((prices->'annual'->>'wholesale')::int, 0), nullif(wholesale, 0))
              into v_unit_wholesale_pm from public.items
             where tenant_id = v_tenant_id and lower(name) = lower(v_po_plan) limit 1;
            if v_unit_wholesale_pm is null or v_unit_wholesale_pm <= 0 then
              v_unit_wholesale_pm := greatest(0, round(coalesce(v_line_amount, v_expected)::numeric * 0.83 / greatest(v_po_seats * v_po_months, 1)))::int;
            end if;
            v_total_wholesale := v_unit_wholesale_pm * v_po_seats * v_po_months;
            v_po_id := public.next_document_number('purchase_order', v_tenant_id);
            insert into public.purchase_orders (
              id, tenant_id, subscription_id, customer_id, customer_name, domain,
              vendor, plan, seats, term_months, unit_cost_pm, total_cost, status, notes, created_by
            ) values (
              v_po_id, v_tenant_id, v_po_sub_id, v_customer_id, v_quote.customer_name, v_domain,
              v_po_vendor, v_po_plan, v_po_seats, v_po_months, v_unit_wholesale_pm, v_total_wholesale, 'draft',
              'Auto-created from quote ' || p_quote_id ||
              case when coalesce((v_first_line->>'bulk')::boolean, false) then ' (bulk order - ' || v_bulk_count || ' domains)'
                   else ' (new sub)' end,
              public.current_user_id()
            );
            v_po_created := true;
          end if;
        end if;
      end loop;
    end if;
    v_po_sub_id := null;
  elsif v_customer_id is not null and not v_is_renewal_quote and not v_is_add_seats and not v_has_bulk then
    update public.subscriptions set outstanding_amount = v_outstanding
     where tenant_id = v_tenant_id and customer_id = v_customer_id and quote_id = p_quote_id and outstanding_amount > 0;
  end if;

  if v_is_renewal_quote and v_is_fully_paid then
    v_first_line := case
      when jsonb_typeof(v_quote.line_items) = 'array' and jsonb_array_length(v_quote.line_items) > 0
        then v_quote.line_items->0 else null end;
    if v_first_line is not null then
      v_plan_name := coalesce(v_first_line->>'name', v_renewal_sub.plan);
      v_seats     := coalesce((v_first_line->>'qty')::int, v_renewal_sub.seats);
    else
      v_plan_name := v_renewal_sub.plan; v_seats := v_renewal_sub.seats;
    end if;
    v_new_mrr := greatest(0, round(coalesce(v_quote.subtotal, v_expected)::numeric / greatest(v_extension_months, 1)))::int;
    update public.subscriptions
       /* A full TERM, not a fixed twelve months. On a monthly subscription one month IS
          the whole term, and the old test left renewal_state stuck at whatever step the
          cadence had reached — so the ladder never re-armed and the next month went
          unchased. */
       set renewal_state = case when v_extension_months >= coalesce(v_renewal_sub.term_months, 12)
                                then 'renewed' else renewal_state end,
           renewal_date  = (v_renewal_sub.renewal_date + (v_extension_months || ' months')::interval)::date,
           seats = v_seats, plan = v_plan_name,
           mrr   = case when v_new_mrr > 0 then v_new_mrr else mrr end,
           outstanding_amount = 0, renewal_quote_id = null,
           reminder_count = 0, last_reminder_sent_at_v2 = null, status = 'active'
     where id = v_renewal_sub.id and tenant_id = v_tenant_id;
    v_renewal_rolled_forward := true;
    v_po_seats := v_seats; v_po_months := v_extension_months;
    v_po_plan := v_plan_name; v_po_vendor := v_renewal_sub.vendor; v_po_sub_id := v_renewal_sub.id;
  end if;

  if v_po_sub_id is not null then
    select coalesce(nullif((prices->'annual'->>'wholesale')::int, 0), nullif(wholesale, 0))
      into v_unit_wholesale_pm from public.items
     where tenant_id = v_tenant_id and lower(name) = lower(v_po_plan) limit 1;
    if v_unit_wholesale_pm is null or v_unit_wholesale_pm <= 0 then
      v_unit_wholesale_pm := greatest(0, round(v_expected::numeric * 0.83 / greatest(v_po_seats * v_po_months, 1)))::int;
    end if;
    v_total_wholesale := v_unit_wholesale_pm * v_po_seats * v_po_months;
    v_po_id := public.next_document_number('purchase_order', v_tenant_id);
    insert into public.purchase_orders (
      id, tenant_id, subscription_id, customer_id, customer_name, domain,
      vendor, plan, seats, term_months, unit_cost_pm, total_cost, status, notes, created_by
    ) values (
      v_po_id, v_tenant_id, v_po_sub_id, v_customer_id, v_quote.customer_name, v_domain,
      v_po_vendor, v_po_plan, v_po_seats, v_po_months, v_unit_wholesale_pm, v_total_wholesale, 'draft',
      'Auto-created from quote ' || p_quote_id ||
      case when v_is_renewal_quote then ' (renewal/extension)'
           when v_bulk_count > 0    then ' (bulk order - ' || v_bulk_count || ' domains)'
           else ' (new sub)' end,
      public.current_user_id()
    );
    v_po_created := true;
  end if;

  update public.quotes
     set payment_status = v_new_payment_status,
         payment_amount = v_total_received,
         payment_method = p_method,
         payment_reference = p_reference,
         payment_received_at = now(),
         payment_notes = nullif(trim(coalesce(p_notes, '')), ''),
         customer_id = v_customer_id,
         status = case
           when status in ('draft', 'sent', 'viewed') then 'accepted'::public.quote_status
           else status
         end
   where id = p_quote_id and tenant_id = v_tenant_id;

  if v_has_existing_invoice then
    select i.amount, i.net_payable, i.status, i.adjusted_advances into v_invoice
      from public.invoices i where i.id = v_quote.invoice_id and i.tenant_id = v_tenant_id;
    if found and v_invoice.status <> 'paid' then
      v_already_adjusted := coalesce((select sum((adv->>'amount')::int) from jsonb_array_elements(v_invoice.adjusted_advances) adv), 0);
      v_post_invoice_received := v_total_received - v_already_adjusted;
      v_net_due := coalesce(v_invoice.net_payable, v_invoice.amount);
      /* R-015 (Pardeep, 29 Sep 2026). This wrote NOTHING unless the invoice was settled
         in full, so `invoices.paid_amount` stayed 0 on every part-paid invoice — and
         Aging and the Balance Sheet both count the whole `net_payable`. A Rs 1,00,000
         invoice with Rs 40,000 received showed Rs 1,00,000 outstanding while the same
         Rs 40,000 was also counted as cash: wrong on both sides of the books at once.
         (Only `sync_project_invoice_paid`, on the project side, ever filled the column,
         which is why it looks populated to anybody who checks a project invoice.)

         paid_amount is written on EVERY payment now. `greatest(0, ...)` because
         v_post_invoice_received is net of advances already adjusted onto the invoice and
         can legitimately go negative; a negative paid_amount would flatter the aging
         rather than merely be wrong.

         status and paid_date still move only on full settlement. invoice_status has no
         'partial' value, and adding one reaches every screen that switches on status —
         that is a change to ask for, not to take. Aging reads net_payable - paid_amount,
         which needs no new status.

         paid_date uses ist_today(): current_date is the UTC day on this server (R-015
         part 1), so an invoice settled at 01:00 IST was stamped yesterday. It is still
         the SETTLEMENT day and not the payment's own received date — record_payment has
         no received-date parameter to read, so the dialog patches that in afterwards. */
      update public.invoices
         set paid_amount = greatest(0, v_post_invoice_received),
             status      = case when v_post_invoice_received >= v_net_due
                                then 'paid'::invoice_status else status end,
             paid_date   = case when v_post_invoice_received >= v_net_due
                                then public.ist_today() else paid_date end
       where id = v_quote.invoice_id and tenant_id = v_tenant_id;
      v_invoice_paid := v_post_invoice_received >= v_net_due;
    end if;
  end if;

  /* ─── Overpayment → customer credit, ISI transaction me (audit A5, 1 Sep 2026) ───
     Outstanding upar 0 par floor hota hai, to expected se zyada aaya paisa yahan
     record na ho to KAHIN record nahi hota. Ye insert pehle client-side tha
     (record-payment-dialog.tsx), RPC ke commit ke BAAD — network/RLS ki ek hichki
     aur customer ka extra rupaya hamesha ke liye be-hisaab. Incremental hi jodta
     hai (is payment ne jitna naya excess banaya), taki kai kishton me double na gine —
     wahi ganit jo client me tha. */
  v_overpaid_credit := greatest(0, v_total_received - v_expected)
                     - greatest(0, v_prior_received - v_expected);
  if v_overpaid_credit > 0 and v_customer_id is not null then
    insert into public.customer_credits
      (tenant_id, customer_id, amount, source, source_payment_id, source_quote_id, note, status)
    values
      (v_tenant_id, v_customer_id, v_overpaid_credit, 'overpayment', v_payment_id, p_quote_id,
       'Excess over quote ' || p_quote_id, 'open');
  end if;

  return jsonb_build_object(
    'payment_id', v_payment_id,
    'receipt_voucher_no', v_receipt_voucher_no,
    'customer_id', v_customer_id,
    'total_received', v_total_received,
    'expected', v_expected,
    'outstanding', v_outstanding,
    'is_first_payment', v_is_first_payment,
    'is_fully_paid', v_is_fully_paid,
    'converted_now', v_converted_now,
    'subscription_created', v_subscription_created,
    'bulk_domains_created', v_bulk_count,
    'invoice_paid', v_invoice_paid,
    'has_existing_invoice', v_has_existing_invoice,
    'is_renewal_quote', v_is_renewal_quote,
    'renewal_rolled_forward', v_renewal_rolled_forward,
    'extension_months', v_extension_months,
    'domain', v_domain,
    'po_id', v_po_id,
    'po_created', v_po_created,
    'was_trial', v_was_trial,
    'is_add_seats', v_is_add_seats,
    'overpaid_credit', v_overpaid_credit,
    'idempotent_replay', false
  );
end;
$function$;

-- public.record_project_payment
CREATE OR REPLACE FUNCTION public.record_project_payment(p_milestone_id uuid, p_amount integer, p_method text, p_reference text, p_received_at date, p_bank_txn_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant   uuid := public.current_tenant_id();
  v_ms       record;
  v_pay_id   uuid;
  v_paid     integer;
begin
  select * into v_ms from public.project_milestones where id = p_milestone_id for update;
  if not found then raise exception 'Milestone not found'; end if;
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated')) or (v_tenant is not null and v_ms.tenant_id is distinct from v_tenant) then
    raise exception 'Milestone not in caller''s tenant' using errcode = 'insufficient_privilege';
  end if;
  if coalesce(p_amount, 0) <= 0 then raise exception 'Amount must be > 0'; end if;

  insert into public.project_payments
    (tenant_id, project_id, milestone_id, amount, method, reference, received_at, bank_txn_id)
  values
    (v_ms.tenant_id, v_ms.project_id, p_milestone_id, p_amount,
     nullif(trim(coalesce(p_method,'')),''), nullif(trim(coalesce(p_reference,'')),''),
     coalesce(p_received_at, current_date), p_bank_txn_id)
  returning id into v_pay_id;

  select coalesce(sum(amount), 0) into v_paid
    from public.project_payments where milestone_id = p_milestone_id;
  if v_paid >= v_ms.total_amount then
    update public.project_milestones set status = 'paid' where id = p_milestone_id;
    if v_ms.invoice_id is not null then
      update public.invoices set status = 'paid'::invoice_status, paid_date = coalesce(p_received_at, current_date)
       where id = v_ms.invoice_id;
    end if;
  end if;

  if p_bank_txn_id is not null then
    update public.bank_transactions
       set matched_to_type = 'project', matched_to_id = v_pay_id::text,
           matched_at = now(), match_confidence = 'manual'
     where id = p_bank_txn_id and tenant_id = v_ms.tenant_id;
  end if;

  return v_pay_id;
end;
$function$;

-- public.refund_payment
CREATE OR REPLACE FUNCTION public.refund_payment(p_payment_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant     uuid := public.current_tenant_id();
  v_pay        record;
  v_quote      record;
  v_remaining  integer;
  v_expected   integer;
  v_new_status public.payment_status;
  v_rfv        text;
  v_bank_cnt   integer;
  v_credits    integer := 0;
begin
  if p_reason is null or length(trim(p_reason)) < 5 then
    raise exception 'Refund ki wajah likhiye (kam se kam 5 akshar) — ye voucher par darj hoti hai.'
      using errcode = 'invalid_parameter_value';
  end if;

  select * into v_pay from public.payments where id = p_payment_id;
  if not found then raise exception 'Payment not found'; end if;
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated')) or (v_tenant is not null and v_pay.tenant_id is distinct from v_tenant) then
    raise exception 'Payment not in your tenant' using errcode = 'insufficient_privilege';
  end if;

  /* ── R-042 (Pardeep, 30 Sep 2026): tenant was the only question being asked ──────
     Being in the right workspace is not authority to send money back. A sales or support
     login could refund any payment in the workspace — and a refund is not reversible
     bookkeeping: it consumes a Refund Voucher number from the gapless CGST 31(3)(e)
     series, recomputes the quote and the subscription, and closes customer credit.

     owner / manager / accountant, the same three S41 uses for money writes, through the
     same helper — so "who may touch money" has one definition instead of a role list
     copied into each guard.

     A session with NO JWT (psql, a migration, the SQL tests) is deliberately left alone,
     exactly as the tenant check above leaves it alone: it is not a PostgREST caller. */
  if coalesce(public.current_request_role(), '') in ('anon', 'authenticated')
     and not public.current_user_has_role('owner', 'manager', 'accountant') then
    raise exception
      'Refunds are for an owner, manager or accountant. A refund takes a numbered Refund Voucher from your GST series and reopens the balance on that customer, so it is not a staff-level action. Ask one of them to record it (Payments → the payment → Refund).'
      using errcode = 'insufficient_privilege';
  end if;
  if v_pay.status = 'refunded' then
    raise exception 'Ye payment pehle hi refund ho chuki hai (voucher %).', coalesce(v_pay.refund_voucher_no, '—')
      using errcode = 'invalid_parameter_value';
  end if;

  select id, tenant_id, amount, invoice_id, is_add_seats, customer_id, customer_name
    into v_quote from public.quotes where id = v_pay.quote_id;

  if v_quote.invoice_id is not null then
    raise exception 'Is quote par GST invoice jaari hai — pehle us invoice ka CREDIT NOTE banaiye (invoice ke page se), phir refund book kariye. Tax-invoice ke against seedha refund GSTR ka milaan tod deta hai.'
      using errcode = 'invalid_parameter_value';
  end if;

  select count(*) into v_bank_cnt from public.bank_transactions
   where tenant_id = v_pay.tenant_id and matched_to_type = 'payment' and matched_to_id = v_pay.id::text;
  if v_bank_cnt > 0 then
    raise exception 'This payment is reconciled to a bank transaction — un-reconcile that bank line first, then refund.'
      using errcode = 'invalid_parameter_value';
  end if;

  if coalesce(v_quote.is_add_seats, false) then
    if exists (
      select 1 from public.subscriptions s
       where s.tenant_id = v_pay.tenant_id
         and ( (v_quote.customer_id is not null and s.customer_id = v_quote.customer_id)
            or (v_quote.customer_id is null and s.customer_name = v_quote.customer_name) )
    ) then
      raise exception 'Ye add-seats ki payment hai — pehle subscription par seats ghataiye, phir refund; warna seats mile hue aur paisa wapas dono ho jate.'
        using errcode = 'invalid_parameter_value';
    end if;
  end if;

  v_rfv := public.next_document_number('refund_voucher', v_pay.tenant_id);

  update public.payments
     set status = 'refunded',
         refunded_at = now(),
         refund_reason = trim(p_reason),
         refund_voucher_no = v_rfv
   where id = p_payment_id;

  /* Isi payment ki tairti overpayment-credit band — paisa wapas ja raha hai,
     credit ke roop me dobara kharch nahi ho sakta. */
  update public.customer_credits
     set status = 'refunded'
   where source_payment_id = p_payment_id and status = 'open';
  get diagnostics v_credits = row_count;

  select coalesce(sum(amount), 0) into v_remaining
    from public.payments where quote_id = v_pay.quote_id and status = 'received';
  v_expected := coalesce(v_quote.amount, 0);
  v_new_status := case
    when v_remaining <= 0          then 'none'
    when v_remaining >= v_expected then 'received'
    else                                'partial' end::public.payment_status;

  update public.quotes
     set payment_status = v_new_status,
         payment_amount = v_remaining
   where id = v_pay.quote_id;

  update public.subscriptions
     set outstanding_amount = greatest(0, v_expected - v_remaining)
   where tenant_id = v_pay.tenant_id and quote_id = v_pay.quote_id;

  return jsonb_build_object(
    'refund_voucher_no', v_rfv,
    'payment_id', p_payment_id,
    'amount', v_pay.amount,
    'quote_id', v_pay.quote_id,
    'new_payment_status', v_new_status,
    'credits_closed', v_credits,
    'gateway_refunded', false
  );
end $function$;

-- public.reset_tenant_selected_tables
CREATE OR REPLACE FUNCTION public.reset_tenant_selected_tables(p_tables text[], p_label text, p_confirm_statutory boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant   uuid;
  v_role     text;
  v_backup   jsonb;
  v_bad      text[];
  v_stat     text[];
  r          record;
  v_deleted  jsonb := '{}'::jsonb;
  n          bigint;
begin
  select tenant_id, role into v_tenant, v_role from public.users where id = public.current_user_id();
  if v_tenant is null then
    raise exception 'No tenant for caller';
  end if;
  if coalesce(v_role, '') <> 'owner' then
    raise exception 'Only the owner can reset data. Ask the account owner to do this.';
  end if;

  if p_tables is null or cardinality(p_tables) = 0 then
    raise exception 'Nothing selected. Tick at least one section to reset.';
  end if;

  select array_agg(t) into v_bad
  from unnest(p_tables) t
  where t not in (select key from backup._resettable());

  if v_bad is not null then
    raise exception 'Not resettable: %. Allowed: %',
      array_to_string(v_bad, ', '),
      (select string_agg(distinct key, ', ' order by key) from backup._resettable());
  end if;

  select array_agg(distinct key) into v_stat
  from backup._resettable()
  where statutory and key = any(p_tables);

  if v_stat is not null and not p_confirm_statutory then
    raise exception
      'Refusing to reset % — these are statutory records (GST invoice series must have no gaps; attendance backs payroll). Re-run with the statutory confirmation if you are certain.',
      array_to_string(v_stat, ', ');
  end if;

  v_backup := backup._take(v_tenant, 'Pre-Reset Safeguard Snapshot - ' || coalesce(p_label, 'unlabelled'), 'pre_reset');

  if v_backup is null
     or coalesce((v_backup->>'bytes')::bigint, 0) = 0
     or coalesce((v_backup->>'table_count')::int, 0) = 0 then
    raise exception 'Pre-reset backup produced an empty snapshot — refusing to delete anything. Nothing has been changed.';
  end if;

  for r in
    select tbl from backup._resettable() where key = any(p_tables)
  loop
    if to_regclass('public.' || quote_ident(r.tbl)) is null then
      raise exception 'Reset allowlist is stale: table public.% does not exist. Nothing has been changed.', r.tbl;
    end if;
    if not exists (
      select 1 from information_schema.columns
      where table_schema = 'public' and table_name = r.tbl and column_name = 'tenant_id'
    ) then
      raise exception 'Refusing to reset public.% — it has no tenant_id, so the delete could not be scoped to one tenant. Nothing has been changed.', r.tbl;
    end if;

    execute format('delete from public.%I where tenant_id = $1', r.tbl) using v_tenant;
    get diagnostics n = row_count;
    v_deleted := v_deleted || jsonb_build_object(r.tbl, n);
  end loop;

  return jsonb_build_object(
    'backup_id',  v_backup->>'id',
    'backup_bytes', (v_backup->>'bytes')::bigint,
    'deleted',    v_deleted,
    'label',      p_label
  );
end $function$;

-- public.restore_tenant_backup
CREATE OR REPLACE FUNCTION public.restore_tenant_backup(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid; v_role text; v_payload jsonb; r record; col_list text; has_identity bool; n int := 0;
begin
  select tenant_id, role into v_tenant, v_role from public.users where id = public.current_user_id();
  if v_tenant is null then raise exception 'No tenant for caller'; end if;
  if coalesce(v_role, '') <> 'owner' then raise exception 'Only the owner can restore'; end if;
  select payload into v_payload from backup.snapshots where id = p_id and tenant_id = v_tenant;
  if v_payload is null then raise exception 'Restore point not found'; end if;

  perform backup._take(v_tenant, 'Before restore ' || to_char(now(), 'DD Mon HH24:MI'), 'auto');

  set local session_replication_role = replica;

  for r in
    select c.table_name from information_schema.columns c
    join pg_tables pt on pt.schemaname='public' and pt.tablename=c.table_name
    where c.table_schema='public' and c.column_name='tenant_id' and c.table_name not in ('tenant_secrets','users')
    group by c.table_name order by c.table_name
  loop
    if not (v_payload ? r.table_name) then continue; end if;
    select string_agg(quote_ident(column_name), ', ' order by ordinal_position), bool_or(is_identity = 'YES')
      into col_list, has_identity
    from information_schema.columns
    where table_schema='public' and table_name = r.table_name and is_generated <> 'ALWAYS';
    execute format('delete from public.%I where tenant_id = $1', r.table_name) using v_tenant;
    execute format(
      'insert into public.%I (%s) %s select %s from jsonb_populate_recordset(null::public.%I, $1)',
      r.table_name, col_list, case when has_identity then 'overriding system value' else '' end, col_list, r.table_name
    ) using (v_payload -> r.table_name);
    n := n + 1;
  end loop;

  set local session_replication_role = origin;
  return jsonb_build_object('restored_tables', n, 'restored_at', now());
end $function$;

-- public.set_document_series_start
CREATE OR REPLACE FUNCTION public.set_document_series_start(p_doc_type text, p_fiscal_year text, p_start_number integer, p_prefix text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant_id uuid;
  v_is_owner  boolean;
  v_prefix    text;
begin
  v_tenant_id := public.current_tenant_id();
  if v_tenant_id is null then raise exception 'No tenant context'; end if;

  select exists (
    select 1 from public.users
    where id = public.current_user_id() and tenant_id = v_tenant_id and role = 'owner'
  ) into v_is_owner;

  if not v_is_owner then
    raise exception 'Only tenant owners can modify document sequence';
  end if;

  v_prefix := coalesce(p_prefix, public.default_doc_prefix(p_doc_type));

  insert into public.document_series (tenant_id, doc_type, fiscal_year, prefix, last_number)
  values (v_tenant_id, p_doc_type, p_fiscal_year, v_prefix, p_start_number)
  on conflict (tenant_id, doc_type, fiscal_year)
  do update set last_number = excluded.last_number, prefix = excluded.prefix, updated_at = now();
end;
$function$;

-- public.set_my_employee
CREATE OR REPLACE FUNCTION public.set_my_employee(p_employee_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_user_email text; v_emp_email text;
begin
  select tenant_id, email into v_tenant, v_user_email from public.users where id = public.current_user_id();
  if v_tenant is null then raise exception 'No tenant for caller'; end if;
  if not exists (select 1 from public.employees where id = p_employee_id and tenant_id = v_tenant) then
    raise exception 'Employee not in your workspace';
  end if;
  if exists (select 1 from public.users where employee_id = p_employee_id and id <> public.current_user_id()) then
    raise exception 'Ye employee record kisi aur user se already linked hai — owner se kaho.';
  end if;
  select email into v_emp_email from public.employees where id = p_employee_id;
  if v_emp_email is not null and lower(v_emp_email) <> lower(coalesce(v_user_email, '')) then
    raise exception 'Aapka login email is employee se match nahi karta — owner se kaho ki Employees me aapko link kare.';
  end if;
  update public.users set employee_id = p_employee_id where id = public.current_user_id();
end $function$;

-- public.settle_reimbursement
CREATE OR REPLACE FUNCTION public.settle_reimbursement(p_id uuid, p_settled_on date, p_notes text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := public.current_tenant_id();
  v_r      public.reimbursements;
begin
  select * into v_r from public.reimbursements where id = p_id;
  if not found then raise exception 'Reimbursement not found'; end if;
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated')) or (v_tenant is not null and v_r.tenant_id is distinct from v_tenant) then
    raise exception 'Not in your tenant' using errcode = 'insufficient_privilege';
  end if;
  update public.reimbursements
     set status = 'settled', settled_on = coalesce(p_settled_on, current_date),
         settled_notes = nullif(trim(coalesce(p_notes, '')), '')
   where id = p_id;
end;
$function$;

-- public.sync_partner_item
CREATE OR REPLACE FUNCTION public.sync_partner_item(p_partner_item_id text, p_my_msrp integer DEFAULT NULL::integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_child_tenant uuid;
  v_parent_tenant uuid;
  v_parent items%rowtype;
  v_short text;
  v_new_id text;
  v_existing_id text;
  v_msrp integer;
begin
  select u.tenant_id, t.parent_tenant_id
    into v_child_tenant, v_parent_tenant
  from public.users u
  join public.tenants t on t.id = u.tenant_id
  where u.id = public.current_user_id()
  limit 1;

  if v_parent_tenant is null then
    raise exception 'Your tenant is not linked to a distributor — cannot sync partner items';
  end if;

  select * into v_parent
  from public.items
  where id = p_partner_item_id
    and tenant_id = v_parent_tenant
    and is_partner_visible = true
    and is_active = true;

  if not found then
    raise exception 'Partner item % not found or not visible to your tenant', p_partner_item_id;
  end if;

  v_msrp := coalesce(p_my_msrp, v_parent.msrp);
  v_short := substr(v_child_tenant::text, 1, 3);

  select id into v_existing_id
  from public.items
  where tenant_id = v_child_tenant
    and synced_from_partner_id = p_partner_item_id
  limit 1;

  if v_existing_id is not null then
    update public.items
      set wholesale = v_parent.partner_price,
          msrp      = case when p_my_msrp is not null then p_my_msrp else msrp end,
          prices    = v_parent.prices,
          is_active = true,
          name      = v_parent.name,
          vendor    = v_parent.vendor,
          kind      = v_parent.kind,
          hsn       = v_parent.hsn
      where id = v_existing_id;
    return v_existing_id;
  end if;

  v_new_id := regexp_replace(p_partner_item_id, '-[a-f0-9]{2,}$', '') || '-' || v_short;
  if exists (select 1 from public.items where id = v_new_id) then
    v_new_id := v_new_id || '-' || substr(md5(random()::text), 1, 4);
  end if;

  insert into public.items (
    id, tenant_id, name, vendor, kind, hsn,
    msrp, wholesale, prices, is_active,
    synced_from_partner_id, is_partner_visible, partner_price
  ) values (
    v_new_id, v_child_tenant, v_parent.name, v_parent.vendor, v_parent.kind, v_parent.hsn,
    v_msrp, v_parent.partner_price, v_parent.prices, true,
    p_partner_item_id, false, null
  );

  return v_new_id;
end $function$;

-- public.sync_partner_item
CREATE OR REPLACE FUNCTION public.sync_partner_item(p_partner_item_id text, p_my_msrp integer DEFAULT NULL::integer, p_link_existing_id text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_child_tenant  uuid;
  v_parent_tenant uuid;
  v_parent        items%rowtype;
  v_short         text;
  v_new_id        text;
  v_existing_id   text;
begin
  select u.tenant_id, t.parent_tenant_id
    into v_child_tenant, v_parent_tenant
  from public.users u
  join public.tenants t on t.id = u.tenant_id
  where u.id = public.current_user_id()
  limit 1;

  if v_parent_tenant is null then
    raise exception 'Your tenant is not linked to a distributor — cannot sync partner items';
  end if;

  select * into v_parent
  from public.items
  where id = p_partner_item_id
    and tenant_id = v_parent_tenant
    and is_partner_visible = true
    and is_active = true;

  if not found then
    raise exception 'Partner item % not found or not visible to your tenant', p_partner_item_id;
  end if;

  v_short := substr(v_child_tenant::text, 1, 3);

  -- 1. Caller asked to link a specific existing row → trust it (verify ownership).
  if p_link_existing_id is not null then
    if not exists (
      select 1 from public.items
      where id = p_link_existing_id and tenant_id = v_child_tenant
    ) then
      raise exception 'Cannot link to item % — not in your tenant', p_link_existing_id;
    end if;
    update public.items
      set synced_from_partner_id = p_partner_item_id,
          wholesale              = v_parent.partner_price,
          msrp                   = case when p_my_msrp is not null then p_my_msrp else msrp end,
          is_active              = true
      where id = p_link_existing_id and tenant_id = v_child_tenant;
    return p_link_existing_id;
  end if;

  -- 2. Already synced from this exact parent → refresh.
  select id into v_existing_id
  from public.items
  where tenant_id = v_child_tenant
    and synced_from_partner_id = p_partner_item_id
  limit 1;

  if v_existing_id is not null then
    update public.items
      set wholesale = v_parent.partner_price,
          msrp      = case when p_my_msrp is not null then p_my_msrp else msrp end,
          prices    = v_parent.prices,
          is_active = true,
          name      = v_parent.name,
          vendor    = v_parent.vendor,
          kind      = v_parent.kind,
          hsn       = v_parent.hsn
      where id = v_existing_id;
    return v_existing_id;
  end if;

  -- 3. New clone.
  v_new_id := regexp_replace(p_partner_item_id, '-[a-f0-9]{2,}$', '') || '-' || v_short;
  if exists (select 1 from public.items where id = v_new_id) then
    v_new_id := v_new_id || '-' || substr(md5(random()::text), 1, 4);
  end if;

  insert into public.items (
    id, tenant_id, name, vendor, kind, hsn,
    msrp, wholesale, prices, is_active,
    synced_from_partner_id, is_partner_visible, partner_price
  ) values (
    v_new_id, v_child_tenant, v_parent.name, v_parent.vendor, v_parent.kind, v_parent.hsn,
    coalesce(p_my_msrp, v_parent.msrp), v_parent.partner_price, v_parent.prices, true,
    p_partner_item_id, false, null
  );

  return v_new_id;
end $function$;

-- public.tg_academy_phase2_same_tenant
CREATE OR REPLACE FUNCTION public.tg_academy_phase2_same_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from public.academy_apprentices where id = new.apprentice_id and tenant_id = new.tenant_id) then
    raise exception 'That apprentice is not in this company.' using errcode = '23514';
  end if;
  -- Nested, not "and": PL/pgSQL may evaluate both sides, and an evaluation row has no skill_id.
  if tg_table_name = 'academy_apprentice_skills' then
    if not exists (select 1 from public.academy_skills where id = new.skill_id and tenant_id = new.tenant_id) then
      raise exception 'That skill is not in this company.' using errcode = '23514';
    end if;
  end if;
  new.updated_at := now();
  if public.current_user_id() is not null then
    if tg_table_name = 'academy_apprentice_skills' then new.updated_by := public.current_user_id(); end if;
    if tg_table_name = 'academy_evaluations' and tg_op = 'INSERT' then new.evaluated_by := public.current_user_id(); end if;
  end if;
  return new;
end $function$;

-- public.tg_books_locked
CREATE OR REPLACE FUNCTION public.tg_books_locked()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_col   text := tg_argv[0];
  v_lock  date;
  v_old   date;
  v_new   date;
  v_tenant uuid;
begin
  if coalesce(public.current_request_role(), '') not in ('anon', 'authenticated') then
    if tg_op = 'DELETE' then return old; else return new; end if;
  end if;

  if tg_op in ('UPDATE', 'DELETE') then
    v_old := left(to_jsonb(old) ->> v_col, 10)::date;
    v_tenant := (to_jsonb(old) ->> 'tenant_id')::uuid;
  end if;
  if tg_op in ('INSERT', 'UPDATE') then
    v_new := left(to_jsonb(new) ->> v_col, 10)::date;
    v_tenant := coalesce(v_tenant, (to_jsonb(new) ->> 'tenant_id')::uuid);
  end if;

  select books_locked_until into v_lock from public.tenants where id = v_tenant;
  if v_lock is not null and ((v_old is not null and v_old <= v_lock) or (v_new is not null and v_new <= v_lock)) then
    raise exception 'Books % tak lock hain (% · %). Us tareekh tak ki entry badal nahi sakti — pehle Accounting → Overview par lock hatao, ya entry ko baad ki tareekh par karo.',
      to_char(v_lock, 'DD Mon YYYY'), tg_table_name, coalesce(v_old, v_new)
      using errcode = 'check_violation';
  end if;

  if tg_op = 'DELETE' then return old; else return new; end if;
end $function$;

-- public.today_inbox
CREATE OR REPLACE FUNCTION public.today_inbox()
 RETURNS TABLE(kind text, id text, title text, due_at timestamp with time zone, priority integer, href text)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
  with me as (
    select u.id as uid, u.tenant_id, u.role::text as role,
           (now() at time zone 'Asia/Kolkata')::date as today_ist,
           /* End of the IST day, as an instant. */
           (((now() at time zone 'Asia/Kolkata')::date + 1)::timestamp at time zone 'Asia/Kolkata') as eod
      from public.users u
     where u.id = public.current_user_id()
       and u.tenant_id = public.current_tenant_id()
  ),
  items (kind, id, title, due_at, priority, href) as (
    -- 1. My tasks — overdue or due by the end of today.
    (select 'task'::text, t.id::text, t.title, t.due_at,
            case when t.due_at < now() then 70 else 55 end, '/tasks'::text
       from public.tasks t, me
      where t.tenant_id = me.tenant_id
        and t.owner_id = me.uid
        and t.status in ('pending', 'snoozed')
        and t.due_at < me.eod
      order by t.due_at
      limit 50)

    union all
    -- 2. Enquiries — unread, still in the Inbox (not done, not snoozed, not machine mail).
    (select 'enquiry', e.id::text,
            'Enquiry: ' || coalesce(nullif(e.subject, ''), '(no subject)')
              || ' — ' || coalesce(nullif(e.from_name, ''), e.from_email, 'unknown sender'),
            e.created_at, 60, '/enquiries'
       from public.inbound_emails e, me
      where e.tenant_id = me.tenant_id
        and e.status in ('received', 'lead_created', 'appended_to_lead')
        and e.read_at is null
        and e.archived_at is null
        and (e.snoozed_until is null or e.snoozed_until <= now())
        and e.created_at > now() - interval '14 days'
      order by e.created_at
      limit 50)

    union all
    -- 3. WhatsApp — conversations whose LAST message is theirs, in the last 7 days.
    (select 'whatsapp', w.contact_phone,
            'WhatsApp from ' || w.contact_phone || coalesce(': ' || left(w.text_body, 60), ''),
            w.created_at, 60, '/whatsapp'
       from (select distinct on (m.contact_phone) m.contact_phone, m.direction, m.text_body, m.created_at
               from public.whatsapp_messages m, me
              where m.tenant_id = me.tenant_id
                and m.created_at > now() - interval '7 days'
              order by m.contact_phone, m.created_at desc) w
      where w.direction = 'inbound'
      order by w.created_at
      limit 50)

    union all
    -- 4. Support tickets we owe a move on (awaiting_customer is THEIR move).
    (select 'support', s.id,
            'Ticket ' || s.id || ': ' || coalesce(s.subject, '') || coalesce(' — ' || s.customer_name, ''),
            s.sla_due_at,
            case when s.sla_due_at < now() then 80
                 when s.priority in ('urgent', 'high') then 65
                 else 55 end,
            '/support'
       from public.support_tickets s, me
      where s.tenant_id = me.tenant_id
        and s.status in ('open', 'in_progress')
      order by s.sla_due_at nulls last
      limit 50)

    union all
    -- 5. Automation held for a human, last 7 days (the /automation "waiting on you" list).
    (select 'automation', a.id::text,
            'Held for you: ' || a.action || coalesce(' — ' || a.reason, ''),
            a.created_at, 50, '/automation'
       from public.ai_action_log a, me
      where a.tenant_id = me.tenant_id
        and a.outcome = 'held'
        and a.created_at > now() - interval '7 days'
      order by a.created_at
      limit 50)

    union all
    -- 6. Activation queue — paid for, not switched on.
    (select 'provisioning', p.id::text,
            case when p.status = 'failed' then 'Activation FAILED: ' else 'Activate: ' end
              || p.seats || ' × ' || coalesce(p.plan, p.vendor) || coalesce(' for ' || p.domain, ''),
            p.created_at,
            case when p.status = 'failed' then 90
                 when p.created_at < now() - interval '24 hours' then 85
                 else 75 end,
            '/provisioning'
       from public.provisioning_requests p, me
      where p.tenant_id = me.tenant_id
        and p.status in ('queued', 'failed')
      order by p.created_at
      limit 50)

    union all
    -- 7. Purchases inbox — vendor order mails not yet booked.
    (select 'purchase_inbox', ip.id::text,
            'Book purchase: ' || coalesce(nullif(ip.subject, ''), ip.source)
              || coalesce(' · ₹' || to_char(ip.total, 'FM99,99,99,99,999'), ''),
            ip.created_at, 30, '/purchases/inbox'
       from public.inbound_purchases ip, me
      where ip.tenant_id = me.tenant_id
        and ip.status = 'pending'
      order by ip.created_at
      limit 50)

    union all
    -- 8a. Quotes waiting on MY approval — mirrors useNavBadges / awaitsMyApproval:
    --     pending, not raised by me, and a tier my role may clear.
    (select 'approval', q.id,
            'Approve quote ' || q.id || coalesce(' — ' || q.customer_name, '')
              || coalesce(' · ₹' || to_char(q.amount, 'FM99,99,99,99,999'), ''),
            q.approval_requested_at, 70, '/quotes/' || q.id
       from public.quotes q, me
      where q.tenant_id = me.tenant_id
        and q.approval_status = 'pending'
        and q.approval_requested_by is distinct from me.uid
        and ( (q.approval_tier = 'owner'   and me.role = 'owner')
           or (q.approval_tier = 'manager' and me.role in ('owner', 'manager')) )
      order by q.approval_requested_at
      limit 50)

    union all
    -- 8b. Seat-change requests from customers (decided on /subscriptions).
    (select 'approval', sr.id::text,
            'Seat change: ' || coalesce(sr.customer_name, 'customer') || ' '
              || sr.current_seats || ' → ' || sr.requested_seats,
            sr.created_at, 60, '/subscriptions'
       from public.seat_requests sr, me
      where sr.tenant_id = me.tenant_id
        and sr.status = 'pending'
        and me.role in ('owner', 'manager', 'billing')
      order by sr.created_at
      limit 50)

    union all
    -- 8c. Expense claims against an advance, waiting for a decision.
    (select 'approval', ec.id::text,
            'Expense claim: ₹' || to_char(ec.amount, 'FM99,99,99,99,999') || coalesce(' — ' || ec.purpose, ''),
            ec.created_at, 40, '/accounting/loans'
       from public.expense_claims ec, me
      where ec.tenant_id = me.tenant_id
        and ec.status = 'pending'
        and me.role in ('owner', 'manager')
      order by ec.created_at
      limit 50)

    union all
    -- 9. Join requests — somebody signed up with our domain and is waiting to be let in.
    (select 'join_request', jr.id::text,
            'Join request: ' || coalesce(nullif(jr.full_name, ''), jr.email) || ' (' || jr.email || ')',
            jr.created_at, 65, '/team'
       from public.join_requests jr, me
      where jr.tenant_id = me.tenant_id
        and jr.status = 'pending_approval'
        and me.role in ('owner', 'manager')
      order by jr.created_at
      limit 50)

    union all
    -- 10. Renewals in the next 14 days (or already past) that nobody has renewed.
    (select 'renewal', su.id::text,
            'Renewal: ' || coalesce(su.customer_name, '') || ' · ' || coalesce(su.plan, '')
              || coalesce(' · ' || su.domain, '') || ' on ' || to_char(su.renewal_date, 'DD Mon'),
            (su.renewal_date::timestamp at time zone 'Asia/Kolkata'),
            case when su.renewal_date <= me.today_ist + 3 then 75
                 when su.renewal_date <= me.today_ist + 7 then 60
                 else 45 end,
            '/renewals'
       from public.subscriptions su, me
      where su.tenant_id = me.tenant_id
        and su.status = 'active'
        and su.renewal_date <= me.today_ist + 14
        and su.renewal_state is distinct from 'renewed'
      order by su.renewal_date
      limit 50)

    union all
    -- 11. Overdue invoices — unpaid and past their due date (IST).
    (select 'invoice_overdue', i.id,
            'Overdue ' || (me.today_ist - i.due_date) || 'd: ' || i.id || coalesce(' — ' || i.customer_name, '')
              || ' (invoice ₹' || to_char(i.amount, 'FM99,99,99,99,999') || ')',
            (i.due_date::timestamp at time zone 'Asia/Kolkata'),
            case when i.due_date < me.today_ist - 30 then 80 else 72 end,
            '/invoices/' || i.id
       from public.invoices i, me
      where i.tenant_id = me.tenant_id
        and i.status in ('pending', 'overdue')
        and i.due_date < me.today_ist
      order by i.due_date
      limit 50)

    union all
    -- 12. Autopay stopped — Razorpay halted the mandate (repeated failed charges) or it is
    --     stuck pending. The only durable record of a failed payment this schema keeps:
    --     the webhook ignores one-off `payment.failed` events (webhooks/razorpay/route.ts).
    (select 'payment_failed', pm.id::text,
            'Autopay stopped: ' || coalesce(c.name, 'customer') || coalesce(' — ' || pm.status_note, ''),
            pm.updated_at, 85, '/subscriptions'
       from public.payment_mandates pm
       join me on pm.tenant_id = me.tenant_id
       left join public.customers c on c.id = pm.customer_id and c.tenant_id = pm.tenant_id
      where pm.status = 'paused'
        and coalesce(pm.test_mode, false) = false
      order by pm.updated_at
      limit 50)
  )
  select i.kind, i.id, i.title, i.due_at, i.priority, i.href from items i
   order by i.priority desc, i.due_at asc nulls last, i.kind, i.id;
$function$;

-- public.undo_my_last_punch
CREATE OR REPLACE FUNCTION public.undo_my_last_punch()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_emp uuid; v_date date; v_row public.attendance;
begin
  select tenant_id, employee_id into v_tenant, v_emp from public.users where id = public.current_user_id();
  if v_emp is null then raise exception 'Pehle apna employee link karo.'; end if;
  v_date := (now() at time zone 'Asia/Kolkata')::date;
  select * into v_row from public.attendance where tenant_id = v_tenant and employee_id = v_emp and work_date = v_date;
  if not found then raise exception 'Aaj ka koi attendance record nahi.'; end if;

  if v_row.check_out is not null then
    if now() - v_row.check_out > interval '15 minutes' then
      raise exception 'Undo ka 15-min time nikal gaya — owner se correction karao.';
    end if;
    update public.attendance set check_out = null, selfie_out = null, geo_out = null, check_out_device = null where id = v_row.id;
    return 'undo_checkout';
  else
    if now() - v_row.check_in > interval '15 minutes' then
      raise exception 'Undo ka 15-min time nikal gaya — owner se correction karao.';
    end if;
    delete from public.attendance where id = v_row.id;
    return 'undo_checkin';
  end if;
end $function$;

-- public.update_project_details
CREATE OR REPLACE FUNCTION public.update_project_details(p_project_id uuid, p_title text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_customer_id uuid DEFAULT NULL::uuid, p_customer_name text DEFAULT NULL::text, p_total_amount integer DEFAULT NULL::integer, p_gst_rate integer DEFAULT NULL::integer, p_inter_state boolean DEFAULT NULL::boolean, p_milestones jsonb DEFAULT NULL::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant      uuid := public.current_tenant_id();
  v_proj        public.project_sales;
  v_locked_sum  integer := 0;
  v_max_seq     integer := 0;
  v_invoiced    integer := 0;
  v_paid        integer := 0;
  v_new_total   integer;
  v_rate        integer;
  v_taxable     integer;
  v_gst         integer;
  v_new_sum     integer := 0;
  v_seq         integer;
  v_m           jsonb;
begin
  select * into v_proj from public.project_sales where id = p_project_id for update;
  if not found then
    raise exception 'Project not found';
  end if;
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated')) or (v_tenant is not null and v_proj.tenant_id is distinct from v_tenant) then
    raise exception 'Not in the caller tenant' using errcode = 'insufficient_privilege';
  end if;

  -- What is already committed. "Locked" means invoiced OR paid, exactly as
  -- update_project_future_milestones defines it.
  select coalesce(sum(m.total_amount), 0), coalesce(max(m.seq), 0)
    into v_locked_sum, v_max_seq
  from public.project_milestones m
  where m.project_id = p_project_id
    and (m.invoice_id is not null
         or exists (select 1 from public.project_payments p where p.milestone_id = m.id));

  select count(*) into v_invoiced
    from public.project_milestones m
   where m.project_id = p_project_id and m.invoice_id is not null;

  select coalesce(sum(p.amount), 0) into v_paid
    from public.project_payments p where p.project_id = p_project_id;

  -- Customer -----------------------------------------------------------------
  if p_customer_id is not null and p_customer_id is distinct from v_proj.customer_id then
    if v_invoiced > 0 then
      raise exception
        'This project already has % tax invoice(s), issued to "%". Changing the customer now would leave those invoices pointing at a different party. Raise a credit note against them first, then invoice the correct customer.',
        v_invoiced, coalesce(v_proj.customer_name, 'the current customer')
        using errcode = 'invalid_parameter_value';
    end if;
    update public.project_sales
       set customer_id   = p_customer_id,
           customer_name = coalesce(p_customer_name, customer_name)
     where id = p_project_id;
  elsif p_customer_name is not null then
    update public.project_sales set customer_name = p_customer_name where id = p_project_id;
  end if;

  -- Title / description --------------------------------------------------------
  if p_title is not null then
    if length(btrim(p_title)) < 2 then
      raise exception 'A project needs a title of at least 2 characters.'
        using errcode = 'invalid_parameter_value';
    end if;
    update public.project_sales set title = btrim(p_title) where id = p_project_id;
  end if;
  if p_description is not null then
    update public.project_sales
       set description = nullif(btrim(p_description), '')
     where id = p_project_id;
  end if;

  -- Money ----------------------------------------------------------------------
  v_new_total := coalesce(p_total_amount, v_proj.total_amount);
  v_rate      := coalesce(p_gst_rate, v_proj.gst_rate, 18);

  if v_new_total <= 0 then
    raise exception 'A contract value must be more than zero.'
      using errcode = 'invalid_parameter_value';
  end if;

  -- Rule 1. Below what is already committed the schedule cannot be satisfied.
  if v_new_total < greatest(v_locked_sum, v_paid) then
    raise exception
      'The new value Rs % is below what is already invoiced or paid (Rs %). Reduce it only to that figure or above - to go lower, credit-note the invoices first.',
      v_new_total, greatest(v_locked_sum, v_paid)
      using errcode = 'invalid_parameter_value';
  end if;

  v_taxable := round(v_new_total * 100.0 / (100 + v_rate));
  v_gst     := v_new_total - v_taxable;

  update public.project_sales
     set total_amount   = v_new_total,
         taxable_amount = v_taxable,
         gst_amount     = v_gst,
         gst_rate       = v_rate,
         inter_state    = coalesce(p_inter_state, inter_state),
         updated_at     = now()
   where id = p_project_id;

  -- Re-plan the milestones that are not locked ---------------------------------
  -- NULL means "leave the schedule alone" - a title-only edit must not touch it.
  if p_milestones is not null then
    for v_m in select * from jsonb_array_elements(p_milestones) loop
      v_new_sum := v_new_sum + greatest(coalesce((v_m->>'total_amount')::integer, 0), 0);
    end loop;

    if v_locked_sum + v_new_sum <> v_new_total then
      raise exception
        'Schedule must total Rs %. Rs % is already invoiced or paid and fixed, so the remaining milestones must add up to Rs %.',
        v_new_total, v_locked_sum, (v_new_total - v_locked_sum)
        using errcode = 'invalid_parameter_value';
    end if;

    delete from public.project_milestones m
     where m.project_id = p_project_id
       and m.invoice_id is null
       and not exists (select 1 from public.project_payments p where p.milestone_id = m.id);

    v_seq := v_max_seq;
    for v_m in select * from jsonb_array_elements(p_milestones) loop
      v_seq := v_seq + 1;
      insert into public.project_milestones (tenant_id, project_id, seq, label, total_amount, due_date, status)
      values (v_proj.tenant_id, p_project_id, v_seq,
              coalesce(nullif(btrim(v_m->>'label'), ''), 'Milestone ' || v_seq),
              greatest(coalesce((v_m->>'total_amount')::integer, 0), 0),
              nullif(v_m->>'due_date', '')::date,
              'pending');
    end loop;
  elsif p_total_amount is not null and p_total_amount <> v_proj.total_amount then
    -- The value moved and no schedule came with it. Refusing is better than leaving a
    -- schedule that no longer adds up: every screen reading the project would show a
    -- total the milestones disagree with, and nothing would say why.
    raise exception
      'The contract value changed but no milestone schedule was sent, so the instalments would no longer add up to it. Re-plan the remaining milestones in the same save.'
      using errcode = 'invalid_parameter_value';
  end if;
end;
$function$;

-- public.update_project_future_milestones
CREATE OR REPLACE FUNCTION public.update_project_future_milestones(p_project_id uuid, p_milestones jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant     uuid := public.current_tenant_id();
  v_proj       public.project_sales;
  v_locked_sum integer := 0;
  v_max_seq    integer := 0;
  v_new_sum    integer := 0;
  v_seq        integer;
  v_m          jsonb;
begin
  select * into v_proj from public.project_sales where id = p_project_id;
  if not found then raise exception 'Project not found'; end if;
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated')) or (v_tenant is not null and v_proj.tenant_id is distinct from v_tenant) then
    raise exception 'Not in caller''s tenant' using errcode = 'insufficient_privilege';
  end if;

  select coalesce(sum(m.total_amount), 0), coalesce(max(m.seq), 0)
    into v_locked_sum, v_max_seq
  from public.project_milestones m
  where m.project_id = p_project_id
    and (m.invoice_id is not null
         or exists (select 1 from public.project_payments p where p.milestone_id = m.id));

  for v_m in select * from jsonb_array_elements(coalesce(p_milestones, '[]'::jsonb)) loop
    v_new_sum := v_new_sum + greatest(coalesce((v_m->>'total_amount')::integer, 0), 0);
  end loop;

  if v_locked_sum + v_new_sum <> v_proj.total_amount then
    raise exception 'Schedule must total %. Rupees % is already invoiced/paid and fixed, so the remaining milestones must add up to Rupees %.',
      v_proj.total_amount, v_locked_sum, (v_proj.total_amount - v_locked_sum)
      using errcode = 'invalid_parameter_value';
  end if;

  delete from public.project_milestones m
  where m.project_id = p_project_id
    and m.invoice_id is null
    and not exists (select 1 from public.project_payments p where p.milestone_id = m.id);

  v_seq := v_max_seq;
  for v_m in select * from jsonb_array_elements(coalesce(p_milestones, '[]'::jsonb)) loop
    v_seq := v_seq + 1;
    insert into public.project_milestones (tenant_id, project_id, seq, label, total_amount, due_date, status)
    values (v_proj.tenant_id, p_project_id, v_seq,
            coalesce(v_m->>'label', 'Milestone ' || v_seq),
            greatest(coalesce((v_m->>'total_amount')::integer, 0), 0),
            nullif(v_m->>'due_date', '')::date,
            'pending');
  end loop;

  update public.project_sales set updated_at = now() where id = p_project_id;
end;
$function$;

-- public.update_project_quote
CREATE OR REPLACE FUNCTION public.update_project_quote(p_project_id uuid, p_customer_name text, p_title text, p_description text, p_line_items jsonb, p_gst_rate integer, p_inter_state boolean, p_milestones jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant  uuid := public.current_tenant_id();
  v_proj    public.project_sales;
  v_taxable integer := 0;
  v_gst     integer;
  v_li      jsonb;
  v_m       jsonb;
  v_seq     integer := 0;
begin
  select * into v_proj from public.project_sales where id = p_project_id;
  if not found then raise exception 'Project not found'; end if;
  if (v_tenant is null and coalesce(public.current_request_role(), '') in ('anon', 'authenticated')) or (v_tenant is not null and v_proj.tenant_id is distinct from v_tenant) then
    raise exception 'Not in caller''s tenant' using errcode = 'insufficient_privilege';
  end if;
  if exists (select 1 from public.project_milestones where project_id = p_project_id and invoice_id is not null) then
    raise exception 'Can''t edit — a milestone is already invoiced. Delete that invoice first.'
      using errcode = 'invalid_parameter_value';
  end if;
  if exists (select 1 from public.project_payments where project_id = p_project_id) then
    raise exception 'Can''t edit — payments are recorded. Remove them first.'
      using errcode = 'invalid_parameter_value';
  end if;

  for v_li in select * from jsonb_array_elements(coalesce(p_line_items, '[]'::jsonb)) loop
    v_taxable := v_taxable + greatest(coalesce((v_li->>'amount')::integer, 0), 0);
  end loop;
  if v_taxable <= 0 then raise exception 'Needs at least one line item'; end if;
  v_gst := round(v_taxable * coalesce(p_gst_rate, 18) / 100.0);

  update public.project_sales
     set customer_name  = p_customer_name,
         title          = p_title,
         description    = nullif(trim(coalesce(p_description,'')),''),
         gst_rate       = coalesce(p_gst_rate, 18),
         inter_state    = coalesce(p_inter_state, false),
         line_items     = coalesce(p_line_items, '[]'::jsonb),
         taxable_amount = v_taxable,
         gst_amount     = v_gst,
         total_amount   = v_taxable + v_gst,
         updated_at     = now()
   where id = p_project_id;

  delete from public.project_milestones where project_id = p_project_id;
  for v_m in select * from jsonb_array_elements(coalesce(p_milestones, '[]'::jsonb)) loop
    v_seq := v_seq + 1;
    insert into public.project_milestones (tenant_id, project_id, seq, label, total_amount, due_date)
    values (v_proj.tenant_id, p_project_id, v_seq,
            coalesce(v_m->>'label', 'Milestone ' || v_seq),
            greatest(coalesce((v_m->>'total_amount')::integer, 0), 0),
            nullif(v_m->>'due_date','')::date);
  end loop;
end;
$function$;

-- public.visible_owner_ids
CREATE OR REPLACE FUNCTION public.visible_owner_ids()
 RETURNS uuid[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ select coalesce(array_agg(t.id), '{}'::uuid[]) from public.get_subordinate_user_ids(public.current_user_id()) as t(id) $function$;

-- ─── 4. Nothing may still read the JWT directly ─────────────────────────────
do $$
declare n int;
begin
  select count(*) into n from pg_policies
   where coalesce(qual,'') || coalesce(with_check,'') ~ 'auth\.(uid|role)\(\)';
  if n > 0 then raise exception 'tenant_context: % policies still use auth.uid()/auth.role()', n; end if;

  select count(*) into n from pg_proc p join pg_namespace s on s.oid = p.pronamespace
   where s.nspname in ('public','storage') and p.prosrc ~ 'auth\.(uid|role)\(\)'
     and p.proname not in ('current_user_id','current_request_role','current_tenant_id');
  if n > 0 then raise exception 'tenant_context: % functions still use auth.uid()/auth.role()', n; end if;
end $$;

commit;
